        }

        public MainWindow()
        {
            LogException("StartupTrace", new Exception("MainWindow ctor begin"));
            InitializeComponent();
            AddHandler(UIElement.PreviewMouseLeftButtonDownEvent, new MouseButtonEventHandler(MainWindow_PreviewMouseLeftButtonDown), true);
            _dashboardRefreshTimer.Tick += DashboardRefreshTimer_Tick;
            if (DashboardPendingDispatchGrid != null) DashboardPendingDispatchGrid.ItemsSource = _dashboardPendingDispatchEntries;
            if (DashboardInTransitGrid != null) DashboardInTransitGrid.ItemsSource = _dashboardInTransitEntries;
            Closed += (s, e) =>
            {
                _dashboardRefreshTimer.Stop();
                _connectionStatusTimer?.Stop();
            };
            LogException("StartupTrace", new Exception("MainWindow InitializeComponent complete"));
            try
            {
                var ver = Assembly.GetExecutingAssembly().GetName().Version;
                if (AppVersionText != null && ver != null)
                {
                    AppVersionText.Text = $"v {ver.Major}.{ver.Minor}.{ver.Build}";
                }
            }
            catch (Exception ex) { LogException(nameof(MainWindow), ex); }
            ValidateRuntimeAssets();
            LogException("StartupTrace", new Exception("ValidateRuntimeAssets complete"));
            try
            {
                LogException("StartupTrace", new Exception("Creating ChallanViewModel"));
                DataContext = new ChallanViewModel();
                LogException("StartupTrace", new Exception("Creating LRLedgerViewModel"));
                LRVM = new LRLedgerViewModel();
                LogException("StartupTrace", new Exception("Creating TrackingViewModel"));
                TrackingVM = new TrackingViewModel(loadOnStartup: false);
                LogException("StartupTrace", new Exception("Creating BillLedgerViewModel"));
                BillVM = new ViewModels.BillLedgerViewModel();
                LogException("StartupTrace", new Exception("ViewModels created"));
            }
            catch (Exception ex)
            {
                LogException("StartupTrace", ex);
                throw;
            }

            // Debounce timer for search boxes
            _searchTimer = new System.Windows.Threading.DispatcherTimer();
            _searchTimer.Interval = TimeSpan.FromMilliseconds(300);
            _searchTimer.Tick += SearchTimer_Tick;

            // Debounce timer for Challan filter fields
            _challanFilterTimer = new System.Windows.Threading.DispatcherTimer();
            _challanFilterTimer.Interval = TimeSpan.FromMilliseconds(300);
            _challanFilterTimer.Tick += ChallanFilterTimer_Tick;

            if (VM != null) VM.PropertyChanged += VM_PropertyChanged;

            this.Closing += (s, e) => SaveGridSettings();

            Loaded += (s, e) =>
            {
                LogException("StartupTrace", new Exception("MainWindow Loaded begin"));
                try
                {
                    if (PageTitle != null) PageTitle.Text = "Dashboard";
                    LoadGridSettings();
                    ApplyCurrentUserAccess();

                    if (LRLedgerGrid != null)
                    {
                        if (LRLedgerView.DataContext == null) LRLedgerView.DataContext = LRVM;
                        EnforceLRLockedColumnsReadOnly();
                    }

                    if (TrackingLedgerGrid != null)
                    {
                        var trackingView = CollectionViewSource.GetDefaultView(TrackingLedgerGrid.ItemsSource) as System.Collections.Specialized.INotifyCollectionChanged;
                        if (trackingView != null) trackingView.CollectionChanged += (s2, e2) => QueueDashboardRefresh();
                    }

                    var view = System.Windows.Data.CollectionViewSource.GetDefaultView(LedgerGrid.ItemsSource) as System.Collections.Specialized.INotifyCollectionChanged;
                    if (view != null) view.CollectionChanged += (s2, e2) => { RefreshFilteredSummary(); QueueDashboardRefresh(); };

                    var lrView = LRLedgerGrid != null ? System.Windows.Data.CollectionViewSource.GetDefaultView(LRLedgerGrid.ItemsSource) as System.Collections.Specialized.INotifyCollectionChanged : null;
                    if (lrView != null) lrView.CollectionChanged += (s2, e2) => LRRefreshFilteredSummary();

                    DeferUi(() =>
                    {
                        try
                        {
                            UpdateColumnVisibility();
                            RestoreSortIndicator();
                            RefreshFilteredSummary();
                            RefreshDashboard();
                        }
                        catch (Exception ex)
                        {
                            LogException("MainWindow Loaded Deferred", ex);
                        }
                    }, System.Windows.Threading.DispatcherPriority.Background);

                    Task.Run(() =>
                    {
                        try
                        {
                            MasterDataCache.WarmUpRemote();

                            if (!_initialLrBackfillDone)
                            {
                                BackfillAllLinkedLREntriesFromChallans();
                                _initialLrBackfillDone = true;
                            }

                            SyncAllChallanBillingFromLR();
                            WarmBillDueCachesInBackground();
                            GetPendingBillPageCached(1, 200, allowStale: false);
                        }
                        catch (Exception ex)
                        {
                            LogException("MainWindow StartupBackground", ex);
                        }
                    });
                }
                catch (Exception ex)
                {
                    LogException("MainWindow Loaded", ex);
                }
                finally
                {
                    LogException("StartupTrace", new Exception("MainWindow Loaded end"));
                }
            };

            if (BackendSettings.UseRemoteApi)
            {
                _remoteSyncTimer = new System.Windows.Threading.DispatcherTimer();
                _remoteSyncTimer.Interval = TimeSpan.FromSeconds(12);
                _remoteSyncTimer.Tick += RemoteSyncTimer_Tick;
                _remoteSyncTimer.Start();
            }

            StartConnectionStatusMonitor();
        }

        private void StartConnectionStatusMonitor()
        {
            SetConnectionStatus(false, "Checking connection...");
            _connectionStatusTimer = new System.Windows.Threading.DispatcherTimer();
            _connectionStatusTimer.Interval = TimeSpan.FromSeconds(30);
            _connectionStatusTimer.Tick += (s, e) => UpdateConnectionStatusAsync();
            _connectionStatusTimer.Start();
            UpdateConnectionStatusAsync();
        }

        private void UpdateConnectionStatusAsync()
        {
            if (_connectionStatusCheckInProgress) return;
            _connectionStatusCheckInProgress = true;
            Task.Run(() =>
            {
                var connected = BackendSettings.UseRemoteApi ? IsRemoteApiHealthy() : HasInternetConnection();
                Dispatcher.BeginInvoke(new Action(() =>
                {
                    SetConnectionStatus(connected, connected ? "Connected" : "Not connected");
                    _connectionStatusCheckInProgress = false;
                }));
            });
        }

        private void SetConnectionStatus(bool connected, string tooltip)
        {
            if (ConnectionStatusDot == null) return;
            ConnectionStatusDot.Fill = new SolidColorBrush((Color)ColorConverter.ConvertFromString(connected ? "#16A34A" : "#DC2626"));
            var parent = ConnectionStatusDot.Parent as FrameworkElement;
            if (parent != null) parent.ToolTip = tooltip;
        }

        private bool IsOperatorRestricted()
        {
            return AuthSession.IsAuthenticated && !AuthSession.IsAdmin;
        }

        private void ApplyCurrentUserAccess()
        {
            try
            {
                var restrict = IsOperatorRestricted();
                if (SidebarImportButton != null) SidebarImportButton.Visibility = restrict ? Visibility.Collapsed : Visibility.Visible;
                if (SidebarExportButton != null) SidebarExportButton.Visibility = restrict ? Visibility.Collapsed : Visibility.Visible;
                if (SidebarReportsButton != null) SidebarReportsButton.Visibility = restrict ? Visibility.Collapsed : Visibility.Visible;
                if (SidebarUsersButton != null) SidebarUsersButton.Visibility = restrict ? Visibility.Collapsed : Visibility.Visible;
                if (TabPartyLedger != null) TabPartyLedger.Visibility = restrict ? Visibility.Collapsed : Visibility.Visible;
                if (TabVehicleLedger != null) TabVehicleLedger.Visibility = restrict ? Visibility.Collapsed : Visibility.Visible;
                if (TopResetDataButton != null) TopResetDataButton.Visibility = Visibility.Collapsed;
                if (LedgerResetDataButton != null) LedgerResetDataButton.Visibility = Visibility.Collapsed;
                if (ChallanImportButton != null) ChallanImportButton.Visibility = restrict ? Visibility.Collapsed : Visibility.Visible;
                if (ChallanImportGuideButton != null) ChallanImportGuideButton.Visibility = restrict ? Visibility.Collapsed : Visibility.Visible;
                if (ChallanDeleteButton != null) ChallanDeleteButton.Visibility = restrict ? Visibility.Collapsed : (_isChallanLedgerMode ? Visibility.Collapsed : Visibility.Visible);
                if (LRDeleteButton != null) LRDeleteButton.Visibility = restrict ? Visibility.Collapsed : Visibility.Visible;
                if (LRImportButton != null) LRImportButton.Visibility = restrict ? Visibility.Collapsed : Visibility.Visible;
                if (LRImportGuideButton != null) LRImportGuideButton.Visibility = restrict ? Visibility.Collapsed : Visibility.Visible;
                if (BillDeleteButton != null) BillDeleteButton.Visibility = restrict ? Visibility.Collapsed : Visibility.Visible;
                if (BillImportButton != null) BillImportButton.Visibility = restrict ? Visibility.Collapsed : Visibility.Visible;
                if (BillImportGuideButton != null) BillImportGuideButton.Visibility = restrict ? Visibility.Collapsed : Visibility.Visible;
                if (TrackingDeleteButton != null) TrackingDeleteButton.Visibility = restrict ? Visibility.Collapsed : Visibility.Visible;
                if (PartyImportButton != null) PartyImportButton.Visibility = restrict ? Visibility.Collapsed : Visibility.Visible;
                if (PartyDeleteButton != null) PartyDeleteButton.Visibility = restrict ? Visibility.Collapsed : Visibility.Visible;
                if (VehicleDeleteButton != null) VehicleDeleteButton.Visibility = restrict ? Visibility.Collapsed : Visibility.Visible;
                if (CBSDeleteButton != null) CBSDeleteButton.Visibility = restrict ? Visibility.Collapsed : Visibility.Visible;
            }
            catch (Exception ex)
            {
                AppLogger.LogException(nameof(ApplyCurrentUserAccess), ex);
            }
        }

        private bool EnsureAdminAccess(string featureName)
        {
            if (!IsOperatorRestricted())
            {
                return true;
            }

            MessageBox.Show(featureName + " is available only for admin users.", "Access Denied", MessageBoxButton.OK, MessageBoxImage.Information);
            return false;
        }

        private static bool HasInternetConnection()
        {
            try
            {
                using (var client = new System.Net.Http.HttpClient())
                {
                    client.Timeout = TimeSpan.FromSeconds(5);
                    var response = client.GetAsync("https://www.google.com/generate_204").GetAwaiter().GetResult();
                    return response.IsSuccessStatusCode || response.StatusCode == System.Net.HttpStatusCode.NoContent;
                }
            }
            catch
            {
                return false;
            }
        }

        private void RemoteSyncTimer_Tick(object sender, EventArgs e)
        {
            if (!IsLoaded || !IsVisible)
            {
                return;
            }

            // Skip sync while another owned window is active so we do not disturb in-progress edits.
            try
            {
                if (Application.Current != null)
                {
                    foreach (Window window in Application.Current.Windows)
                    {
                        if (window != null && window != this && window.IsVisible && window.IsActive)
                        {
                            return;
                        }
                    }
                }
            }
            catch
            {
                return;
            }

            try
            {
                RefreshFilteredSummary();
                LRRefreshFilteredSummary();
                BillUpdatePageUI();
                RefreshDashboard();
            }
            catch (Exception ex)
            {
                LogException(nameof(RemoteSyncTimer_Tick), ex);
            }
        }

        private void ValidateRuntimeAssets()
        {
            try
            {
                var baseDir = AppDomain.CurrentDomain.BaseDirectory ?? string.Empty;
                var required = new[]
                {
                    "logo.png",
                    "logo.ico",
                    "LR format.png",
                    "LR consginor.png",
                    "Lorry Lr.png",
                    "bill format.png"
                };

                foreach (var file in required)
                {
                    try
                    {
                        var path = System.IO.Path.Combine(baseDir, file);
                        if (!System.IO.File.Exists(path))
                        {
                            LogException("AssetMissing", new System.IO.FileNotFoundException($"Missing asset: {file}", path));
                        }
                    }
                    catch (Exception ex)
                    {
                        LogException("ValidateRuntimeAssets", ex);
                    }
                }
            }
            catch (Exception ex)
            {
                LogException(nameof(ValidateRuntimeAssets), ex);
            }
        }

        private void VM_PropertyChanged(object sender, PropertyChangedEventArgs e)
        {
            if (e.PropertyName != null && e.PropertyName.StartsWith("Show"))
            {
                UpdateColumnVisibility();
                VM?.SaveColumnSettings();
            }
        }

        private void RefreshDashboard()
        {
            if (!IsDashboardVisible())
            {
                return;
            }

            var refreshVersion = Interlocked.Increment(ref _dashboardRefreshVersion);
            Task.Run(() =>
            {
                try
                {
                    int trackingReminderCount = 0;
                    var dashboardSummaryApplied = false;

                    if (BackendSettings.UseRemoteApi)
                    {
                        try
                        {
                            var summary = RemoteApiClient.Get<DashboardSummary>("api/dashboard/summary");
                            ApplyDashboardSummary(summary);
                            dashboardSummaryApplied = true;
                        }
                        catch (Exception summaryEx)
                        {
                            LogException("RefreshDashboard.RemoteSummary", summaryEx);
                            // Older API deployments do not have the summary endpoint. Fall back to
                            // repository calculations so dashboard cards never remain at startup zero.
                        }
                    }

                    var trackingEntries = LoadTrackingEntriesForDashboard();
                    long dueChallans = 0;
                    decimal totalDue = 0m;

                    var tomorrow = DateTime.Today.AddDays(1);
                    trackingReminderCount = trackingEntries.Count(x =>
                        x.EwayBillTillDate.HasValue &&
                        x.EwayBillTillDate.Value.Date <= tomorrow &&
                        !x.DeliveredDate.HasValue);

                    var pendingDispatchRows = trackingEntries
                        .Where(x => string.Equals(x.Status, "Pending Dispatch", StringComparison.OrdinalIgnoreCase))
                        .OrderByDescending(x => x.ChallanDate)
                        .ThenByDescending(x => x.Id)
                        .ToList();

                    var inTransitRows = trackingEntries
                        .Where(x => string.Equals(x.Status, "In Transit", StringComparison.OrdinalIgnoreCase))
                        .OrderByDescending(x => x.DispatchDate ?? DateTime.MinValue)
                        .ThenByDescending(x => x.Id)
                        .Take(20)
                        .ToList();

                    if (!dashboardSummaryApplied)
                    {
                        var challanSummaryRepo = new ChallanRepository { LedgerMode = "Challan" };
                        dueChallans = SafeGet(() => (long)challanSummaryRepo.GetDueCount(useLhsDerived: true), 0L);
                        totalDue = SafeGet(() => challanSummaryRepo.GetTotalDue(useLhsDerived: true), 0m);
                        decimal billTotalDue = SafeGet(() => _billRepo.GetTotalDue(), 0m);
                        decimal cbsBankNet = SafeGet(() => _cbsRepo.GetBankNet(), 0m);
                        decimal cbsCashNet = SafeGet(() => _cbsRepo.GetCashNet(), 0m);
                        var newBookingPage = SafeGet(() => challanSummaryRepo.GetPendingBookingPage(1, 50, string.Empty), new RemotePagedResult<ChallanEntry>())
                            ?? new RemotePagedResult<ChallanEntry>();
                        var newBookingItems = newBookingPage.Items ?? new List<ChallanEntry>();
                        var pendingBillsCount = SafeGet(() => _lrRepo.GetPendingBillPage(1, 1, string.Empty)?.TotalCount ?? 0, 0);

                        DeferUi(() =>
                        {
                            if (refreshVersion != Volatile.Read(ref _dashboardRefreshVersion)) return;
                            _dashboardPendingBookingPreviewEntries = newBookingItems.Select(CloneChallanEntry).ToList();
                            if (DashboardTotalDue != null) DashboardTotalDue.Text = $"Rs. {totalDue:N2}";
                            if (DashboardTotalChallans != null) DashboardTotalChallans.Text = $"{dueChallans} Due Challans";
                            if (DashboardOutstanding != null) DashboardOutstanding.Text = $"Rs. {billTotalDue:N2}";
                            if (DashboardPendingBills != null) DashboardPendingBills.Text = $"{pendingBillsCount} Pending Bills";
                            if (DashboardCBSBankNet != null) DashboardCBSBankNet.Text = $"Rs. {cbsBankNet:N2}";
                            if (DashboardCBSCashNet != null) DashboardCBSCashNet.Text = $"Rs. {cbsCashNet:N2}";
                            if (DashboardNewBookings != null) DashboardNewBookings.Text = newBookingPage.TotalCount.ToString();
                            if (DashboardBillsCard != null) DashboardBillsCard.ToolTip = $"Open pending bills window ({pendingBillsCount})";
                            ApplyTrackingReminderCount(trackingReminderCount);
                            ApplyDashboardTrackingTables(pendingDispatchRows, inTransitRows);
                        });
                    }
                    else
                    {
                        DeferUi(() =>
                        {
                            if (refreshVersion != Volatile.Read(ref _dashboardRefreshVersion)) return;
                            ApplyTrackingReminderCount(trackingReminderCount);
                            ApplyDashboardTrackingTables(pendingDispatchRows, inTransitRows);
                        });
                    }
                }
                catch (Exception ex)
                {
                    LogException(nameof(RefreshDashboard), ex);
                }
            });
        }

        private List<TrackingEntry> LoadTrackingEntriesForDashboard()
        {
            var trackingEntries = (TrackingVM?.Entries?.Count > 0
                ? TrackingVM.Entries.ToList()
                : (SafeLoad(() => _trackingRepo.GetAll()) ?? new List<TrackingEntry>()));

            try
            {
                var latestReports = _trackingRepo.GetLatestReportForAll() ?? new Dictionary<int, string>();
                foreach (var entry in trackingEntries)
                {
                    if (latestReports.TryGetValue(entry.Id, out var latestReport))
                    {
                        entry.LatestReport = latestReport;
                    }
                }
            }
            catch (Exception ex)
            {
                LogException(nameof(LoadTrackingEntriesForDashboard), ex);
            }

            return trackingEntries;
        }

        private void QueueDashboardRefresh()
        {
            if (!Dispatcher.CheckAccess())
            {
                Dispatcher.BeginInvoke(new Action(QueueDashboardRefresh));
                return;
            }

            if (!IsDashboardVisible())
            {
                return;
            }

            _dashboardRefreshTimer.Stop();
            _dashboardRefreshTimer.Start();
        }

        private void DashboardRefreshTimer_Tick(object sender, EventArgs e)
        {
            _dashboardRefreshTimer.Stop();
            RefreshDashboard();
        }

        private bool IsDashboardVisible()
        {
            return DashboardView != null && DashboardView.Visibility == Visibility.Visible;
        }

        private void ApplyDashboardSummary(DashboardSummary summary)
        {
            if (summary == null) return;

            DeferUi(() =>
            {
                if (DashboardTotalDue != null) DashboardTotalDue.Text = $"Rs. {summary.ChallanDueAmount:N2}";
                if (DashboardTotalChallans != null) DashboardTotalChallans.Text = $"{summary.DueChallanCount} Due Challans";
                if (DashboardOutstanding != null) DashboardOutstanding.Text = $"Rs. {summary.BillDueAmount:N2}";
                if (DashboardPendingBills != null) DashboardPendingBills.Text = $"{summary.PendingBillCount} Pending Bills";
                if (DashboardCBSBankNet != null) DashboardCBSBankNet.Text = $"Rs. {summary.CBSBankNet:N2}";
                if (DashboardCBSCashNet != null) DashboardCBSCashNet.Text = $"Rs. {summary.CBSCashNet:N2}";
                if (DashboardNewBookings != null) DashboardNewBookings.Text = summary.NewBookingCount.ToString();
                if (DashboardBillsCard != null) DashboardBillsCard.ToolTip = $"Open pending bills window ({summary.PendingBillCount})";
            });
