        private void ApplyTrackingReminderCount(int reminderCount)
        {
            if (TabTrackingLedger == null) return;

            var safeCount = Math.Max(0, reminderCount);
            TabTrackingLedger.Content = safeCount > 0
                ? $"{TrackingTabBaseText} ({safeCount})"
                : TrackingTabBaseText;
            TabTrackingLedger.ToolTip = safeCount > 0
                ? $"{safeCount} e-way bill entr{(safeCount == 1 ? "y is" : "ies are")} expired or due by tomorrow."
                : "No expired or near-due e-way bill reminders.";
        }

        private void RefreshTrackingReminderFromCurrentEntries()
        {
            try
            {
                if (TrackingVM?.Entries == null)
                {
                    ApplyTrackingReminderCount(0);
                    return;
                }

                var tomorrow = DateTime.Today.AddDays(1).Date;
                var reminderCount = TrackingVM.Entries.Count(x =>
                    x.EwayBillTillDate.HasValue &&
                    x.EwayBillTillDate.Value.Date <= tomorrow &&
                    !x.DeliveredDate.HasValue);

                ApplyTrackingReminderCount(reminderCount);
            }
            catch (Exception ex)
            {
                LogException(nameof(RefreshTrackingReminderFromCurrentEntries), ex);
            }
        }

        private void ApplyDashboardTrackingTables(IList<TrackingEntry> pendingDispatchRows, IList<TrackingEntry> inTransitRows)
        {
            _dashboardPendingDispatchSourceEntries = pendingDispatchRows?.ToList() ?? new List<TrackingEntry>();
            ApplyDashboardPendingDispatchFilter();

            if (DashboardInTransitCount != null)
            {
                DashboardInTransitCount.Text = (inTransitRows?.Count ?? 0).ToString();
            }

            _dashboardInTransitSourceEntries = inTransitRows?.ToList() ?? new List<TrackingEntry>();
            ApplyDashboardInTransitFilter();
        }

        private void DashboardPendingDispatchFilter_TextChanged(object sender, TextChangedEventArgs e)
        {
            ApplyDashboardPendingDispatchFilter();
        }

        private void ApplyDashboardPendingDispatchFilter()
        {
            var fromFilter = (DashboardPendingDispatchFromSearchBox?.Text ?? string.Empty).Trim();
            var toFilter = (DashboardPendingDispatchToSearchBox?.Text ?? string.Empty).Trim();

            var filtered = _dashboardPendingDispatchSourceEntries
                .Where(x => string.IsNullOrWhiteSpace(fromFilter) ||
                            (!string.IsNullOrWhiteSpace(x?.From) && x.From.IndexOf(fromFilter, StringComparison.OrdinalIgnoreCase) >= 0))
                .Where(x => string.IsNullOrWhiteSpace(toFilter) ||
                            (!string.IsNullOrWhiteSpace(x?.To) && x.To.IndexOf(toFilter, StringComparison.OrdinalIgnoreCase) >= 0))
                .ToList();

            if (DashboardPendingDispatchCount != null)
            {
                DashboardPendingDispatchCount.Text = filtered.Count.ToString();
            }

            _dashboardPendingDispatchEntries.Clear();
            foreach (var row in filtered)
            {
                _dashboardPendingDispatchEntries.Add(row);
            }
        }

        private void DashboardInTransitFilter_TextChanged(object sender, TextChangedEventArgs e)
        {
            ApplyDashboardInTransitFilter();
        }

        private void ApplyDashboardInTransitFilter()
        {
            var fromFilter = (DashboardInTransitFromSearchBox?.Text ?? string.Empty).Trim();
            var toFilter = (DashboardInTransitToSearchBox?.Text ?? string.Empty).Trim();

            var filtered = _dashboardInTransitSourceEntries
                .Where(x => string.IsNullOrWhiteSpace(fromFilter) ||
                            (!string.IsNullOrWhiteSpace(x?.From) && x.From.IndexOf(fromFilter, StringComparison.OrdinalIgnoreCase) >= 0))
                .Where(x => string.IsNullOrWhiteSpace(toFilter) ||
                            (!string.IsNullOrWhiteSpace(x?.To) && x.To.IndexOf(toFilter, StringComparison.OrdinalIgnoreCase) >= 0))
                .ToList();

            if (DashboardInTransitCount != null)
            {
                DashboardInTransitCount.Text = filtered.Count.ToString();
            }

            _dashboardInTransitEntries.Clear();
            foreach (var row in filtered)
            {
                _dashboardInTransitEntries.Add(row);
            }
        }

        private void RefreshDashboardTrackingTablesFromCurrentEntries()
        {
            try
            {
                var trackingEntries = TrackingVM?.Entries?.ToList() ?? new List<TrackingEntry>();

                var pendingDispatchRows = trackingEntries
                    .Where(x => string.Equals(x.Status, "Pending Dispatch", StringComparison.OrdinalIgnoreCase))
                    .OrderByDescending(x => x.ChallanDate)
                    .ThenByDescending(x => x.Id)
                    .ToList();

                var inTransitRows = trackingEntries
                    .Where(x => string.Equals(x.Status, "In Transit", StringComparison.OrdinalIgnoreCase))
                    .OrderByDescending(x => x.DispatchDate ?? DateTime.MinValue)
                    .ThenByDescending(x => x.Id)
                    .Take(20)
                    .ToList();

                ApplyDashboardTrackingTables(pendingDispatchRows, inTransitRows);

                if (DashboardPendingDispatchGrid != null) DashboardPendingDispatchGrid.Items.Refresh();
                if (DashboardInTransitGrid != null) DashboardInTransitGrid.Items.Refresh();
            }
            catch (Exception ex)
            {
                LogException(nameof(RefreshDashboardTrackingTablesFromCurrentEntries), ex);
            }
        }

        private void RefreshTrackingAfterChallanChange()
        {
            try
            {
                _trackingLedgerDirty = true;

                if (TrackingVM == null)
                {
                    return;
                }

                if (TrackingVM.Entries.Count == 0 && (TrackingLedgerView == null || TrackingLedgerView.Visibility != Visibility.Visible))
                {
                    return;
                }

                TrackingVM.LoadData();
                _trackingLedgerDirty = false;
                TrackingVM.FilteredEntriesCount = TrackingVM.Entries.Count;
                RefreshTrackingReminderFromCurrentEntries();
                RefreshDashboardTrackingTablesFromCurrentEntries();

                if (TrackingLedgerGrid != null)
                {
                    TrackingLedgerGrid.Items.Refresh();
                }
            }
            catch (Exception ex)
            {
                LogException(nameof(RefreshTrackingAfterChallanChange), ex);
            }
        }

        private static List<T> SafeLoad<T>(Func<List<T>> loader)
        {
            try
            {
                return loader != null ? loader() : new List<T>();
            }
            catch
            {
                return new List<T>();
            }
        }

        private static T SafeGet<T>(Func<T> loader, T fallback = default(T))
        {
            try
            {
                return loader != null ? loader() : fallback;
            }
            catch
            {
                return fallback;
            }
        }

        private void DataGrid_PreviewKeyDown(object sender, KeyEventArgs e)
        {
            var grid = sender as DataGrid;
            if (grid == null) return;

            if (grid == LedgerGrid &&
                Keyboard.Modifiers == ModifierKeys.Control &&
                e.Key == Key.Z)
            {
                if (UndoChallanEdit()) e.Handled = true;
                return;
            }

            if (grid == LedgerGrid &&
                Keyboard.Modifiers == (ModifierKeys.Control | ModifierKeys.Shift) &&
                e.Key == Key.Z)
            {
                if (RedoChallanEdit()) e.Handled = true;
                return;
            }

            if (grid == LRLedgerGrid &&
                Keyboard.Modifiers == ModifierKeys.Control &&
                e.Key == Key.Z)
            {
                if (UndoLREdit()) e.Handled = true;
                return;
            }

            if ((grid == LedgerGrid || grid == LRLedgerGrid || grid == BillLedgerGrid || grid == CBSGrid) &&
                Keyboard.Modifiers == ModifierKeys.Control && e.Key == Key.C)
            {
                CopySelectedRangeFromGrid(grid);
                e.Handled = true;
                return;
            }

            if (e.Key != Key.Left && e.Key != Key.Right && e.Key != Key.Up && e.Key != Key.Down && e.Key != Key.Enter && e.Key != Key.Tab) return;

            // While typing/editing in a TextBox, keep normal caret behavior for Left/Right keys.
            if ((e.Key == Key.Left || e.Key == Key.Right) && grid.IsKeyboardFocusWithin)
            {
                var tb = e.OriginalSource as TextBox;
                if (tb != null && !tb.IsReadOnly)
                {
                    return;
                }
            }

            // For Tab, let standard handling work but commit first.
            if (e.Key == Key.Tab)
            {
                if (!TryCommitGridEdits(grid)) e.Handled = true;
                return;
            }

            if (grid.CurrentCell.Column == null) return;
            var colIdx = grid.Columns.IndexOf(grid.CurrentCell.Column);
            var rowIdx = grid.Items.IndexOf(grid.CurrentCell.Item);
            if (colIdx < 0 || rowIdx < 0) return;

            int newCol = colIdx, newRow = rowIdx;
            if (e.Key == Key.Left && colIdx > 0) newCol = colIdx - 1;
            else if (e.Key == Key.Right && colIdx < grid.Columns.Count - 1) newCol = colIdx + 1;
            else if (e.Key == Key.Up && rowIdx > 0) newRow = rowIdx - 1;
            else if (e.Key == Key.Down && rowIdx < grid.Items.Count - 1) newRow = rowIdx + 1;
            else if (e.Key == Key.Enter && rowIdx < grid.Items.Count - 1) newRow = rowIdx + 1;
            else if (e.Key == Key.Enter && rowIdx >= grid.Items.Count - 1)
            {
                TryCommitGridEdits(grid);
                return;
            }
            else return;

            e.Handled = true;
            if (!TryCommitGridEdits(grid))
            {
                // Keep focus on current cell when commit fails (e.g., partially typed numeric value)
                return;
            }

            if (newCol < 0 || newCol >= grid.Columns.Count)
            {
                return;
            }

            if (newRow < 0 || newRow >= grid.Items.Count)
            {
                return;
            }

            var newItem = grid.Items[newRow];
            grid.CurrentCell = new DataGridCellInfo(newItem, grid.Columns[newCol]);
            grid.BeginEdit();
        }

        private static bool TryCommitGridEdits(DataGrid grid)
        {
            try
            {
                if (grid == null) return false;
                grid.CommitEdit(DataGridEditingUnit.Cell, true);
                grid.CommitEdit(DataGridEditingUnit.Row, true);
                return true;
            }
            catch
            {
                return false;
            }
        }

        private void MainWindow_PreviewMouseLeftButtonDown(object sender, MouseButtonEventArgs e)
        {
            try
            {
                if (IsClickInsideEditingCell(e.OriginalSource as DependencyObject))
                {
                    return;
                }

                TryCommitOpenGridEdits();
            }
            catch (Exception ex)
            {
                LogException(nameof(MainWindow_PreviewMouseLeftButtonDown), ex);
            }
        }

        private void TryCommitOpenGridEdits()
        {
            TryCommitGridEdits(LedgerGrid);
            TryCommitGridEdits(LRLedgerGrid);
            TryCommitGridEdits(BillLedgerGrid);
            TryCommitGridEdits(CBSGrid);
        }

        private static bool IsClickInsideEditingCell(DependencyObject source)
        {
            var current = source;
            while (current != null)
            {
                if (current is DataGridCell cell)
                {
                    return cell.IsEditing;
                }

                current = VisualTreeHelper.GetParent(current);
            }

            return false;
        }

        private static string GetColumnBindingPath(DataGridColumn col)
        {
            if (col is DataGridTextColumn tc && tc.Binding is Binding tb) return tb.Path?.Path;
            if (col is DataGridBoundColumn bc && bc.Binding is Binding bb) return bb.Path?.Path;
            if (col is DataGridTemplateColumn tcol) return tcol.SortMemberPath;
            return null;
        }

        private static string GetCellDisplayText(object item, DataGridColumn col)
        {
            if (item == null || col == null) return string.Empty;
            var path = GetColumnBindingPath(col);
            if (string.IsNullOrWhiteSpace(path)) return string.Empty;
            var prop = item.GetType().GetProperty(path);
            if (prop == null) return string.Empty;
            var val = prop.GetValue(item);
            if (val == null) return string.Empty;
            if (val is DateTime dt) return dt.ToString("dd-MMM-yyyy");
            var ndt = val as DateTime?;
            if (ndt.HasValue) return ndt.Value.ToString("dd-MMM-yyyy");
            if (val is decimal dec) return dec.ToString("N2");
            if (val is double d) return d.ToString("N2");
            return Convert.ToString(val) ?? string.Empty;
        }

        private void CopySelectedRangeFromGrid(DataGrid grid)
        {
            if (grid == null || grid.SelectedCells == null || grid.SelectedCells.Count == 0) return;

            var cells = grid.SelectedCells
                .Where(c => c.Item != CollectionView.NewItemPlaceholder && c.Column != null)
                .ToList();
            if (cells.Count == 0) return;

            var rowOrder = grid.Items.Cast<object>()
                .Where(i => i != CollectionView.NewItemPlaceholder)
                .Select((item, idx) => new { item, idx })
                .ToDictionary(x => x.item, x => x.idx);

            var selectedColumns = cells
                .Select(c => c.Column)
                .Distinct()
                .OrderBy(c => c.DisplayIndex)
                .ToList();

            var selectedRows = cells
                .Select(c => c.Item)
                .Distinct()
                .Where(r => rowOrder.ContainsKey(r))
                .OrderBy(r => rowOrder[r])
                .ToList();

            var rowCellMap = cells
                .GroupBy(c => c.Item)
                .ToDictionary(
                    g => g.Key,
                    g => g.ToDictionary(x => x.Column, x => x, EqualityComparer<DataGridColumn>.Default)
                );

            var sb = new StringBuilder();
            for (int r = 0; r < selectedRows.Count; r++)
            {
                var rowItem = selectedRows[r];
                var rowValues = new List<string>(selectedColumns.Count);

                foreach (var col in selectedColumns)
                {
                    if (rowCellMap.TryGetValue(rowItem, out var colMap) && colMap.TryGetValue(col, out var cellInfo))
                        rowValues.Add(GetCellDisplayText(cellInfo.Item, col));
                    else
                        rowValues.Add(string.Empty);
                }

                sb.Append(string.Join("\t", rowValues));
                if (r < selectedRows.Count - 1) sb.AppendLine();
            }

            if (sb.Length > 0) Clipboard.SetText(sb.ToString());
        }

        private void CopyCurrentCellFromGrid(DataGrid grid)
        {
            if (grid == null) return;

            if (grid.SelectedCells != null && grid.SelectedCells.Count > 1)
            {
                CopySelectedRangeFromGrid(grid);
                return;
            }

            if (grid.CurrentCell.Column == null || grid.CurrentCell.Item == null) return;
            var text = GetCellDisplayText(grid.CurrentCell.Item, grid.CurrentCell.Column);
            if (!string.IsNullOrWhiteSpace(text)) Clipboard.SetText(text);
        }

        private void CopySelectedRowsFromGrid(DataGrid grid)
        {
            if (grid == null || grid.SelectedItems == null || grid.SelectedItems.Count == 0) return;
            var rows = grid.SelectedItems.Cast<object>().Where(x => x != CollectionView.NewItemPlaceholder).ToList();
            if (rows.Count == 0) return;

            var cols = grid.Columns.OrderBy(c => c.DisplayIndex).Where(c => c.Visibility == Visibility.Visible).ToList();
            var sb = new StringBuilder();
            for (int i = 0; i < rows.Count; i++)
            {
                var rowVals = cols.Select(c => GetCellDisplayText(rows[i], c));
                sb.Append(string.Join("\t", rowVals));
                if (i < rows.Count - 1) sb.AppendLine();
            }
            if (sb.Length > 0) Clipboard.SetText(sb.ToString());
        }

        private void CopyColumnFromGrid(DataGrid grid, DataGridColumn column)
        {
            if (grid == null || column == null) return;

             // If multiple columns are selected (via header drag/Ctrl+click), copy the full selected block.
            var selectedCols = grid.SelectedCells
                .Where(c => c.Column != null && c.Item != CollectionView.NewItemPlaceholder)
                .Select(c => c.Column)
                .Distinct()
                .ToList();
            if (selectedCols.Count > 1)
            {
                CopySelectedRangeFromGrid(grid);
                return;
            }

            var items = grid.Items.Cast<object>().Where(i => i != CollectionView.NewItemPlaceholder).ToList();
            if (items.Count == 0) return;

            var sb = new StringBuilder();
            for (int i = 0; i < items.Count; i++)
            {
                sb.Append(GetCellDisplayText(items[i], column));
                if (i < items.Count - 1) sb.AppendLine();
            }
            if (sb.Length > 0) Clipboard.SetText(sb.ToString());
        }

        private void DashboardMakeBill_Click(object sender, RoutedEventArgs e)
        {
            var lr = (sender as System.Windows.Controls.Button)?.Tag as LREntry;
            if (lr == null) return;
            OpenBillFormFromPendingLr(lr);
        }

        private void OpenBillFormFromPendingLr(LREntry lr, Action afterSaved = null, Window ownerWindow = null, bool skipBilledCheck = false)
        {
            if (lr == null) return;
            if (!skipBilledCheck && !string.IsNullOrEmpty(lr.BillNo)) { MessageBox.Show($"LR '{lr.LRNo}' already has Bill No. '{lr.BillNo}'.", "Already Billed", MessageBoxButton.OK, MessageBoxImage.Warning); return; }
            var form = new BillFormWindow();
            form.Result.Party = (lr.BillParty ?? string.Empty).Trim();
            form.Result.LRNo = lr.LRNo;
            form.Result.LRDate = lr.Date;
            form.Result.From = lr.From;
            form.Result.To = lr.To;
            form.Result.VehicleType = lr.VehicleType;
            form.Result.Freight = lr.TotalFreight;
            form.Result.HML = lr.Hamali;
            form.Result.Detention = lr.Detention;
            form.Result.OTHR = lr.Others;
            form.Result.StCharge = lr.StCharge;
            form.Result.RCVD = lr.NEFT + lr.CASH;
            form.Result.TDS = lr.TDS;
            form.Result.DED = lr.Ded;
            form.DataContext = form.Result;
            form.Owner = ownerWindow ?? this;
            form.Closed += (_, __) =>
            {
                if (!form.WasSaved) return;
                var entry = form.Result;
                try
                {
                    SaveBillRowsFromFormEntry(entry);
                    UpdateLRBillNo(lr.Id, entry.BillNo);
                    SyncChallanBillingForBillEntry(entry);
                }
                catch (Exception ex)
                {
                    MessageBox.Show("Save error: " + ex.Message, "Error", MessageBoxButton.OK, MessageBoxImage.Error);
                    return;
                }

                try
                {
                    BillVM.RefreshAfterDelete();
                    LRVM.RefreshAfterDelete();
                    BillUpdatePageUI();
                    LRUpdatePageUI();
                    RefreshDashboard();
                    afterSaved?.Invoke();
                    RestoreWindowAfterChildSave(ownerWindow ?? this);
                    MessageBox.Show($"Bill created: {entry.BillNo}", "Success", MessageBoxButton.OK, MessageBoxImage.Information);
                }
                catch (Exception ex)
                {
                    LogException(nameof(OpenBillFormFromPendingLr), ex);
                }
            };
            form.Show();
        }

        private static string NormalizeBillingPartyKey(string value)
        {
            var raw = (value ?? string.Empty).Trim();
            if (raw.Length == 0) return string.Empty;
            var parts = raw.Split(new[] { ' ', '\t', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
            return string.Join(" ", parts).ToUpperInvariant();
        }

        private static string GetBillingPartyName(LREntry lr)
        {
            if (lr == null) return string.Empty;
            var billParty = (lr.BillParty ?? string.Empty).Trim();
            if (!string.IsNullOrWhiteSpace(billParty)) return billParty;
            return (lr.ConsignorName ?? string.Empty).Trim();
        }

        private void OpenBillFormFromPendingLrs(List<LREntry> selectedRows, Action afterSaved = null, Window ownerWindow = null, bool skipBilledCheck = true)
        {
            var selected = (selectedRows ?? new List<LREntry>())
                .Where(lr => lr != null)
                .ToList();
            if (selected.Count == 0)
            {
                MessageBox.Show("Select LR rows to create a bill.", "No Selection", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            var fullRows = selected
                .OrderBy(lr => lr.Id)
                .ToList();

            if (fullRows.Count == 0)
            {
                MessageBox.Show("Unable to load selected LR details.", "Pending Bills", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            OpenBillFormForLrSelection(fullRows, afterSaved, ownerWindow, skipBilledCheck);
        }

        private void OpenBillFormForLrSelection(List<LREntry> selectedRows, Action afterSaved = null, Window ownerWindow = null, bool skipBilledCheck = false)
        {
            var selected = (selectedRows ?? new List<LREntry>())
                .Where(lr => lr != null)
                .ToList();
            if (selected.Count == 0)
            {
                MessageBox.Show("Select LR entries to create a bill.", "No Selection", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            List<LREntry> unbilled;
            if (skipBilledCheck)
            {
                unbilled = selected
                    .Where(lr => string.IsNullOrWhiteSpace(lr?.BillNo))
                    .ToList();
            }
            else
            {
                var billedLrSet = GetBilledLrNumbers();
                unbilled = selected
                    .Where(lr => !IsLrBilled(lr?.LRNo, billedLrSet) && string.IsNullOrWhiteSpace(lr?.BillNo))
                    .ToList();
            }
            if (unbilled.Count == 0)
            {
                MessageBox.Show("All selected LRs already have a bill.", "Already Billed", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            if (unbilled.Count < selected.Count)
            {
                var result = MessageBox.Show($"{selected.Count - unbilled.Count} of {selected.Count} selected LRs already have a bill. Create bill for the remaining {unbilled.Count}?", "Partial Bill", MessageBoxButton.YesNo, MessageBoxImage.Question);
                if (result != MessageBoxResult.Yes) return;
            }

            var parties = unbilled
                .Select(GetBillingPartyName)
                .Where(x => !string.IsNullOrWhiteSpace(x))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
            if (parties.Count == 0)
            {
                MessageBox.Show("Selected LR rows do not have a billing company.", "Validation", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            var normalizedParties = parties
                .Select(NormalizeBillingPartyKey)
                .Where(x => x.Length > 0)
                .Distinct(StringComparer.Ordinal)
                .ToList();
            if (normalizedParties.Count > 1)
            {
                MessageBox.Show("You can create one bill only for LR rows of the same billing company.", "Billing Company Mismatch", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            var first = unbilled[0];
            var form = new BillFormWindow();
            form.Result.Party = GetBillingPartyName(first);
            form.Result.LRNo = string.Join(", ", unbilled.Select(lr => lr.LRNo).Where(n => !string.IsNullOrEmpty(n)));
            form.Result.LRDate = first.Date;
            form.Result.From = first.From;
            form.Result.To = first.To;
            form.Result.VehicleType = first.VehicleType;
            form.Result.Freight = unbilled.Sum(lr => lr.TotalFreight);
            form.Result.HML = unbilled.Sum(lr => lr.Hamali);
            form.Result.Detention = unbilled.Sum(lr => lr.Detention);
            form.Result.OTHR = unbilled.Sum(lr => lr.Others);
            form.Result.StCharge = unbilled.Sum(lr => lr.StCharge);
            form.Result.RCVD = unbilled.Sum(lr => lr.NEFT + lr.CASH);
            form.Result.TDS = unbilled.Sum(lr => lr.TDS);
            form.Result.DED = unbilled.Sum(lr => lr.Ded);
            form.DataContext = form.Result;

            form.Owner = ownerWindow ?? this;
            form.Closed += (_, __) =>
            {
                if (!form.WasSaved) return;
                var entry = form.Result;
                try
                {
                    SaveBillRowsFromFormEntry(entry);
                    foreach (var lr in unbilled)
                    {
                        if (lr.Id <= 0) continue;
                        UpdateLRBillNo(lr.Id, entry.BillNo);
                    }
                    SyncChallanBillingForBillEntry(entry);
                }
                catch (Exception ex)
                {
                    MessageBox.Show("Save error: " + ex.Message, "Error", MessageBoxButton.OK, MessageBoxImage.Error);
                    return;
                }

                try
                {
                    LRVM.RefreshAfterDelete();
                    BillVM.RefreshAfterDelete();
                    LRUpdatePageUI();
                    BillUpdatePageUI();
                    RefreshDashboard();
                    afterSaved?.Invoke();
                    RestoreWindowAfterChildSave(ownerWindow ?? this);
                    MessageBox.Show($"Bill created: {entry.BillNo}", "Success", MessageBoxButton.OK, MessageBoxImage.Information);
                }
                catch (Exception ex)
                {
                    LogException(nameof(OpenBillFormForLrSelection), ex);
                }
            };
            form.Show();
        }

