        private List<ChallanEntry> LoadPendingBookingItems(int limit = 50)
        {
            var challanRepository = GetPurchaseChallanRepository();
            if (BackendSettings.UseRemoteApi)
            {
                return challanRepository.GetPendingBookingItems(limit > 0 ? limit : 0)
                    .Where(x => x != null)
                    .ToList();
            }

            var allLrs = _lrRepo.GetAll();
            var allLrNos = new HashSet<string>(
                allLrs
                    .Select(x => (x.LRNo ?? string.Empty).Trim())
                    .Where(x => !string.IsNullOrWhiteSpace(x)),
                StringComparer.OrdinalIgnoreCase);
            var challansWithCreatedLr = new HashSet<string>(
                allLrs
                    .Select(x => (x.CHNo ?? string.Empty).Trim())
                    .Where(x => !string.IsNullOrWhiteSpace(x)),
                StringComparer.OrdinalIgnoreCase);
            var allChallans = challanRepository.GetAll();

            List<string> GetMissingLrNos(string raw)
            {
                raw = (raw ?? string.Empty).Trim();
                if (string.IsNullOrWhiteSpace(raw)) return new List<string>();

                var lrParts = raw.Split(new[] { ',', ';', ' ', '\n', '\r', '\t' }, StringSplitOptions.RemoveEmptyEntries)
                                 .Select(x => x.Trim())
                                 .Where(x => !string.IsNullOrWhiteSpace(x))
                                 .Distinct(StringComparer.OrdinalIgnoreCase)
                                 .ToList();
                if (lrParts.Count == 0) return new List<string>();

                return lrParts.Where(lr => !allLrNos.Contains(lr)).ToList();
            }

            var expandedPending = new List<ChallanEntry>();
            foreach (var ch in allChallans)
            {
                var raw = (ch.LRNumber ?? string.Empty).Trim();
                if (string.IsNullOrWhiteSpace(raw))
                {
                    if (challansWithCreatedLr.Contains((ch.ChallanNumber ?? string.Empty).Trim())) continue;
                    expandedPending.Add(ch);
                    continue;
                }

                var missing = GetMissingLrNos(raw);
                if (missing.Count == 0) continue;
                foreach (var miss in missing)
                {
                    expandedPending.Add(new ChallanEntry
                    {
                        Id = ch.Id,
                        ChallanNumber = ch.ChallanNumber,
                        LRNumber = miss,
                        From = ch.From,
                        To = ch.To,
                        VehicleNumber = ch.VehicleNumber,
                        BrokerName = ch.BrokerName,
                        LorryHire = ch.LorryHire
                    });
                }
            }

            return limit > 0 ? expandedPending.Take(limit).ToList() : expandedPending;
        }

        private static void ReplaceCollectionItems<T>(ObservableCollection<T> items, IEnumerable<T> source)
        {
            items.Clear();
            foreach (var item in source)
            {
                items.Add(item);
            }
        }

