        private async void LRDeleteSelected_Click(object sender, RoutedEventArgs e)
        {
            if (!EnsureAdminAccess("Delete LR entries")) return;
            if (LRLedgerGrid == null) return;
            var selected = LRLedgerGrid.SelectedItems.Cast<LREntry>().ToList();
            if (selected.Count == 0) { MessageBox.Show("Select LR entries to delete.", "No Selection", MessageBoxButton.OK, MessageBoxImage.Information); return; }
            if (MessageBox.Show($"Delete {selected.Count} LR entr{(selected.Count == 1 ? "y" : "ies")}?", "Confirm", MessageBoxButton.YesNo, MessageBoxImage.Question) != MessageBoxResult.Yes) return;
            foreach (var item in selected)
            {
                LRVM?.RemoveOptimisticEntry(item);
            }
            LRUpdatePageUI();

            BeginBusyCursor();
            try
            {
                await Task.Run(() =>
                {
                    foreach (var item in selected)
                    {
                        try { _lrRepo.Delete(item); } catch { }
                    }
                    SyncChallanBillingForLrs(selected);
                });

                if (VM != null && (DeliveryChallanView.Visibility == Visibility.Visible || DashboardView.Visibility == Visibility.Visible))
                {
                    UpdatePageUI(applyGridFilter: _onlyDueFilterEnabled || _challanHeaderFilters.Count > 0);
                }
                LRRefreshFilteredSummary();
                QueueDashboardRefresh();
            }
            catch (Exception ex)
            {
                LRVM?.RefreshAfterDelete();
                LRUpdatePageUI();
                MessageBox.Show("LR delete failed: " + ex.Message, "Error", MessageBoxButton.OK, MessageBoxImage.Error);
            }
            finally
            {
                EndBusyCursor();
            }
        }

        private async void BillDeleteSelected_Click(object sender, RoutedEventArgs e)
        {
            if (!EnsureAdminAccess("Delete bill entries")) return;
            if (BillLedgerGrid == null) return;
            var selected = BillLedgerGrid.SelectedItems.Cast<BillEntry>().ToList();
            if (selected.Count == 0)
            {
                MessageBox.Show("Select Bill entries to delete.", "No Selection", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            if (MessageBox.Show($"Delete {selected.Count} Bill entr{(selected.Count == 1 ? "y" : "ies")}?", "Confirm", MessageBoxButton.YesNo, MessageBoxImage.Question) != MessageBoxResult.Yes)
            {
                return;
            }

            try
            {
                InvalidateBillDueCaches();
                foreach (var item in selected)
                {
                    BillVM?.RemoveOptimisticEntry(item);
                }
                BillUpdatePageUI();

                var commentRepo = new CommentRepository();
                var affectedBillNos = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                var affectedLrNos = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

                BeginBusyCursor();
                await Task.Run(() =>
                {
                    foreach (var item in selected)
                    {
                        var billNo = (item.BillNo ?? string.Empty).Trim();
                        if (billNo.Length > 0) affectedBillNos.Add(billNo);
                        foreach (var lrNo in SplitLrNumbers(item.LRNo))
                        {
                            affectedLrNos.Add(lrNo);
                        }

                        foreach (var comment in commentRepo.GetBillByBillId(item.Id))
                        {
                            try { commentRepo.DeleteBill(comment.Id); } catch { }
                        }

                        try { _billRepo.Delete(item); } catch { }
                    }

                    var remainingBillsByNo = affectedBillNos.ToDictionary(x => x, x => _billRepo.GetByBillNo(x), StringComparer.OrdinalIgnoreCase);
                    var survivingLrToBillNo = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                    foreach (var kv in remainingBillsByNo)
                    {
                        foreach (var row in kv.Value)
                        {
                            foreach (var lrNo in SplitLrNumbers(row.LRNo))
                            {
                                if (!survivingLrToBillNo.ContainsKey(lrNo))
                                {
                                    survivingLrToBillNo[lrNo] = kv.Key;
                                }
                            }
                        }
                    }

                    foreach (var billNo in affectedBillNos.Where(x => remainingBillsByNo[x].Count == 0))
                    {
                        foreach (var receipt in _billReceiptRepo.GetByBillNo(billNo))
                        {
                            try { _billReceiptRepo.Delete(receipt); } catch { }
                        }
                    }

                    foreach (var lr in _lrRepo.GetByLRNumbers(affectedLrNos))
                    {
                        var currentLrNo = (lr.LRNo ?? string.Empty).Trim();
                        if (currentLrNo.Length == 0) continue;
                        if (!survivingLrToBillNo.TryGetValue(currentLrNo, out var survivingBillNo))
                        {
                            lr.BillNo = null;
                            lr.BillDate = null;
                            lr.BILL = 0m;
                            _lrRepo.Upsert(lr);
                            continue;
                        }

                        var currentBillNo = (lr.BillNo ?? string.Empty).Trim();
                        if (!string.Equals(currentBillNo, survivingBillNo, StringComparison.OrdinalIgnoreCase))
                        {
                            lr.BillNo = survivingBillNo;
                            lr.BillDate = remainingBillsByNo[survivingBillNo].FirstOrDefault()?.BillDate;
                            lr.BILL = remainingBillsByNo[survivingBillNo].FirstOrDefault()?.Total ?? 0m;
                            _lrRepo.Upsert(lr);
                        }
                    }

                    SyncChallanBillingForLrs(_lrRepo.GetByLRNumbers(affectedLrNos));
                });

                BillUpdatePageUI();
                LRVM?.RefreshAfterDelete();
                LRUpdatePageUI();
                if (VM != null && (DeliveryChallanView.Visibility == Visibility.Visible || DashboardView.Visibility == Visibility.Visible))
                {
                    UpdatePageUI(applyGridFilter: _onlyDueFilterEnabled || _challanHeaderFilters.Count > 0);
                }
                QueueDashboardRefresh();
            }
            catch (Exception ex)
            {
                BillVM?.RefreshAfterDelete();
                BillUpdatePageUI();
                MessageBox.Show("Bill delete failed: " + ex.Message, "Error", MessageBoxButton.OK, MessageBoxImage.Error);
            }
            finally
            {
                EndBusyCursor();
            }
        }

        private void OpenBillLedger_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                using (EnterBusyCursor())
                {
                HideUtilityViews();
                DashboardView.Visibility = Visibility.Collapsed;
                DeliveryChallanView.Visibility = Visibility.Collapsed;
                LRLedgerView.Visibility = Visibility.Collapsed;
                TrackingLedgerView.Visibility = Visibility.Collapsed;
                PartyLedgerView.Visibility = Visibility.Collapsed;
                VehicleLedgerView.Visibility = Visibility.Collapsed;
                CBSLedgerView.Visibility = Visibility.Collapsed;

                TabBillLedger.Style = (Style)FindResource("ActiveTabButtonStyle");
                TabDashboard.Style = (Style)FindResource("TabButtonStyle");
                TabDeliveryChallans.Style = (Style)FindResource("TabButtonStyle");
                TabChallan.Style = (Style)FindResource("TabButtonStyle");
                TabLRLedger.Style = (Style)FindResource("TabButtonStyle");
                TabTrackingLedger.Style = (Style)FindResource("TabButtonStyle");
                TabPartyLedger.Style = (Style)FindResource("TabButtonStyle");
                TabVehicleLedger.Style = (Style)FindResource("TabButtonStyle");
                TabCBSLedger.Style = (Style)FindResource("TabButtonStyle");
                if (PageTitle != null) PageTitle.Text = "Bill Ledger";

                BillLedgerView.DataContext = BillVM;
                BillLedgerView.Visibility = Visibility.Visible;
                if (BillSearchBox != null)
                {
                    var visibleSearch = (BillSearchBox.Text ?? string.Empty).Trim().ToLower();
                    BillVM.SetSearchFilter(visibleSearch);
                }
                LoadBillColumnSettings();
                if (!string.IsNullOrWhiteSpace(BillVM?.GetSortColumn()))
                    ApplyBillSort(BillVM.GetSortColumn(), BillVM.IsCurrentSortAscending);

                if (BackendSettings.UseRemoteApi)
                {
                    if (!BillVM.HasLoadedPage && BillRecordCountText != null)
                        BillRecordCountText.Text = "Loading bills...";

                    BeginBusyCursor();
                    BillVM.EnsurePageLoadedAsync(
                        () =>
                        {
                            if (BillVM.TotalCount > 0 && BillVM.PagedEntries.Count == 0)
                            {
                                _billHeaderFilters.Clear();
                                if (BillSearchBox != null && !string.IsNullOrWhiteSpace(BillSearchBox.Text))
                                {
                                    BillSearchBox.Text = string.Empty;
                                }
                                BillVM.SetSearchFilter(string.Empty);
                                BillVM.EnsurePageLoaded();
                            }

                            BillUpdatePageUI();
                            EndBusyCursor();
                        },
                        ex =>
                        {
                            AppLogger.LogException(nameof(OpenBillLedger_Click), ex);
                            if (BillRecordCountText != null) BillRecordCountText.Text = "Unable to load bills";
                            EndBusyCursor();
                        });
                    return;
                }

                BillVM.EnsurePageLoaded();
                if (BillVM.TotalCount > 0 && BillVM.PagedEntries.Count == 0)
                {
                    _billHeaderFilters.Clear();
                    if (BillSearchBox != null) BillSearchBox.Text = string.Empty;
                    BillVM.SetSearchFilter(string.Empty);
                    BillVM.EnsurePageLoaded();
                }
                BillUpdatePageUI();
                }
            }
            catch (Exception ex) { MessageBox.Show("Error: " + ex.Message, "Bill Ledger Error", MessageBoxButton.OK, MessageBoxImage.Error); }
        }

        private void OpenBillForm_Click(object sender, RoutedEventArgs e)
        {
            var form = new BillFormWindow();
            form.Owner = this;
            form.Closed += (_, __) =>
            {
                if (!form.WasSaved) return;
                var entry = form.Result;
                try
                {
                    SaveBillRowsFromFormEntry(entry);
                    SyncLREntriesFromBillNo(entry?.BillNo);
                    SyncChallanBillingForBillEntry(entry);
                }
                catch (Exception ex)
                {
                    MessageBox.Show("Save error: " + ex.Message, "Error", MessageBoxButton.OK, MessageBoxImage.Error);
                    return;
                }

                try
                {
                    LRVM.RefreshAfterDelete();
                    BillVM.RefreshAfterDelete();
                    LRUpdatePageUI();
                    BillUpdatePageUI();
                    MessageBox.Show($"Bill created: {entry.BillNo}", "Success", MessageBoxButton.OK, MessageBoxImage.Information);
                }
                catch (Exception ex)
                {
                    LogException(nameof(OpenBillForm_Click), ex);
                }
            };
            form.Show();
        }

        private void OpenBillPrefixSettings_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                var dialog = new Window
                {
                    Title = "Bill Prefix Settings",
                    Width = 420,
                    Height = 190,
                    Owner = this,
                    WindowStartupLocation = WindowStartupLocation.CenterOwner,
                    ResizeMode = ResizeMode.NoResize,
                    Background = System.Windows.Media.Brushes.White
                };

                var root = new Grid { Margin = new Thickness(14) };
                root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
                root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

                var label = new TextBlock
                {
                    Text = "Default Bill Prefix",
                    FontWeight = FontWeights.SemiBold,
                    Margin = new Thickness(0, 0, 0, 6)
                };
                var box = new TextBox
                {
                    Height = 28,
                    Text = BillPrefixSettings.GetPrefix(),
                    Margin = new Thickness(0, 0, 0, 8)
                };
                var hint = new TextBlock
                {
                    Text = "Example: FBD 26-27 (bill no will be Prefix/NextNumber)",
                    Foreground = System.Windows.Media.Brushes.Gray,
                    FontSize = 12
                };

                var footer = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right };
                var saveBtn = new Button { Content = "Save", Width = 90, Height = 30, Margin = new Thickness(0, 0, 8, 0) };
                var cancelBtn = new Button { Content = "Cancel", Width = 90, Height = 30 };
                footer.Children.Add(saveBtn);
                footer.Children.Add(cancelBtn);

                Grid.SetRow(label, 0);
                Grid.SetRow(box, 1);
                Grid.SetRow(hint, 2);
                Grid.SetRow(footer, 3);
                root.Children.Add(label);
                root.Children.Add(box);
                root.Children.Add(hint);
                root.Children.Add(footer);
                dialog.Content = root;

                saveBtn.Click += (_, __) =>
                {
                    var value = (box.Text ?? string.Empty).Trim().TrimEnd('/');
                    if (string.IsNullOrWhiteSpace(value))
                    {
                        MessageBox.Show("Prefix cannot be empty.", "Validation", MessageBoxButton.OK, MessageBoxImage.Warning);
                        return;
                    }

                    BillPrefixSettings.SavePrefix(value);
                    dialog.DialogResult = true;
                    dialog.Close();
                };
                cancelBtn.Click += (_, __) => { dialog.DialogResult = false; dialog.Close(); };

                dialog.ShowDialog();
            }
            catch (Exception ex)
            {
                MessageBox.Show("Unable to open bill prefix settings: " + ex.Message, "Error", MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }

