        private void SaveBillRowsFromFormEntry(BillEntry entry)
        {
            if (entry == null) return;
            InvalidateBillDueCaches();

            var lrNos = (entry.LRNo ?? string.Empty)
                .Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries)
                .Select(s => s.Trim())
                .Where(s => s.Length > 0)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();

            var repo = new BillRepository();
            int nextSr = GetNextBillSr();

            // If single/no LR, keep existing behavior.
            if (lrNos.Count <= 1)
            {
                entry.Sr = nextSr;
                ApplyExistingBillRowIdentity(entry);
                repo.Upsert(entry);
                if (lrNos.Count == 1)
                {
                    UpdateLRBillNoByLRNo(lrNos[0], entry.BillNo);
                }
                return;
            }

            var lrMap = _lrRepo.GetByLrNumbers(lrNos)
                .Where(x => x != null && !string.IsNullOrWhiteSpace((x.LRNo ?? string.Empty).Trim()))
                .GroupBy(x => (x.LRNo ?? string.Empty).Trim(), StringComparer.OrdinalIgnoreCase)
                .ToDictionary(g => g.Key, g => g.OrderBy(x => x.Id).First(), StringComparer.OrdinalIgnoreCase);

            foreach (var lrNo in lrNos)
            {
                lrMap.TryGetValue(lrNo, out var lr);
                var row = new BillEntry
                {
                    Sr = nextSr++,
                    BillNo = entry.BillNo,
                    BillDate = entry.BillDate,
                    Party = string.IsNullOrWhiteSpace(entry.Party)
                        ? (!string.IsNullOrWhiteSpace(lr?.BillParty) ? lr.BillParty : (lr?.ConsignorName ?? entry.Party))
                        : entry.Party,
                    LRNo = lrNo,
                    LRDate = lr?.Date,
                    From = lr?.From ?? entry.From,
                    To = lr?.To ?? entry.To,
                    VehicleType = lr?.VehicleType ?? entry.VehicleType,
                    Freight = lr?.TotalFreight ?? 0m,
                    HML = lr?.Hamali ?? 0m,
                    Detention = lr?.Detention ?? 0m,
                    OTHR = lr?.Others ?? 0m,
                    StCharge = lr?.StCharge ?? 0m,
                    RCVD = lr != null ? (lr.NEFT + lr.CASH) : 0m,
                    TDS = lr?.TDS ?? 0m,
                    DED = lr?.Ded ?? 0m,
                    MOP = entry.MOP,
                    MR = entry.MR,
                    Date = entry.Date
                };
                ApplyExistingBillRowIdentity(row);
                repo.Upsert(row);
                UpdateLRBillNoByLRNo(lrNo, entry.BillNo);
            }
        }

        private void ApplyExistingBillRowIdentity(BillEntry row)
        {
            if (row == null || row.Id > 0 || string.IsNullOrWhiteSpace(row.BillNo)) return;
            var billNo = (row.BillNo ?? string.Empty).Trim();
            var lrNo = (row.LRNo ?? string.Empty).Trim();
            var matches = _billRepo.GetByBillNo(billNo)
                .Where(x => string.Equals((x.LRNo ?? string.Empty).Trim(), lrNo, StringComparison.OrdinalIgnoreCase))
                .OrderBy(x => x.Id)
                .ToList();

            var existing = matches.FirstOrDefault();
            if (existing == null) return;

            row.Id = existing.Id;
            if (row.Sr <= 0) row.Sr = existing.Sr;

            foreach (var duplicate in matches.Skip(1))
            {
                try { _billRepo.Delete(duplicate); }
                catch (Exception ex) { LogException(nameof(ApplyExistingBillRowIdentity), ex); }
            }
        }

        private int GetNextBillSr()
        {
            return _billRepo.GetMaxSr() + 1;
        }
        private void UpdateLRBillNoByLRNo(string lrNo, string billNo)
        {
            if (string.IsNullOrWhiteSpace(lrNo)) return;
            var lr = _lrRepo.GetByLrNumbers(new[] { lrNo.Trim() }).FirstOrDefault();
            if (lr == null) return;
            lr.BillNo = billNo;
            _lrRepo.Upsert(lr);
        }

        private void UpdateLRBillNo(int lrId, string billNo)
        {
            if (lrId <= 0) return;
            var lr = _lrRepo.GetById(lrId);
            if (lr == null) return;
            lr.BillNo = billNo;
            _lrRepo.Upsert(lr);
        }

        private void SyncLREntriesFromBillNo(string billNo)
        {
            billNo = (billNo ?? string.Empty).Trim();
            if (string.IsNullOrWhiteSpace(billNo)) return;
            var linked = _billRepo.GetByBillNo(billNo)
                .Where(x => !string.IsNullOrWhiteSpace((x.LRNo ?? string.Empty).Trim()))
                .Select(x => new { LRNo = (x.LRNo ?? string.Empty).Trim(), BillDate = x.BillDate, Party = (x.Party ?? string.Empty).Trim() })
                .ToList();

            var lrMap = _lrRepo.GetByLrNumbers(linked.Select(x => x.LRNo))
                .Where(x => x != null && !string.IsNullOrWhiteSpace((x.LRNo ?? string.Empty).Trim()))
                .GroupBy(x => (x.LRNo ?? string.Empty).Trim(), StringComparer.OrdinalIgnoreCase)
                .ToDictionary(g => g.Key, g => g.OrderBy(x => x.Id).First(), StringComparer.OrdinalIgnoreCase);

            foreach (var item in linked)
            {
                if (!lrMap.TryGetValue(item.LRNo, out var lr)) continue;
                if (lr == null) continue;
                lr.BillNo = billNo;
                lr.BillDate = item.BillDate;
                if (!string.IsNullOrWhiteSpace(item.Party)) lr.BillParty = item.Party;
                _lrRepo.Upsert(lr);
            }
        }

