        private async Task LoadCBSLedgerAsync()
        {
            if (_cbsLedgerLoadInProgress) return;
            _cbsLedgerLoadInProgress = true;
            try
            {
                var snapshot = await Task.Run(() =>
                {
                    SyncSystemCBSFromChallan();

                    var accounts = _cbsAccountRepo.GetAll();
                    var names = accounts
                        .Where(a => a.IsActive)
                        .Select(a => (a.AccountName ?? string.Empty).Trim())
                        .Where(a => a.Length > 0)
                        .Distinct(StringComparer.OrdinalIgnoreCase)
                        .OrderBy(a => a)
                        .ToList();

                    var entries = BuildCBSAccountViewRows(_cbsRepo.GetAll());
                    return Tuple.Create(accounts, names, entries);
                });

                await Dispatcher.InvokeAsync(() =>
                {
                    _allCbsAccounts = snapshot.Item1;

                    for (int i = CBSAccountNames.Count - 1; i >= 0; i--)
                    {
                        var existing = CBSAccountNames[i];
                        if (!snapshot.Item2.Any(n => string.Equals(n, existing, StringComparison.OrdinalIgnoreCase)))
                        {
                            CBSAccountNames.RemoveAt(i);
                        }
                    }

                    foreach (var name in snapshot.Item2)
                    {
                        if (!CBSAccountNames.Any(x => string.Equals(x, name, StringComparison.OrdinalIgnoreCase)))
                        {
                            CBSAccountNames.Add(name);
                        }
                    }

                    _allCbsEntries = snapshot.Item3;
                    if (CBSGrid != null) CBSGrid.ItemsSource = _allCbsEntries;
                    ReapplyCBSViewState();
                    RefreshDataGridItemsSafely(CBSGrid);
                    UpdateCBSFooter();
                });
            }
            catch (Exception ex)
            {
                LogException(nameof(LoadCBSLedgerAsync), ex);
            }
            finally
            {
                _cbsLedgerLoadInProgress = false;
            }
        }

        private void ApplyCBSSnapshot(List<CBSAccountEntry> accounts, List<CashBankStatementEntry> entries)
        {
            _allCbsAccounts = accounts ?? new List<CBSAccountEntry>();
            var names = _allCbsAccounts
                .Where(a => a.IsActive)
                .Select(a => (a.AccountName ?? string.Empty).Trim())
                .Where(a => a.Length > 0)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(a => a)
                .ToList();

            for (int i = CBSAccountNames.Count - 1; i >= 0; i--)
            {
                var existing = CBSAccountNames[i];
                if (!names.Any(n => string.Equals(n, existing, StringComparison.OrdinalIgnoreCase)))
                {
                    CBSAccountNames.RemoveAt(i);
                }
            }

            foreach (var name in names)
            {
                if (!CBSAccountNames.Any(x => string.Equals(x, name, StringComparison.OrdinalIgnoreCase)))
                {
                    CBSAccountNames.Add(name);
                }
            }

            if (entries != null)
            {
                _allCbsEntries = entries;
                if (CBSGrid != null) CBSGrid.ItemsSource = _allCbsEntries;
                ReapplyCBSViewState();
                RefreshDataGridItemsSafely(CBSGrid);
                UpdateCBSFooter();
            }
        }

        private void QueueCBSRefresh(bool rebuildSystemRows = false)
        {
            Task.Run(() =>
            {
                try
                {
                    if (rebuildSystemRows)
                    {
                        SyncSystemCBSFromChallan();
                    }

                    var accounts = _cbsAccountRepo.GetAll();
                    var entries = CBSLedgerView != null && CBSLedgerView.Dispatcher.Invoke(() => CBSLedgerView.Visibility == Visibility.Visible)
                        ? BuildCBSAccountViewRows(_cbsRepo.GetAll())
                        : null;

                    Dispatcher.BeginInvoke(new Action(() =>
                    {
                        ApplyCBSSnapshot(accounts, entries);
                        _refreshCbsSummaryView?.Invoke();
                    }));
                }
                catch (Exception ex)
                {
                    LogException(nameof(QueueCBSRefresh), ex);
                }
            });
        }

        private void RefreshCBSAccounts()
        {
            try
            {
                _allCbsAccounts = _cbsAccountRepo.GetAll();
                var names = _allCbsAccounts
                    .Where(a => a.IsActive)
                    .Select(a => (a.AccountName ?? string.Empty).Trim())
                    .Where(a => a.Length > 0)
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .OrderBy(a => a)
                    .ToList();

                for (int i = CBSAccountNames.Count - 1; i >= 0; i--)
                {
                    var existing = CBSAccountNames[i];
                    if (!names.Any(n => string.Equals(n, existing, StringComparison.OrdinalIgnoreCase)))
                    {
                        CBSAccountNames.RemoveAt(i);
                    }
                }

                foreach (var name in names)
                {
                    if (!CBSAccountNames.Any(x => string.Equals(x, name, StringComparison.OrdinalIgnoreCase)))
                    {
                        CBSAccountNames.Add(name);
                    }
                }

                RefreshDataGridItemsSafely(CBSGrid);
            }
            catch (Exception ex) { LogException(nameof(RefreshCBSAccounts), ex); }
        }

        private void RefreshCBSGrid()
        {
            try
            {
                SyncSystemCBSFromChallan();
                _allCbsEntries = BuildCBSAccountViewRows(_cbsRepo.GetAll());
                if (CBSGrid != null) CBSGrid.ItemsSource = _allCbsEntries;
                ReapplyCBSViewState();
            }
            catch (Exception ex) { LogException(nameof(BackfillAllLinkedLREntriesFromChallans), ex); }
        }

        private void SyncSystemCBSFromChallan()
        {
            try
            {
                if (BackendSettings.UseRemoteApi)
                {
                    return;
                }

                // Ensure required system accounts exist.
                AddCBSAccount("Purchase LHS", refreshUi: false, trackUndo: false, showError: false);
                AddCBSAccount("Challan LHS", refreshUi: false, trackUndo: false, showError: false);
                AddCBSAccount("BFRS", refreshUi: false, trackUndo: false, showError: false);

                // Rebuild only auto-generated purchase LHS rows. Manual rows must be preserved.
                var challans = new ChallanRepository().GetAll();
                var expectedAutoParticulars = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                foreach (var ch in challans.Where(x => !string.IsNullOrWhiteSpace(x.ChallanNumber)))
                {
                    expectedAutoParticulars.Add($"Challan {ch.ChallanNumber} - Advance Paid");
                    expectedAutoParticulars.Add($"Challan {ch.ChallanNumber} - Balance Paid");
                }

                var cbsRows = _cbsRepo.GetAll();
                var maxSr = cbsRows.Select(x => x.Sr).DefaultIfEmpty(0).Max();

                foreach (var row in cbsRows.Where(x => IsAutoChallanCBSRow(x, "Purchase LHS")).ToList())
                {
                    if (!expectedAutoParticulars.Contains((row.Particulars ?? string.Empty).Trim()))
                    {
                        _cbsRepo.Delete(row);
                        cbsRows.Remove(row);
                    }
                }

                foreach (var ch in challans)
                {
                    SyncChallanCBSFromChallan(ch, "Purchase LHS", cbsRows, ref maxSr);
                }
            }
            catch (Exception ex) { LogException(nameof(SyncSystemCBSFromChallan), ex); }
        }

        private void SyncLhsCBSFromChallan(ChallanEntry ch)
        {
            try
            {
                if (BackendSettings.UseRemoteApi)
                {
                    return;
                }

                if (ch == null || string.IsNullOrWhiteSpace(ch.ChallanNumber))
                {
                    return;
                }

                var accountName = GetChallanCBSAccountName();
                AddCBSAccount(accountName, refreshUi: false, trackUndo: false, showError: false);
                var cbsRows = _cbsRepo.GetAll();
                var maxSr = cbsRows.Select(x => x.Sr).DefaultIfEmpty(0).Max();
                SyncChallanCBSFromChallan(ch, accountName, cbsRows, ref maxSr);
            }
            catch (Exception ex)
            {
                LogException(nameof(SyncLhsCBSFromChallan), ex);
            }
        }

        private string GetChallanCBSAccountName()
        {
            return _isChallanLedgerMode ? "Challan LHS" : "Purchase LHS";
        }

        private void SyncChallanCBSFromChallan(ChallanEntry ch, string accountName, List<CashBankStatementEntry> cbsRows, ref int maxSr)
        {
            try
            {
                if (ch == null || string.IsNullOrWhiteSpace(ch.ChallanNumber))
                {
                    return;
                }

                accountName = string.IsNullOrWhiteSpace(accountName) ? "Purchase LHS" : accountName.Trim();

                var advanceParticulars = $"Challan {ch.ChallanNumber} - Advance Paid";
                var balanceParticulars = $"Challan {ch.ChallanNumber} - Balance Paid";

                var advanceNeft = ch.AdvanceNEFT;
                var advanceCash = ch.AdvanceCash;
                if (advanceNeft == 0m && advanceCash == 0m && ch.AdvanceAmount != 0m)
                {
                    advanceCash = ch.AdvanceAmount;
                }

                if (advanceNeft != 0m || advanceCash != 0m)
                {
                    var advDate = ch.AdvanceDate ?? ch.Date;
                    UpsertAutoLhsCBSRow(new CashBankStatementEntry
                    {
                        Sr = ++maxSr,
                        Date = advDate,
                        CBS = advDate.ToString("MMM-yy"),
                        AccountName = accountName,
                        Particulars = advanceParticulars,
                        Remarks = "Auto from Challan",
                        BankDr = 0m,
                        BankCr = advanceNeft,
                        CashDr = 0m,
                        CashCr = advanceCash
                    }, cbsRows);
                }
                else
                {
                    DeleteAutoLhsCBSRows(accountName, advanceParticulars, cbsRows);
                }

                if (ch.BalancePaidNEFT != 0m || ch.BalancePaidCash != 0m)
                {
                    var balDate = ch.BalancePaidDate ?? ch.Date;
                    UpsertAutoLhsCBSRow(new CashBankStatementEntry
                    {
                        Sr = ++maxSr,
                        Date = balDate,
                        CBS = balDate.ToString("MMM-yy"),
                        AccountName = accountName,
                        Particulars = balanceParticulars,
                        Remarks = "Auto from Challan",
                        BankDr = 0m,
                        BankCr = ch.BalancePaidNEFT,
                        CashDr = 0m,
                        CashCr = ch.BalancePaidCash
                    }, cbsRows);
                }
                else
                {
                    DeleteAutoLhsCBSRows(accountName, balanceParticulars, cbsRows);
                }
            }
            catch (Exception ex)
            {
                LogException(nameof(SyncLhsCBSFromChallan), ex);
            }
        }

        private bool IsAutoChallanCBSRow(CashBankStatementEntry row, string accountName)
        {
            return row != null &&
                   string.Equals((row.AccountName ?? string.Empty).Trim(), (accountName ?? string.Empty).Trim(), StringComparison.OrdinalIgnoreCase) &&
                   string.Equals((row.Remarks ?? string.Empty).Trim(), "Auto from Challan", StringComparison.OrdinalIgnoreCase);
        }

        private void UpsertAutoLhsCBSRow(CashBankStatementEntry row)
        {
            if (row == null || string.IsNullOrWhiteSpace(row.Particulars)) return;
            var cbsRows = _cbsRepo.GetAll();
            UpsertAutoLhsCBSRow(row, cbsRows);
        }

        private void UpsertAutoLhsCBSRow(CashBankStatementEntry row, List<CashBankStatementEntry> cbsRows)
        {
            if (row == null || string.IsNullOrWhiteSpace(row.Particulars)) return;
            if (cbsRows == null) cbsRows = new List<CashBankStatementEntry>();
            var key = row.Particulars.Trim();
            var accountName = (row.AccountName ?? string.Empty).Trim();
            var matches = cbsRows
                .Where(x => IsAutoChallanCBSRow(x, accountName))
                .Where(x => string.Equals((x.Particulars ?? string.Empty).Trim(), key, StringComparison.OrdinalIgnoreCase))
                .OrderBy(x => x.Id)
                .ToList();

            var existing = matches.FirstOrDefault();
            if (existing != null)
            {
                row.Id = existing.Id;
                if (row.Sr <= 0) row.Sr = existing.Sr;
            }

            foreach (var duplicate in matches.Skip(1))
            {
                try
                {
                    _cbsRepo.Delete(duplicate);
                    cbsRows.Remove(duplicate);
                }
                catch (Exception ex) { LogException(nameof(UpsertAutoLhsCBSRow), ex); }
            }

            _cbsRepo.Upsert(row);
            foreach (var old in cbsRows.Where(x => x.Id == row.Id).ToList())
            {
                cbsRows.Remove(old);
            }
            cbsRows.Add(row);
        }

        private void DeleteAutoLhsCBSRows(string accountName, string particulars, List<CashBankStatementEntry> cbsRows)
        {
            if (string.IsNullOrWhiteSpace(particulars) || cbsRows == null) return;
            foreach (var row in cbsRows
                         .Where(x => IsAutoChallanCBSRow(x, accountName))
                         .Where(x => string.Equals((x.Particulars ?? string.Empty).Trim(), particulars.Trim(), StringComparison.OrdinalIgnoreCase))
                         .ToList())
            {
                try
                {
                    _cbsRepo.Delete(row);
                    cbsRows.Remove(row);
                }
                catch (Exception ex) { LogException(nameof(DeleteAutoLhsCBSRows), ex); }
            }
        }

        private static bool IsRemoteApiHealthy()
        {
            try
            {
                using (var client = new System.Net.Http.HttpClient())
                {
                    client.Timeout = TimeSpan.FromSeconds(5);
                    var response = client.GetAsync(BackendSettings.ApiBaseUrl.TrimEnd('/') + "/api/health").GetAwaiter().GetResult();
                    return response.IsSuccessStatusCode;
                }
            }
            catch
            {
                return false;
            }
        }

        private List<CashBankStatementEntry> BuildCBSAccountViewRows(IEnumerable<CashBankStatementEntry> rawRows)
        {
            var groupedRows = (rawRows ?? Enumerable.Empty<CashBankStatementEntry>())
                .Where(x => !string.IsNullOrWhiteSpace(x.AccountName))
                .GroupBy(x => x.AccountName.Trim(), StringComparer.OrdinalIgnoreCase)
                .Select(g =>
                {
                    var latest = g.OrderByDescending(x => x.Date).ThenByDescending(x => x.Id).First();
                    return new CashBankStatementEntry
                    {
                        Id = latest.Id,
                        Sr = latest.Sr,
                        CBS = latest.CBS,
                        Date = g.Max(x => x.Date),
                        AccountName = latest.AccountName?.Trim(),
                        Particulars = latest.Particulars,
                        Remarks = latest.Remarks,
                        BankDr = g.Sum(x => x.BankDr),
                        BankCr = g.Sum(x => x.BankCr),
                        CashDr = g.Sum(x => x.CashDr),
                        CashCr = g.Sum(x => x.CashCr)
                    };
                })
                .ToList();

            var accountNames = (_cbsAccountRepo?.GetAll() ?? new List<CBSAccountEntry>())
                .Where(x => x != null && x.IsActive && !string.IsNullOrWhiteSpace(x.AccountName))
                .Select(x => x.AccountName.Trim())
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();

            foreach (var accountName in accountNames)
            {
                if (groupedRows.Any(x => string.Equals((x.AccountName ?? string.Empty).Trim(), accountName, StringComparison.OrdinalIgnoreCase)))
                {
                    continue;
                }

                groupedRows.Add(new CashBankStatementEntry
                {
                    Id = 0,
                    Sr = 0,
                    CBS = string.Empty,
                    Date = DateTime.MinValue,
                    AccountName = accountName,
                    Particulars = string.Empty,
                    Remarks = string.Empty,
                    BankDr = 0m,
                    BankCr = 0m,
                    CashDr = 0m,
                    CashCr = 0m
                });
            }

            return groupedRows
                .OrderByDescending(x => x.Date)
                .ThenBy(x => x.AccountName)
                .ToList();
        }

        private void UpdateCBSFooter()
        {
            if (CBSRecordsTextBlock == null && CBSBankNetTextBlock == null && CBSCashNetTextBlock == null) return;
            var cv = CollectionViewSource.GetDefaultView(CBSGrid?.ItemsSource);
            var rows = cv == null
                ? (CBSGrid?.ItemsSource as IEnumerable<CashBankStatementEntry>)?.Where(x => x != null).ToList() ?? new List<CashBankStatementEntry>()
                : cv.Cast<object>().OfType<CashBankStatementEntry>().ToList();

            var count = rows.Count;
            var bankNet = rows.Sum(x => x.BankDr - x.BankCr);
            var cashNet = rows.Sum(x => x.CashDr - x.CashCr);

            if (CBSRecordsTextBlock != null)
                CBSRecordsTextBlock.Text = $"Records: {count}";
            if (CBSBankNetTextBlock != null)
                CBSBankNetTextBlock.Text = $"Rs. {bankNet:N2}";
            if (CBSCashNetTextBlock != null)
                CBSCashNetTextBlock.Text = $"Rs. {cashNet:N2}";
        }

