            try
            {
                var repo = new VehicleRepository();
                foreach (var row in selected)
                {
                    try { repo.Delete(row); } catch { }
                }
                RefreshVehicleGrid();
            }
            catch (Exception ex)
            {
                MessageBox.Show("Vehicle delete failed: " + ex.Message, "Error", MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }

