        private string PromptCBSAccountName()
        {
            var dialog = new Window
            {
                Title = "Add Account",
                Owner = this,
                Width = 420,
                Height = 180,
                ResizeMode = ResizeMode.NoResize,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Background = Brushes.White
            };

            var root = new Grid { Margin = new Thickness(14) };
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

            var label = new TextBlock
            {
                Text = "Account Name",
                FontWeight = FontWeights.SemiBold,
                Margin = new Thickness(0, 0, 0, 6)
            };
            var box = new TextBox
            {
                Height = 30,
                Padding = new Thickness(6, 2, 6, 2)
            };
            AutomationProperties.SetAutomationId(box, "CBSAccountNameBox");
            var hint = new TextBlock
            {
                Text = "Type account name and press Enter or click Save.",
                Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#6B7280")),
                Margin = new Thickness(0, 8, 0, 0)
            };
            var footer = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right };
            var saveBtn = new Button { Content = "Save", Width = 90, Height = 30, Margin = new Thickness(0, 0, 8, 0) };
            var cancelBtn = new Button { Content = "Cancel", Width = 90, Height = 30 };
            footer.Children.Add(saveBtn);
            footer.Children.Add(cancelBtn);

            Grid.SetRow(label, 0);
            Grid.SetRow(box, 1);
            Grid.SetRow(hint, 2);
            Grid.SetRow(footer, 3);
            root.Children.Add(label);
            root.Children.Add(box);
            root.Children.Add(hint);
            root.Children.Add(footer);
            dialog.Content = root;

            string result = null;
            Action trySave = () =>
            {
                var value = (box.Text ?? string.Empty).Trim();
                if (value.Length == 0)
                {
                    MessageBox.Show(dialog, "Enter account name first.", "Validation", MessageBoxButton.OK, MessageBoxImage.Information);
                    box.Focus();
                    return;
                }
                result = value;
                dialog.DialogResult = true;
                dialog.Close();
            };

            saveBtn.Click += (_, __) => trySave();
            cancelBtn.Click += (_, __) => dialog.Close();
            box.KeyDown += (_, ke) =>
            {
                if (ke.Key == Key.Enter)
                {
                    ke.Handled = true;
                    trySave();
                }
                else if (ke.Key == Key.Escape)
                {
                    ke.Handled = true;
                    dialog.Close();
                }
            };

            dialog.Loaded += (_, __) => box.Focus();
            dialog.ShowDialog();
            return result;
        }

        private void AddCBSAccount(string name, bool refreshUi = true, bool trackUndo = true, bool showError = true)
        {
            try
            {
                var existing = _cbsAccountRepo.FindByName(name);
                if (existing != null)
                {
                    if (!existing.IsActive)
                    {
                        existing.IsActive = true;
                        _cbsAccountRepo.Upsert(existing);
                        if (trackUndo)
                        {
                            _cbsAccountUndoStack.Push(new CbsAccountUndoAction
                            {
                                Account = new CBSAccountEntry
                                {
                                    Id = existing.Id,
                                    Sr = existing.Sr,
                                    AccountName = existing.AccountName,
                                    IsActive = true
                                },
                                WasReactivated = true
                            });
                        }
                    }
                }
                else
                {
                    var created = new CBSAccountEntry
                    {
                        Sr = _cbsAccountRepo.GetMaxSr() + 1,
                        AccountName = name,
                        IsActive = true
                    };
                    _cbsAccountRepo.Upsert(created);
                    if (trackUndo)
                    {
                        _cbsAccountUndoStack.Push(new CbsAccountUndoAction
                        {
                            Account = created,
                            WasCreated = true
                        });
                    }
                }

                if (refreshUi)
                {
                    RefreshCBSAccounts();
                }
            }
            catch (Exception ex)
            {
                if (showError)
                {
                    MessageBox.Show("Unable to add account: " + ex.Message, "Error", MessageBoxButton.OK, MessageBoxImage.Error);
                }
                else
                {
                    LogException(nameof(AddCBSAccount), ex);
                }
            }
        }

        private bool UndoCBSAccountAction()
        {
            if (_cbsAccountUndoStack.Count == 0) return false;
            var action = _cbsAccountUndoStack.Pop();
            if (action?.Account == null) return false;

            try
            {
                if (action.WasCreated)
                {
                    var existing = _cbsAccountRepo.FindByName(action.Account.AccountName);
                    if (existing != null && existing.Id > 0)
                    {
                        _cbsAccountRepo.Delete(existing);
                    }
                }
                else if (action.WasReactivated)
                {
                    var existing = _cbsAccountRepo.FindByName(action.Account.AccountName);
                    if (existing != null && existing.Id > 0)
                    {
                        existing.IsActive = false;
                        _cbsAccountRepo.Upsert(existing);
                    }
                }
                else
                {
                    return false;
                }

                RefreshCBSAccounts();
                RefreshCBSGrid();
                return true;
            }
            catch (Exception ex)
            {
                MessageBox.Show("Unable to undo account action: " + ex.Message, "Undo Error", MessageBoxButton.OK, MessageBoxImage.Error);
                return false;
            }
        }

        private void CBSGrid_Loaded(object sender, RoutedEventArgs e)
        {
            AttachCBSResizePersistenceHooks();
        }

        private void AttachCBSResizePersistenceHooks()
        {
            if (CBSGrid == null) return;

            if (!_cbsGridResizeHooksAttached)
            {
                var rowHeightDpd = DependencyPropertyDescriptor.FromProperty(DataGrid.RowHeightProperty, typeof(DataGrid));
                rowHeightDpd?.AddValueChanged(CBSGrid, (_, __) => SaveGridSettings());
                _cbsGridResizeHooksAttached = true;
            }

            var widthDpd = DependencyPropertyDescriptor.FromProperty(DataGridColumn.WidthProperty, typeof(DataGridColumn));
            if (widthDpd == null) return;

            foreach (var col in CBSGrid.Columns)
            {
                if (col == null || _cbsWidthHookedColumns.Contains(col)) continue;
                widthDpd.AddValueChanged(col, (_, __) => SaveGridSettings());
                _cbsWidthHookedColumns.Add(col);
            }
        }

