        private static bool ValidateCbsSingleSide(CashBankStatementEntry row, out string message)
        {
            if (row != null)
            {
                if (row.BankDr != 0m && row.BankCr != 0m)
                {
                    message = "Only one of Bank Dr or Bank Cr can be entered in a single entry.";
                    return false;
                }

                if (row.CashDr != 0m && row.CashCr != 0m)
                {
                    message = "Only one of Cash Dr or Cash Cr can be entered in a single entry.";
                    return false;
                }
            }

            message = null;
            return true;
        }

        private static string SafeLogPath
        {
            get
            {
                var dir = System.IO.Path.Combine(
                    Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                    "Awagaman ERP",
                    "logs");
                if (!System.IO.Directory.Exists(dir))
                {
                    try { System.IO.Directory.CreateDirectory(dir); } catch { }
                }
                return System.IO.Path.Combine(dir, "app.log");
            }
        }

        private static void LogException(string context, Exception ex)
        {
            try
            {
                var line = $"{DateTime.Now:yyyy-MM-dd HH:mm:ss.fff} [{context}] {ex?.GetType().Name}: {ex?.Message}{Environment.NewLine}{ex?.StackTrace}{Environment.NewLine}";
                System.IO.File.AppendAllText(SafeLogPath, line);
                System.Diagnostics.Debug.WriteLine(line);
            }
            catch
            {
                // logging must never crash the app
            }
        }

        private void DeferUi(Action action, System.Windows.Threading.DispatcherPriority priority = System.Windows.Threading.DispatcherPriority.Background)
        {
            if (action == null) return;
            try
            {
                var dispatcher = Dispatcher ?? Application.Current?.Dispatcher;
                if (dispatcher == null)
                {
                    action();
                    return;
                }
                dispatcher.BeginInvoke(action, priority);
            }
            catch (Exception ex)
            {
                LogException(nameof(DeferUi), ex);
            }
        }

        private IDisposable EnterBusyCursor()
        {
            return new BusyCursorScope(this);
        }

        private void BeginBusyCursor()
        {
            try
            {
                if (Interlocked.Increment(ref _busyCursorDepth) == 1)
                {
                    Mouse.OverrideCursor = Cursors.Wait;
                }
            }
            catch (Exception ex)
            {
                LogException(nameof(BeginBusyCursor), ex);
            }
        }

        private void EndBusyCursor()
        {
            try
            {
                var next = Interlocked.Decrement(ref _busyCursorDepth);
                if (next <= 0)
                {
                    Interlocked.Exchange(ref _busyCursorDepth, 0);
                    Mouse.OverrideCursor = null;
                }
            }
            catch (Exception ex)
            {
                LogException(nameof(EndBusyCursor), ex);
            }
        }

        private sealed class BusyCursorScope : IDisposable
        {
            private MainWindow _owner;

            public BusyCursorScope(MainWindow owner)
            {
                _owner = owner;
                _owner?.BeginBusyCursor();
            }

            public void Dispose()
            {
                var owner = Interlocked.Exchange(ref _owner, null);
                owner?.EndBusyCursor();
            }
        }

