        private List<BillDueRow> LoadBillDueRows()
        {
            var lrByNo = _lrRepo.GetAll()
                .Where(x => !string.IsNullOrWhiteSpace(x.LRNo))
                .GroupBy(x => (x.LRNo ?? string.Empty).Trim(), StringComparer.OrdinalIgnoreCase)
                .ToDictionary(g => g.Key, g => g.First(), StringComparer.OrdinalIgnoreCase);

            return _billRepo.GetAll()
                .Where(b => !string.IsNullOrWhiteSpace(b.BillNo))
                .Select(b =>
                {
                    lrByNo.TryGetValue((b.LRNo ?? string.Empty).Trim(), out var lr);
                    return new BillDueRow
                    {
                        Party = (b.Party ?? lr?.BillParty ?? lr?.ConsignorName ?? string.Empty).Trim(),
                        BillNo = (b.BillNo ?? string.Empty).Trim(),
                        LRNo = (b.LRNo ?? string.Empty).Trim(),
                        From = (b.From ?? lr?.From ?? string.Empty).Trim(),
                        To = (b.To ?? lr?.To ?? string.Empty).Trim(),
                        Due = b.Due
                    };
                })
                .ToList();
        }

        private List<PartyDueSummaryOption> LoadPartyDueSummaryOptions()
        {
            return _billRepo.GetPartyDueSummary()
                .Select(x => new PartyDueSummaryOption
                {
                    Party = x.Party,
                    Bills = x.Bills,
                    Due = x.Due
                })
                .OrderByDescending(x => x.Due)
                .ToList();
        }

        private List<PartyDueSummaryOption> GetPartyDueSummaryOptionsCached(bool allowStale = true)
        {
            lock (_billDueCacheLock)
            {
                var isFresh = DateTime.UtcNow - _partyDueSummaryCacheUtc <= BillDueCacheLifetime;
                if (_partyDueSummaryCache.Count > 0 && (allowStale || isFresh))
                {
                    return _partyDueSummaryCache
                        .Select(x => new PartyDueSummaryOption { Party = x.Party, Bills = x.Bills, Due = x.Due })
                        .ToList();
                }
            }

            var fresh = LoadPartyDueSummaryOptions();
            lock (_billDueCacheLock)
            {
                _partyDueSummaryCache = fresh
                    .Select(x => new PartyDueSummaryOption { Party = x.Party, Bills = x.Bills, Due = x.Due })
                    .ToList();
                _partyDueSummaryCacheUtc = DateTime.UtcNow;
            }

            return fresh;
        }

        private List<BillDueDetailOption> LoadBillDueDetailsForParty(string party)
        {
            return _billRepo.GetBillDueDetailsForParty(party)
                .Select(x => new BillDueDetailOption
                {
                    BillNo = x.BillNo,
                    LRNos = x.LRNos,
                    From = x.From,
                    To = x.To,
                    Due = x.Due
                })
                .OrderByDescending(x => x.Due)
                .ToList();
        }

        private List<BillDueDetailOption> GetBillDueDetailsForPartyCached(string party, bool allowStale = true)
        {
            var key = (party ?? string.Empty).Trim();
            if (key.Length == 0)
            {
                return new List<BillDueDetailOption>();
            }

            lock (_billDueCacheLock)
            {
                if (_billDueDetailsCache.TryGetValue(key, out var cached) &&
                    _billDueDetailsCacheUtc.TryGetValue(key, out var stamp))
                {
                    var isFresh = DateTime.UtcNow - stamp <= BillDueCacheLifetime;
                    if (cached != null && (allowStale || isFresh))
                    {
                        return cached
                            .Select(x => new BillDueDetailOption
                            {
                                BillNo = x.BillNo,
                                LRNos = x.LRNos,
                                From = x.From,
                                To = x.To,
                                Due = x.Due
                            })
                            .ToList();
                    }
                }
            }

            var fresh = LoadBillDueDetailsForParty(key);
            lock (_billDueCacheLock)
            {
                _billDueDetailsCache[key] = fresh
                    .Select(x => new BillDueDetailOption
                    {
                        BillNo = x.BillNo,
                        LRNos = x.LRNos,
                        From = x.From,
                        To = x.To,
                        Due = x.Due
                    })
                    .ToList();
                _billDueDetailsCacheUtc[key] = DateTime.UtcNow;
            }

            return fresh;
        }

        private void InvalidateBillDueCaches()
        {
            lock (_billDueCacheLock)
            {
                _partyDueSummaryCache = new List<PartyDueSummaryOption>();
                _partyDueSummaryCacheUtc = DateTime.MinValue;
                _billDueDetailsCache.Clear();
                _billDueDetailsCacheUtc.Clear();
                _pendingBillOptionsCache.Clear();
                _pendingBillOptionsCacheUtc.Clear();
                _pendingBillPartiesCache.Clear();
                _pendingBillPartiesCacheUtc.Clear();
                _pendingBillPageCache.Clear();
                _pendingBillPageCacheUtc.Clear();
            }
        }

        private void WarmBillDueCachesInBackground()
        {
            Task.Run(() =>
            {
                try
                {
                    GetPartyDueSummaryOptionsCached(allowStale: false);
                    GetPendingBillPartiesCached(string.Empty, allowStale: false);
                }
                catch (Exception ex)
                {
                    LogException(nameof(WarmBillDueCachesInBackground), ex);
                }
            });
        }

        private List<PendingBillOption> LoadPendingBillOptions(string partyFilter = "", string billNoFilter = "")
        {
            return _billRepo.GetPendingBillOptions(partyFilter, billNoFilter)
                .Select(x => new PendingBillOption
                {
                    BillNo = (x.BillNo ?? string.Empty).Trim(),
                    Party = (x.Party ?? string.Empty).Trim(),
                    LRNos = (x.LRNos ?? string.Empty).Trim(),
                    Total = x.Total,
                    RCVD = x.RCVD,
                    TDS = x.TDS,
                    DED = x.DED
                })
                .OrderByDescending(x => x.BillNo, StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private RemotePagedResult<LREntry> GetPendingBillPageCached(int pageNumber, int pageSize, string searchFilter = "", bool allowStale = true)
        {
            pageNumber = Math.Max(pageNumber, 1);
            pageSize = Math.Max(pageSize, 1);
            searchFilter = (searchFilter ?? string.Empty).Trim();
            var cacheKey = pageNumber.ToString(CultureInfo.InvariantCulture) + "|" + pageSize.ToString(CultureInfo.InvariantCulture) + "|" + searchFilter.ToUpperInvariant();

            lock (_billDueCacheLock)
            {
                if (_pendingBillPageCache.TryGetValue(cacheKey, out var cached) &&
                    _pendingBillPageCacheUtc.TryGetValue(cacheKey, out var stamp))
                {
                    var isFresh = DateTime.UtcNow - stamp <= BillDueCacheLifetime;
                    if (cached != null && (allowStale || isFresh))
                    {
                        return new RemotePagedResult<LREntry>
                        {
                            TotalCount = cached.TotalCount,
                            Items = cached.Items?.Select(CloneLrEntry).ToList() ?? new List<LREntry>()
                        };
                    }
                }
            }

            var fresh = _lrRepo.GetPendingBillPage(pageNumber, pageSize, searchFilter) ?? new RemotePagedResult<LREntry>();
            lock (_billDueCacheLock)
            {
                _pendingBillPageCache[cacheKey] = new RemotePagedResult<LREntry>
                {
                    TotalCount = fresh.TotalCount,
                    Items = fresh.Items?.Select(CloneLrEntry).ToList() ?? new List<LREntry>()
                };
                _pendingBillPageCacheUtc[cacheKey] = DateTime.UtcNow;
            }

            return new RemotePagedResult<LREntry>
            {
                TotalCount = fresh.TotalCount,
                Items = fresh.Items?.Select(CloneLrEntry).ToList() ?? new List<LREntry>()
            };
        }

        private List<PendingBillOption> GetPendingBillOptionsCached(string partyFilter = "", string billNoFilter = "", bool allowStale = true)
        {
            var cacheKey = ((partyFilter ?? string.Empty).Trim() + "|" + (billNoFilter ?? string.Empty).Trim()).ToUpperInvariant();
            lock (_billDueCacheLock)
            {
                if (_pendingBillOptionsCache.TryGetValue(cacheKey, out var cached) &&
                    _pendingBillOptionsCacheUtc.TryGetValue(cacheKey, out var stamp))
                {
                    var isFresh = DateTime.UtcNow - stamp <= BillDueCacheLifetime;
                    if (cached != null && (allowStale || isFresh))
                    {
                        return cached.Select(ClonePendingBillOption).ToList();
                    }
                }
            }

            var fresh = LoadPendingBillOptions(partyFilter, billNoFilter);
            lock (_billDueCacheLock)
            {
                _pendingBillOptionsCache[cacheKey] = fresh.Select(ClonePendingBillOption).ToList();
                _pendingBillOptionsCacheUtc[cacheKey] = DateTime.UtcNow;
            }
            return fresh;
        }

        private List<string> LoadPendingBillParties(string partyFilter = "")
        {
            return _billRepo.GetPendingBillParties(partyFilter)
                .Select(x => (x ?? string.Empty).Trim())
                .Where(x => x.Length > 0)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(x => x)
                .ToList();
        }

        private List<string> GetPendingBillPartiesCached(string partyFilter = "", bool allowStale = true)
        {
            var cacheKey = (partyFilter ?? string.Empty).Trim().ToUpperInvariant();
            lock (_billDueCacheLock)
            {
                if (_pendingBillPartiesCache.TryGetValue(cacheKey, out var cached) &&
                    _pendingBillPartiesCacheUtc.TryGetValue(cacheKey, out var stamp))
                {
                    var isFresh = DateTime.UtcNow - stamp <= BillDueCacheLifetime;
                    if (cached != null && (allowStale || isFresh))
                    {
                        return cached.ToList();
                    }
                }
            }

            var fresh = LoadPendingBillParties(partyFilter);
            lock (_billDueCacheLock)
            {
                _pendingBillPartiesCache[cacheKey] = fresh.ToList();
                _pendingBillPartiesCacheUtc[cacheKey] = DateTime.UtcNow;
            }
            return fresh;
        }

        private static PendingBillOption ClonePendingBillOption(PendingBillOption source)
        {
            return source == null
                ? new PendingBillOption()
                : new PendingBillOption
                {
                    BillNo = source.BillNo,
                    Party = source.Party,
                    LRNos = source.LRNos,
                    Total = source.Total,
                    RCVD = source.RCVD,
                    TDS = source.TDS,
                    DED = source.DED
                };
        }

        private static LREntry CloneLrEntry(LREntry source)
        {
            if (source == null) return new LREntry();

            return new LREntry
            {
                Id = source.Id,
                Sr = source.Sr,
                LRNo = source.LRNo,
                Date = source.Date,
                ConsignorName = source.ConsignorName,
                ConsignorAddress = source.ConsignorAddress,
                ConsignorGST = source.ConsignorGST,
                ConsigneeName = source.ConsigneeName,
                ConsigneeAddress = source.ConsigneeAddress,
                ConsigneeGST = source.ConsigneeGST,
                From = source.From,
                To = source.To,
                VehicleNo = source.VehicleNo,
                VehicleType = source.VehicleType,
                SizeL = source.SizeL,
                SizeW = source.SizeW,
                SizeH = source.SizeH,
                ActualWeight = source.ActualWeight,
                ChargedWeight = source.ChargedWeight,
                PKG = source.PKG,
                PkgType = source.PkgType,
                Description = source.Description,
                Invoice = source.Invoice,
                Value = source.Value,
                CHNo = source.CHNo,
                TotalFreight = source.TotalFreight,
                Hamali = source.Hamali,
                Detention = source.Detention,
                Others = source.Others,
                StCharge = source.StCharge,
                NEFT = source.NEFT,
                CASH = source.CASH,
                TDS = source.TDS,
                Ded = source.Ded,
                BillNo = source.BillNo,
                BillDate = source.BillDate,
                BILL = source.BILL,
                ChallanLorryHire = source.ChallanLorryHire,
                BillParty = source.BillParty,
                Broker = source.Broker,
                FrtType = source.FrtType,
                PayType = source.PayType,
                Comm = source.Comm,
                Paid = source.Paid,
                PreserveImportedBilling = source.PreserveImportedBilling
            };
        }

        private void OpenReceiveBillAmount_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                var preselectedBill = BillLedgerGrid?.SelectedItem as BillEntry;
                var preselectedBillNo = (preselectedBill?.BillNo ?? string.Empty).Trim();
                var preselectedParty = (preselectedBill?.Party ?? string.Empty).Trim();
                if (string.IsNullOrWhiteSpace(preselectedParty) && !string.IsNullOrWhiteSpace(preselectedBillNo))
                {
                    preselectedParty = _billRepo.GetByBillNo(preselectedBillNo)
                        .Select(x => (x.Party ?? string.Empty).Trim())
                        .FirstOrDefault(x => !string.IsNullOrWhiteSpace(x)) ?? string.Empty;
                }

                MouseButtonEventHandler overwriteZeroOnClick = (s, e2) =>
                {
                    if (!(s is TextBox tb)) return;
                    if (!tb.IsKeyboardFocusWithin)
                    {
                        e2.Handled = true;
                        tb.Focus();
                    }
                };
                KeyboardFocusChangedEventHandler overwriteZeroOnFocus = (s, e2) =>
                {
                    if (s is TextBox tb) tb.SelectAll();
                };

                var dialog = new Window
                {
                    Title = "Receive Bill Amount",
                    Width = 560,
                    Height = 620,
                    Owner = this,
                    WindowStartupLocation = WindowStartupLocation.CenterOwner,
                    ResizeMode = ResizeMode.NoResize,
                    Background = System.Windows.Media.Brushes.White
                };

                var root = new Grid { Margin = new Thickness(14) };
                for (int i = 0; i < 12; i++) root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
                root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                root.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(130) });
                root.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

                var partyLabel = new TextBlock { Text = "Party Search", Margin = new Thickness(0, 0, 8, 8), VerticalAlignment = VerticalAlignment.Center };
                var partyBox = new ComboBox { IsEditable = true, IsTextSearchEnabled = false, Height = 28, Margin = new Thickness(0, 0, 0, 8) };
                Grid.SetRow(partyLabel, 0); Grid.SetColumn(partyLabel, 0);
                Grid.SetRow(partyBox, 0); Grid.SetColumn(partyBox, 1);
                root.Children.Add(partyLabel); root.Children.Add(partyBox);

                var billLabel = new TextBlock { Text = "Bill Number", Margin = new Thickness(0, 0, 8, 8), VerticalAlignment = VerticalAlignment.Center };
                var billBox = new ComboBox { IsEditable = true, Height = 28, Margin = new Thickness(0, 0, 0, 8), DisplayMemberPath = "LRDisplay" };
                Grid.SetRow(billLabel, 1); Grid.SetColumn(billLabel, 0);
                Grid.SetRow(billBox, 1); Grid.SetColumn(billBox, 1);
                root.Children.Add(billLabel); root.Children.Add(billBox);

                var lrLabel = new TextBlock { Text = "Select LR", Margin = new Thickness(0, 0, 8, 8), VerticalAlignment = VerticalAlignment.Center };
                var lrBox = new ComboBox { IsEditable = false, Height = 28, Margin = new Thickness(0, 0, 0, 8) };
                Grid.SetRow(lrLabel, 2); Grid.SetColumn(lrLabel, 0);
                Grid.SetRow(lrBox, 2); Grid.SetColumn(lrBox, 1);
                root.Children.Add(lrLabel); root.Children.Add(lrBox);

                var totalLabel = new TextBlock { Text = "Total Due", Margin = new Thickness(0, 0, 8, 8), VerticalAlignment = VerticalAlignment.Center };
                var totalText = new TextBlock { Text = "0.00", FontWeight = FontWeights.SemiBold, Margin = new Thickness(0, 4, 0, 8) };
                Grid.SetRow(totalLabel, 3); Grid.SetColumn(totalLabel, 0);
                Grid.SetRow(totalText, 3); Grid.SetColumn(totalText, 1);
                root.Children.Add(totalLabel); root.Children.Add(totalText);

                var rcvdLabel = new TextBlock { Text = "Received", Margin = new Thickness(0, 0, 8, 8), VerticalAlignment = VerticalAlignment.Center };
                var rcvdBox = new TextBox { Height = 28, Text = "0", Margin = new Thickness(0, 0, 0, 8) };
                rcvdBox.PreviewMouseLeftButtonDown += overwriteZeroOnClick;
                rcvdBox.GotKeyboardFocus += overwriteZeroOnFocus;
                Grid.SetRow(rcvdLabel, 4); Grid.SetColumn(rcvdLabel, 0);
                Grid.SetRow(rcvdBox, 4); Grid.SetColumn(rcvdBox, 1);
                root.Children.Add(rcvdLabel); root.Children.Add(rcvdBox);

                var tdsLabel = new TextBlock { Text = "TDS", Margin = new Thickness(0, 0, 8, 8), VerticalAlignment = VerticalAlignment.Center };
                var tdsBox = new TextBox { Height = 28, Text = "0", Margin = new Thickness(0, 0, 0, 8) };
                tdsBox.PreviewMouseLeftButtonDown += overwriteZeroOnClick;
                tdsBox.GotKeyboardFocus += overwriteZeroOnFocus;
                Grid.SetRow(tdsLabel, 5); Grid.SetColumn(tdsLabel, 0);
                Grid.SetRow(tdsBox, 5); Grid.SetColumn(tdsBox, 1);
                root.Children.Add(tdsLabel); root.Children.Add(tdsBox);

                var dedLabel = new TextBlock { Text = "Deduction", Margin = new Thickness(0, 0, 8, 8), VerticalAlignment = VerticalAlignment.Center };
                var dedBox = new TextBox { Height = 28, Text = "0", Margin = new Thickness(0, 0, 0, 8) };
                dedBox.PreviewMouseLeftButtonDown += overwriteZeroOnClick;
                dedBox.GotKeyboardFocus += overwriteZeroOnFocus;
                Grid.SetRow(dedLabel, 6); Grid.SetColumn(dedLabel, 0);
                Grid.SetRow(dedBox, 6); Grid.SetColumn(dedBox, 1);
                root.Children.Add(dedLabel); root.Children.Add(dedBox);

                var dueLabel = new TextBlock { Text = "Due After Entry", Margin = new Thickness(0, 0, 8, 8), VerticalAlignment = VerticalAlignment.Center };
                var dueText = new TextBlock { Text = "0.00", FontWeight = FontWeights.Bold, Foreground = System.Windows.Media.Brushes.DarkRed, Margin = new Thickness(0, 4, 0, 8) };
                Grid.SetRow(dueLabel, 7); Grid.SetColumn(dueLabel, 0);
                Grid.SetRow(dueText, 7); Grid.SetColumn(dueText, 1);
                root.Children.Add(dueLabel); root.Children.Add(dueText);

                var mopLabel = new TextBlock { Text = "MOP", Margin = new Thickness(0, 0, 8, 8), VerticalAlignment = VerticalAlignment.Center };
                var mopBox = new ComboBox { Height = 28, Margin = new Thickness(0, 0, 0, 8) };
                mopBox.Items.Add("NEFT");
                mopBox.Items.Add("CASH");
                mopBox.Items.Add("OTHER");
                mopBox.SelectedIndex = 0;
                Grid.SetRow(mopLabel, 8); Grid.SetColumn(mopLabel, 0);
                Grid.SetRow(mopBox, 8); Grid.SetColumn(mopBox, 1);
                root.Children.Add(mopLabel); root.Children.Add(mopBox);

                var mrLabel = new TextBlock { Text = "MR", Margin = new Thickness(0, 0, 8, 8), VerticalAlignment = VerticalAlignment.Center };
                var mrBox = new TextBox { Height = 28, Margin = new Thickness(0, 0, 0, 8) };
                Grid.SetRow(mrLabel, 9); Grid.SetColumn(mrLabel, 0);
                Grid.SetRow(mrBox, 9); Grid.SetColumn(mrBox, 1);
                root.Children.Add(mrLabel); root.Children.Add(mrBox);

                var recvDateLabel = new TextBlock { Text = "Received Date", Margin = new Thickness(0, 0, 8, 8), VerticalAlignment = VerticalAlignment.Center };
                var recvDate = new DatePicker { Height = 28, SelectedDate = DateTime.Today, Margin = new Thickness(0, 0, 0, 8) };
                Grid.SetRow(recvDateLabel, 10); Grid.SetColumn(recvDateLabel, 0);
                Grid.SetRow(recvDate, 10); Grid.SetColumn(recvDate, 1);
                root.Children.Add(recvDateLabel); root.Children.Add(recvDate);

                var remarksLabel = new TextBlock { Text = "Remarks (Other)", Margin = new Thickness(0, 0, 8, 8), VerticalAlignment = VerticalAlignment.Top };
                var remarksBox = new TextBox { Height = 56, AcceptsReturn = true, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 0, 0, 8) };
                Grid.SetRow(remarksLabel, 11); Grid.SetColumn(remarksLabel, 0);
                Grid.SetRow(remarksBox, 11); Grid.SetColumn(remarksBox, 1);
                root.Children.Add(remarksLabel); root.Children.Add(remarksBox);

                var hint = new TextBlock { Text = "Only bills with due amount > 0 are shown.", Foreground = System.Windows.Media.Brushes.Gray, Margin = new Thickness(0, 2, 0, 0) };
                Grid.SetRow(hint, 12); Grid.SetColumnSpan(hint, 2);
                root.Children.Add(hint);

                var footer = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 12, 0, 0) };
                var saveBtn = new Button { Content = "Save", Width = 90, Height = 30, Margin = new Thickness(0, 0, 8, 0) };
                var cancelBtn = new Button { Content = "Cancel", Width = 90, Height = 30 };
                footer.Children.Add(saveBtn);
                footer.Children.Add(cancelBtn);
                Grid.SetRow(footer, 13); Grid.SetColumnSpan(footer, 2);
                root.Children.Add(footer);

                dialog.Content = root;

                List<PendingBillOption> options = new List<PendingBillOption>();
                string lastPartyKey = string.Empty;
                Action refreshLrOptions = () =>
                {
                    var selected = billBox.SelectedItem as PendingBillOption;
                    IEnumerable<string> lrItems = Enumerable.Empty<string>();
                    if (selected != null)
                    {
                        lrItems = _billRepo.GetByBillNo(selected.BillNo)
                            .SelectMany(x => SplitLrNumbers(x?.LRNo))
                            .Where(x => !string.IsNullOrWhiteSpace(x))
                            .Distinct(StringComparer.OrdinalIgnoreCase)
                            .ToList();
                    }

                    lrBox.ItemsSource = lrItems.ToList();
                    lrBox.SelectedItem = null;
                    if (lrBox.Items.Count > 0)
                    {
                        lrBox.SelectedIndex = 0;
                    }
                };
                Action refreshPartySuggestions = () =>
                {
                    var typed = (partyBox.Text ?? string.Empty).Trim();
                    if (typed.Length == 0 && string.IsNullOrWhiteSpace(preselectedParty))
                    {
                        partyBox.ItemsSource = null;
                        partyBox.IsDropDownOpen = false;
                        return;
                    }

                    var parties = GetPendingBillPartiesCached(typed);
                    partyBox.ItemsSource = parties;
                    partyBox.IsDropDownOpen = parties.Count > 0 && !string.IsNullOrWhiteSpace(typed);
                };
                Action refreshOptions = () =>
                {
                    var selectedParty = (partyBox.Text ?? string.Empty).Trim();
                    if (string.IsNullOrWhiteSpace(selectedParty))
                    {
                        lastPartyKey = string.Empty;
                        options = new List<PendingBillOption>();
                        billBox.ItemsSource = options;
                        billBox.SelectedItem = null;
                        billBox.Text = string.Empty;
                        refreshLrOptions();
                        totalText.Text = "0.00";
                        dueText.Text = "0.00";
                        return;
                    }

                    if (!string.Equals(lastPartyKey, selectedParty, StringComparison.OrdinalIgnoreCase))
                    {
                        billBox.SelectedItem = null;
                        billBox.Text = string.Empty;
                        lastPartyKey = selectedParty;
                    }

                    var selectedBillNo = (billBox.SelectedItem as PendingBillOption)?.BillNo;
                    if (string.IsNullOrWhiteSpace(selectedBillNo))
                    {
                        selectedBillNo = ExtractBillNoToken(billBox.Text);
                    }
                    options = GetPendingBillOptionsCached(selectedParty, selectedBillNo);
                    billBox.ItemsSource = options;
                    var chosen = options.FirstOrDefault(x => string.Equals(x.BillNo, selectedBillNo, StringComparison.OrdinalIgnoreCase));
                    if (chosen != null)
                    {
                        billBox.SelectedItem = chosen;
                    }
                    else
                    {
                        refreshLrOptions();
                    }
                };

                Action recomputeDue = () =>
                {
                    var selectedParty = (partyBox.Text ?? string.Empty).Trim();
                    if (string.IsNullOrWhiteSpace(selectedParty))
                    {
                        totalText.Text = "0.00";
                        dueText.Text = "0.00";
                        return;
                    }

                    var selected = billBox.SelectedItem as PendingBillOption;
                    decimal baseDue = selected?.Due ?? options.Sum(x => x.Due);
                    totalText.Text = baseDue.ToString("N2");
                    decimal rcvd = ParseDec(rcvdBox.Text);
                    decimal tds = ParseDec(tdsBox.Text);
                    decimal ded = ParseDec(dedBox.Text);
                    var due = baseDue - rcvd - tds - ded;
                    dueText.Text = due.ToString("N2");
                };

                partyBox.AddHandler(System.Windows.Controls.TextBox.TextChangedEvent, new TextChangedEventHandler((_, __) =>
                {
                    refreshPartySuggestions();
                    refreshOptions();
                    recomputeDue();
                }));
                partyBox.SelectionChanged += (_, __) =>
                {
                    refreshOptions();
                    recomputeDue();
                };
                billBox.SelectionChanged += (_, __) =>
                {
                    var selected = billBox.SelectedItem as PendingBillOption;
                    if (selected != null)
                    {
                        if (string.IsNullOrWhiteSpace(partyBox.Text)) partyBox.Text = selected.Party;
                    }
                    refreshLrOptions();
                    recomputeDue();
                };
                billBox.LostFocus += (_, __) =>
                {
                    var typed = ExtractBillNoToken(billBox.Text);
                    if (typed.Length == 0) return;
                    var found = options.FirstOrDefault(x => string.Equals(x.BillNo, typed, StringComparison.OrdinalIgnoreCase));
                    if (found != null) billBox.SelectedItem = found;
                    else refreshLrOptions();
                    recomputeDue();
                };
                rcvdBox.TextChanged += (_, __) => recomputeDue();
                tdsBox.TextChanged += (_, __) => recomputeDue();
                dedBox.TextChanged += (_, __) => recomputeDue();
                mopBox.SelectionChanged += (_, __) => { };

                saveBtn.Click += async (_, __) =>
                {
                    var selected = billBox.SelectedItem as PendingBillOption;
                    if (selected == null)
                    {
                        var typed = ExtractBillNoToken(billBox.Text);
                        selected = options.FirstOrDefault(x => string.Equals(x.BillNo, typed, StringComparison.OrdinalIgnoreCase));
                    }
                    if (selected == null)
                    {
                        MessageBox.Show("Select a valid pending bill number.", "Validation", MessageBoxButton.OK, MessageBoxImage.Warning);
                        return;
                    }
                    var rcvd = ParseDec(rcvdBox.Text);
                    var tds = ParseDec(tdsBox.Text);
                    var ded = ParseDec(dedBox.Text);
                    var mop = ((mopBox.SelectedItem as string) ?? "NEFT").Trim();
                    var mr = (mrBox.Text ?? string.Empty).Trim();
                    var recvDt = recvDate.SelectedDate ?? DateTime.Today;
                    var selectedLrNo = (lrBox.SelectedItem as string) ?? string.Empty;
                    var remarks = remarksBox.Text ?? string.Empty;
                    if (rcvd < 0 || tds < 0 || ded < 0)
                    {
                        MessageBox.Show("Amounts cannot be negative.", "Validation", MessageBoxButton.OK, MessageBoxImage.Warning);
                        return;
                    }

                    saveBtn.IsEnabled = false;
                    cancelBtn.IsEnabled = false;
                    BeginBusyCursor();
                    try
                    {
                        await Task.Run(() => ApplyReceiveOnBill(
                            selected.BillNo,
                            selectedLrNo,
                            rcvd,
                            tds,
                            ded,
                            mop,
                            mr,
                            recvDt,
                            remarks));

                        if (BillLedgerView != null && BillLedgerView.Visibility == Visibility.Visible)
                        {
                            BillVM?.RefreshAfterDelete();
                            BillUpdatePageUI();
                        }

                        if (CBSLedgerView != null && CBSLedgerView.Visibility == Visibility.Visible)
                        {
                            RefreshCBSGrid();
                        }

                        QueueDashboardRefresh();
                        dialog.DialogResult = true;
                        dialog.Close();
                    }
                    catch (Exception ex)
                    {
                        MessageBox.Show("Unable to save bill receipt: " + ex.Message, "Error", MessageBoxButton.OK, MessageBoxImage.Error);
                    }
                    finally
                    {
                        EndBusyCursor();
                        saveBtn.IsEnabled = true;
                        cancelBtn.IsEnabled = true;
                    }
                };
                cancelBtn.Click += (_, __) => { dialog.DialogResult = false; dialog.Close(); };

                refreshPartySuggestions();
                if (!string.IsNullOrWhiteSpace(preselectedParty) || !string.IsNullOrWhiteSpace(preselectedBillNo))
                {
                    if (!string.IsNullOrWhiteSpace(preselectedParty))
                    {
                        partyBox.Text = preselectedParty;
                    }
                    if (!string.IsNullOrWhiteSpace(preselectedBillNo))
                    {
                        billBox.Text = preselectedBillNo;
                    }
                }
                refreshOptions();
                if (!string.IsNullOrWhiteSpace(preselectedBillNo))
                {
                    var selectedOption = options.FirstOrDefault(x => string.Equals((x.BillNo ?? string.Empty).Trim(), preselectedBillNo, StringComparison.OrdinalIgnoreCase));
                    if (selectedOption != null)
                    {
                        billBox.SelectedItem = selectedOption;
                    }
                }
                recomputeDue();
                dialog.ShowDialog();
            }
            catch (Exception ex)
            {
                MessageBox.Show("Unable to open receive bill dialog: " + ex.Message, "Error", MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }

        private void OpenBillReceiptHistory_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                var selected = BillLedgerGrid?.SelectedItem as BillEntry;
                if (selected == null)
                {
                    MessageBox.Show("Select a bill row first.", "No Selection", MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }

                ShowBillReceiptHistory(selected.BillNo, selected.Party);
            }
            catch (Exception ex)
            {
                MessageBox.Show("Unable to open bill receipt history: " + ex.Message, "Error", MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }

        private void ShowBillReceiptHistory(string billNo, string partyName)
        {
            billNo = (billNo ?? string.Empty).Trim();
            if (string.IsNullOrWhiteSpace(billNo))
            {
                MessageBox.Show("Bill number is required.", "Validation", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            var repo = new BillReceiptRepository();
            var receipts = repo.GetByBillNo(billNo);
            decimal totalReceived = receipts.Sum(x => x.RCVD);
            decimal totalTds = receipts.Sum(x => x.TDS);
            decimal totalDed = receipts.Sum(x => x.DED);
            decimal dueAfter = receipts.Count > 0 ? receipts.Last().DueAfter : 0m;
            if (receipts.Count == 0)
            {
                dueAfter = _billRepo.GetAll()
                    .Where(x => string.Equals((x.BillNo ?? string.Empty).Trim(), billNo, StringComparison.OrdinalIgnoreCase))
                    .Sum(x => x.Due);
            }

            var dialog = new Window
            {
                Title = $"Bill Receipt History - {billNo}",
                Owner = this,
                Width = 980,
                Height = 560,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Background = Brushes.White
            };

            var root = new Grid { Margin = new Thickness(14) };
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

            var head = new StackPanel { Margin = new Thickness(0, 0, 0, 12) };
            head.Children.Add(new TextBlock
            {
                Text = $"Bill No: {billNo}",
                FontSize = 18,
                FontWeight = FontWeights.SemiBold,
                Foreground = Brushes.Black
            });
            if (!string.IsNullOrWhiteSpace(partyName))
            {
                head.Children.Add(new TextBlock
                {
                    Text = $"Party: {partyName}",
                    FontSize = 13,
                    Foreground = Brushes.DimGray,
                    Margin = new Thickness(0, 4, 0, 0)
                });
            }
            root.Children.Add(head);

            var summary = new Border
            {
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F8FAFC")),
                BorderBrush = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#D8E1EE")),
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(8),
                Padding = new Thickness(12),
                Margin = new Thickness(0, 0, 0, 12)
            };
            var summaryGrid = new Grid();
            summaryGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            summaryGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            summaryGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            summaryGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

            summaryGrid.Children.Add(MakeSummaryTile("Receipt Count", receipts.Count.ToString(), "#1D4ED8", 0));
            summaryGrid.Children.Add(MakeSummaryTile("Received Total", $"Rs. {totalReceived:N2}", "#0F766E", 1));
            summaryGrid.Children.Add(MakeSummaryTile("TDS + Ded", $"Rs. {(totalTds + totalDed):N2}", "#B45309", 2));
            summaryGrid.Children.Add(MakeSummaryTile("Due After Last Receipt", $"Rs. {dueAfter:N2}", "#DC2626", 3));
            summary.Child = summaryGrid;
            Grid.SetRow(summary, 1);
            root.Children.Add(summary);

                var grid = new DataGrid
                {
                    AutoGenerateColumns = false,
                    IsReadOnly = true,
                CanUserAddRows = false,
                Background = Brushes.White,
                BorderBrush = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#D8E1EE")),
                BorderThickness = new Thickness(1),
                RowHeight = 30,
                SelectionMode = DataGridSelectionMode.Single,
                SelectionUnit = DataGridSelectionUnit.FullRow,
                    FontSize = 12
                };
                grid.Columns.Add(new DataGridTextColumn { Header = "Bill Date", Binding = new Binding("BillDate") { StringFormat = "dd-MMM-yyyy" }, Width = 110 });
                grid.Columns.Add(new DataGridTextColumn { Header = "LR No", Binding = new Binding("LRNo"), Width = 100 });
                grid.Columns.Add(new DataGridTextColumn { Header = "Receipt Date", Binding = new Binding("ReceiptDate") { StringFormat = "dd-MMM-yyyy" }, Width = 120 });
                grid.Columns.Add(new DataGridTextColumn { Header = "MOP", Binding = new Binding("MOP"), Width = 80 });
                grid.Columns.Add(new DataGridTextColumn { Header = "Received", Binding = new Binding("RCVD") { StringFormat = "N2" }, Width = 110 });
                grid.Columns.Add(new DataGridTextColumn { Header = "TDS", Binding = new Binding("TDS") { StringFormat = "N2" }, Width = 100 });
                grid.Columns.Add(new DataGridTextColumn { Header = "Ded", Binding = new Binding("DED") { StringFormat = "N2" }, Width = 100 });
                grid.Columns.Add(new DataGridTextColumn { Header = "MR", Binding = new Binding("MR"), Width = 90 });
                grid.Columns.Add(new DataGridTextColumn { Header = "Remarks", Binding = new Binding("Remarks"), Width = new DataGridLength(1, DataGridLengthUnitType.Star) });
                grid.Columns.Add(new DataGridTextColumn { Header = "Due After", Binding = new Binding("DueAfter") { StringFormat = "N2" }, Width = 120 });
            grid.ItemsSource = receipts;
            Grid.SetRow(grid, 2);
            root.Children.Add(grid);

            var footer = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 12, 0, 0) };
            var editReceipt = new Button
            {
                Content = "Edit Selected",
                Width = 110,
                Height = 30,
                Margin = new Thickness(0, 0, 8, 0)
            };
            editReceipt.Click += (_, __) =>
            {
                var selectedReceipt = grid.SelectedItem as BillReceiptEntry;
                if (selectedReceipt == null)
                {
                    MessageBox.Show("Select a receipt row to edit.", "Receipt History", MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }

                if (!EditBillReceiptEntry(selectedReceipt))
                {
                    return;
                }

                BillVM?.RefreshAfterDelete();
                BillUpdatePageUI();
                LRVM?.RefreshAfterDelete();
                LRUpdatePageUI();
                RefreshCBSGrid();
                RefreshDashboard();
                dialog.Close();
                ShowBillReceiptHistory(billNo, partyName);
            };
            footer.Children.Add(editReceipt);
            var close = new Button { Content = "Close", Width = 90, Height = 30 };
            close.Click += (_, __) => dialog.Close();
            footer.Children.Add(close);
            Grid.SetRow(footer, 3);
            root.Children.Add(footer);

            dialog.Content = root;
            dialog.ShowDialog();
        }

        private bool EditBillReceiptEntry(BillReceiptEntry existing)
        {
            if (existing == null) return false;

            var working = new BillReceiptEntry
            {
                Id = existing.Id,
                BillNo = existing.BillNo,
                LRNo = existing.LRNo,
                Party = existing.Party,
                BillTotal = existing.BillTotal,
                BillDate = existing.BillDate,
                ReceiptDate = existing.ReceiptDate,
                RCVD = existing.RCVD,
                TDS = existing.TDS,
                DED = existing.DED,
                MOP = existing.MOP,
                MR = existing.MR,
                Remarks = existing.Remarks,
                DueAfter = existing.DueAfter,
                CreatedAt = existing.CreatedAt
            };

            var dialog = new Window
            {
                Title = $"Edit Bill Receipt - {working.BillNo}",
                Owner = this,
                Width = 480,
                Height = 420,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Background = Brushes.White,
                ResizeMode = ResizeMode.NoResize
            };

            var root = new Grid { Margin = new Thickness(16) };
            for (int i = 0; i < 9; i++) root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(130) });
            root.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

            void AddLabel(string text, int row)
            {
                var label = new TextBlock { Text = text, Margin = new Thickness(0, 8, 10, 8), VerticalAlignment = VerticalAlignment.Center };
                Grid.SetRow(label, row);
                Grid.SetColumn(label, 0);
                root.Children.Add(label);
            }

            TextBox AddTextBox(string text, int row)
            {
                var box = new TextBox { Text = text ?? string.Empty, Margin = new Thickness(0, 4, 0, 4), Height = 28 };
                Grid.SetRow(box, row);
                Grid.SetColumn(box, 1);
                root.Children.Add(box);
                return box;
            }

            AddLabel("Bill No", 0);
            var billNoBlock = new TextBlock { Text = working.BillNo ?? string.Empty, Margin = new Thickness(0, 8, 0, 8), VerticalAlignment = VerticalAlignment.Center, FontWeight = FontWeights.SemiBold };
            Grid.SetRow(billNoBlock, 0);
            Grid.SetColumn(billNoBlock, 1);
            root.Children.Add(billNoBlock);

            AddLabel("LR No", 1);
            var lrNoBlock = new TextBlock { Text = working.LRNo ?? string.Empty, Margin = new Thickness(0, 8, 0, 8), VerticalAlignment = VerticalAlignment.Center, FontWeight = FontWeights.SemiBold };
            Grid.SetRow(lrNoBlock, 1);
            Grid.SetColumn(lrNoBlock, 1);
            root.Children.Add(lrNoBlock);

            AddLabel("Receipt Date", 2);
            var receiptDate = new DatePicker { SelectedDate = working.ReceiptDate, Margin = new Thickness(0, 4, 0, 4), Height = 28 };
            Grid.SetRow(receiptDate, 2);
            Grid.SetColumn(receiptDate, 1);
            root.Children.Add(receiptDate);

            AddLabel("Received", 3);
            var rcvdBox = AddTextBox(working.RCVD.ToString("0.##"), 3);
            AddLabel("TDS", 4);
            var tdsBox = AddTextBox(working.TDS.ToString("0.##"), 4);
            AddLabel("Ded", 5);
            var dedBox = AddTextBox(working.DED.ToString("0.##"), 5);

            AddLabel("MOP", 6);
            var mopBox = new ComboBox { Margin = new Thickness(0, 4, 0, 4), Height = 28, ItemsSource = new[] { "NEFT", "CASH", "RTGS", "IMPS", "CHEQUE", "UPI" } };
            mopBox.SelectedItem = string.IsNullOrWhiteSpace(working.MOP) ? "NEFT" : working.MOP.Trim().ToUpperInvariant();
            Grid.SetRow(mopBox, 6);
            Grid.SetColumn(mopBox, 1);
            root.Children.Add(mopBox);

            AddLabel("MR", 7);
            var mrBox = AddTextBox(working.MR, 7);
            AddLabel("Remarks", 8);
            var remarksBox = new TextBox { Text = working.Remarks ?? string.Empty, Margin = new Thickness(0, 4, 0, 4), AcceptsReturn = true, TextWrapping = TextWrapping.Wrap, MinHeight = 90 };
            Grid.SetRow(remarksBox, 8);
            Grid.SetColumn(remarksBox, 1);
            Grid.SetRowSpan(remarksBox, 2);
            root.Children.Add(remarksBox);

            var footer = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 12, 0, 0) };
            var save = new Button { Content = "Save", Width = 90, Height = 30, Margin = new Thickness(0, 0, 8, 0) };
            var cancel = new Button { Content = "Cancel", Width = 90, Height = 30 };
            footer.Children.Add(save);
            footer.Children.Add(cancel);
            Grid.SetRow(footer, 10);
            Grid.SetColumnSpan(footer, 2);
            root.Children.Add(footer);

            var saved = false;
            save.Click += (_, __) =>
            {
                var rcvd = ParseDec(rcvdBox.Text);
                var tds = ParseDec(tdsBox.Text);
                var ded = ParseDec(dedBox.Text);
                if (rcvd < 0m || tds < 0m || ded < 0m)
                {
                    MessageBox.Show("Amounts cannot be negative.", "Validation", MessageBoxButton.OK, MessageBoxImage.Warning);
                    return;
                }

                working.ReceiptDate = receiptDate.SelectedDate ?? DateTime.Today;
                working.RCVD = rcvd;
                working.TDS = tds;
                working.DED = ded;
                working.MOP = ((mopBox.SelectedItem as string) ?? "NEFT").Trim();
                working.MR = (mrBox.Text ?? string.Empty).Trim();
                working.Remarks = (remarksBox.Text ?? string.Empty).Trim();

                _billReceiptRepo.Upsert(working);
                RebuildBillReceiptState(working.BillNo);
                InvalidateBillDueCaches();
                saved = true;
                dialog.Close();
            };
            cancel.Click += (_, __) => dialog.Close();

            dialog.Content = root;
            dialog.ShowDialog();
            return saved;
        }

        private UIElement MakeSummaryTile(string label, string value, string colorHex, int column)
        {
            var container = new Border
            {
                Background = Brushes.White,
                BorderBrush = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#D8E1EE")),
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(8),
                Margin = new Thickness(0, 0, 10, 0),
                Padding = new Thickness(12, 10, 12, 10)
            };
            var stack = new StackPanel();
            stack.Children.Add(new TextBlock
            {
                Text = label,
                FontSize = 11,
                Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString(colorHex))
            });
            stack.Children.Add(new TextBlock
            {
                Text = value,
                FontSize = 16,
                FontWeight = FontWeights.Bold,
                Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString(colorHex)),
                Margin = new Thickness(0, 4, 0, 0)
            });
            container.Child = stack;
            Grid.SetColumn(container, column);
            return container;
        }

        private async void OpenPartyBillSummary_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                var dialog = new Window
                {
                    Title = "Party-wise Bill Summary",
                    Width = 860,
                    Height = 560,
                    Owner = this,
                    WindowStartupLocation = WindowStartupLocation.CenterOwner,
                    Background = new System.Windows.Media.SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#F5F7FB"))
                };

                var root = new Grid { Margin = new Thickness(14) };
                root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
                root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

                var headerCard = new Border
                {
                    Background = System.Windows.Media.Brushes.White,
                    BorderBrush = new System.Windows.Media.SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#D8E1EE")),
                    BorderThickness = new Thickness(1),
                    CornerRadius = new CornerRadius(8),
                    Padding = new Thickness(12, 10, 12, 10)
                };
                var header = new Grid();
                header.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                header.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
                var title = new TextBlock { Text = "Party-wise Due Summary", FontSize = 18, FontWeight = FontWeights.SemiBold, VerticalAlignment = VerticalAlignment.Center };
                var backBtn = new Button
                {
                    Content = "Back",
                    Width = 90,
                    Height = 30,
                    Visibility = Visibility.Collapsed,
                    Background = new System.Windows.Media.SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#1565C0")),
                    Foreground = System.Windows.Media.Brushes.White,
                    BorderThickness = new Thickness(0),
                    Cursor = Cursors.Hand
                };
                header.Children.Add(title);
                Grid.SetColumn(backBtn, 1);
                header.Children.Add(backBtn);
                headerCard.Child = header;
                Grid.SetRow(headerCard, 0);
                root.Children.Add(headerCard);

                var partyGrid = new DataGrid
                {
                    AutoGenerateColumns = false,
                    IsReadOnly = true,
                    CanUserAddRows = false,
                    Margin = new Thickness(0, 10, 0, 10),
                    Background = System.Windows.Media.Brushes.White,
                    BorderBrush = new System.Windows.Media.SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#D8E1EE")),
                    BorderThickness = new Thickness(1),
                    RowHeight = 30
                };
                partyGrid.Columns.Add(new DataGridTextColumn { Header = "Party Name", Binding = new Binding("Party"), Width = new DataGridLength(1, DataGridLengthUnitType.Star) });
                partyGrid.Columns.Add(new DataGridTextColumn { Header = "Bills", Binding = new Binding("Bills"), Width = 90 });
                partyGrid.Columns.Add(new DataGridTextColumn { Header = "Due Amount", Binding = new Binding("Due") { StringFormat = "Rs. {0:N2}" }, Width = 160 });
                Grid.SetRow(partyGrid, 1);
                root.Children.Add(partyGrid);

                var billGrid = new DataGrid
                {
                    AutoGenerateColumns = false,
                    IsReadOnly = true,
                    CanUserAddRows = false,
                    Margin = new Thickness(0, 10, 0, 10),
                    Visibility = Visibility.Collapsed,
                    Background = System.Windows.Media.Brushes.White,
                    BorderBrush = new System.Windows.Media.SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#D8E1EE")),
                    BorderThickness = new Thickness(1),
                    RowHeight = 30
                };
                billGrid.Columns.Add(new DataGridTextColumn { Header = "Bill No", Binding = new Binding("BillNo"), Width = 150 });
                billGrid.Columns.Add(new DataGridTextColumn { Header = "LR No(s)", Binding = new Binding("LRNos"), Width = new DataGridLength(1, DataGridLengthUnitType.Star) });
                billGrid.Columns.Add(new DataGridTextColumn { Header = "From", Binding = new Binding("From"), Width = 140 });
                billGrid.Columns.Add(new DataGridTextColumn { Header = "To", Binding = new Binding("To"), Width = 140 });
                billGrid.Columns.Add(new DataGridTextColumn { Header = "Due Amount", Binding = new Binding("Due") { StringFormat = "Rs. {0:N2}" }, Width = 160 });
                Grid.SetRow(billGrid, 1);
                root.Children.Add(billGrid);

                var hint = new TextBlock
                {
                    Text = "Loading party summary...",
                    Foreground = System.Windows.Media.Brushes.Gray,
                    Margin = new Thickness(0, 6, 0, 0)
                };
                Grid.SetRow(hint, 2);
                root.Children.Add(hint);

                dialog.Content = root;
                dialog.Show();

                var partyData = await Task.Run(() => GetPartyDueSummaryOptionsCached());
                partyGrid.ItemsSource = partyData;
                hint.Text = "Double-click party row to open bill details.";

                partyGrid.MouseDoubleClick += async (_, __) =>
                {
                    var selected = partyGrid.SelectedItem as PartyDueSummaryOption;
                    if (selected == null) return;
                    hint.Text = $"Loading bill details for party: {selected.Party}";
                    var details = await Task.Run(() => GetBillDueDetailsForPartyCached(selected.Party));
                    billGrid.ItemsSource = details;
                    partyGrid.Visibility = Visibility.Collapsed;
                    billGrid.Visibility = Visibility.Visible;
                    backBtn.Visibility = Visibility.Visible;
                    hint.Text = $"Bills with due for party: {selected.Party}";
                    title.Text = $"Bill-wise Due Details - {selected.Party}";
                    dialog.Title = $"Bill Details - {selected.Party}";
                };

                backBtn.Click += (_, __) =>
                {
                    billGrid.Visibility = Visibility.Collapsed;
                    partyGrid.Visibility = Visibility.Visible;
                    backBtn.Visibility = Visibility.Collapsed;
                    hint.Text = "Double-click party row to open bill details.";
                    title.Text = "Party-wise Due Summary";
                    dialog.Title = "Party-wise Bill Summary";
                };
            }
            catch (Exception ex)
            {
                MessageBox.Show("Unable to open party summary: " + ex.Message, "Error", MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }

