        private void ShowReportGridWindow<T>(string title, string subtitle, IEnumerable<T> rows, Action<DataGrid> configureGrid)
        {
            var dialog = new Window
            {
                Title = title,
                Width = 1180,
                Height = 720,
                Owner = this,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F5F7FB"))
            };

            var root = new Grid { Margin = new Thickness(14) };
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

            var header = new Border
            {
                Background = Brushes.White,
                BorderBrush = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#D8E1EE")),
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(10),
                Padding = new Thickness(14)
            };
            var headerStack = new StackPanel();
            headerStack.Children.Add(new TextBlock
            {
                Text = title,
                FontSize = 20,
                FontWeight = FontWeights.Bold,
                Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#0F172A"))
            });
            headerStack.Children.Add(new TextBlock
            {
                Text = subtitle,
                FontSize = 12,
                Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")),
                Margin = new Thickness(0, 4, 0, 0),
                TextWrapping = TextWrapping.Wrap
            });
            header.Child = headerStack;
            Grid.SetRow(header, 0);
            root.Children.Add(header);

            var grid = new DataGrid
            {
                AutoGenerateColumns = false,
                IsReadOnly = true,
                CanUserAddRows = false,
                Background = Brushes.White,
                BorderBrush = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#D8E1EE")),
                BorderThickness = new Thickness(1),
                RowHeight = 30,
                SelectionMode = DataGridSelectionMode.Single,
                SelectionUnit = DataGridSelectionUnit.FullRow,
                Margin = new Thickness(0, 12, 0, 0)
            };
            configureGrid(grid);
            grid.ItemsSource = (rows ?? Enumerable.Empty<T>()).ToList();
            Grid.SetRow(grid, 2);
            root.Children.Add(grid);

            var footer = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                HorizontalAlignment = HorizontalAlignment.Right,
                Margin = new Thickness(0, 12, 0, 0)
            };
            var closeBtn = new Button
            {
                Content = "Close",
                Width = 92,
                Height = 30,
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#334155")),
                Foreground = Brushes.White,
                BorderThickness = new Thickness(0),
                Cursor = Cursors.Hand
            };
            closeBtn.Click += (_, __) => dialog.Close();
            footer.Children.Add(closeBtn);
            Grid.SetRow(footer, 3);
            root.Children.Add(footer);

            dialog.Content = root;
            dialog.Show();
        }

        private void ApplyReceiveOnBill(string billNo, string lrNo, decimal rcvd, decimal tds, decimal ded, string mop, string mr, DateTime receivedDate, string otherRemarks)
        {
            billNo = (billNo ?? string.Empty).Trim();
            lrNo = (lrNo ?? string.Empty).Trim();
            if (billNo.Length == 0) return;

            var rows = _billRepo.GetByBillNo(billNo);
            if (rows.Count == 0) return;

            var billTotal = rows.Sum(x => x.Total);
            var currentRcvd = rows.Sum(x => x.RCVD);
            var currentTds = rows.Sum(x => x.TDS);
            var currentDed = rows.Sum(x => x.DED);
            var party = rows.Select(x => (x.Party ?? string.Empty).Trim()).FirstOrDefault(x => x.Length > 0) ?? string.Empty;
            var billDate = rows.First().BillDate;
            var dueAfter = billTotal - (currentRcvd + rcvd) - (currentTds + tds) - (currentDed + ded);

            _billReceiptRepo.Upsert(new BillReceiptEntry
            {
                BillNo = billNo,
                LRNo = lrNo,
                Party = party,
                BillTotal = billTotal,
                BillDate = billDate,
                ReceiptDate = receivedDate,
                RCVD = rcvd,
                TDS = tds,
                DED = ded,
                MOP = mop,
                MR = mr,
                Remarks = (otherRemarks ?? string.Empty).Trim(),
                DueAfter = dueAfter,
                CreatedAt = DateTime.Now
            });
            RebuildBillReceiptState(billNo);
        }

        private void RebuildBillReceiptState(string billNo)
        {
            billNo = (billNo ?? string.Empty).Trim();
            if (billNo.Length == 0) return;

            var rows = _billRepo.GetByBillNo(billNo);
            if (rows.Count == 0) return;

            var originalRowState = rows.ToDictionary(
                x => x.Id,
                x => new
                {
                    x.RCVD,
                    x.TDS,
                    x.DED,
                    x.MOP,
                    x.MR,
                    x.Date
                });

            var receipts = _billReceiptRepo.GetByBillNo(billNo)
                .OrderBy(x => x.ReceiptDate)
                .ThenBy(x => x.Id)
                .ToList();

            foreach (var row in rows)
            {
                row.RCVD = 0m;
                row.TDS = 0m;
                row.DED = 0m;
            }

            var billTotal = rows.Sum(x => x.Total);
            var runningDue = billTotal;
            foreach (var receipt in receipts)
            {
                ApplyReceiptAmountsToBillRows(rows, receipt.LRNo, receipt.RCVD, receipt.TDS, receipt.DED, receipt.MOP, receipt.MR, receipt.ReceiptDate);
                runningDue -= receipt.RCVD + receipt.TDS + receipt.DED;
                if (receipt.DueAfter != runningDue)
                {
                    receipt.DueAfter = runningDue;
                    _billReceiptRepo.Upsert(receipt);
                }
            }

            foreach (var row in rows)
            {
                if (!originalRowState.TryGetValue(row.Id, out var original) ||
                    row.RCVD != original.RCVD ||
                    row.TDS != original.TDS ||
                    row.DED != original.DED ||
                    !string.Equals((row.MOP ?? string.Empty).Trim(), (original.MOP ?? string.Empty).Trim(), StringComparison.OrdinalIgnoreCase) ||
                    !string.Equals((row.MR ?? string.Empty).Trim(), (original.MR ?? string.Empty).Trim(), StringComparison.OrdinalIgnoreCase) ||
                    row.Date != original.Date)
                {
                    _billRepo.Upsert(row);
                }
            }

            SyncLocalBillReceiptCbsEntries(billNo, receipts);
        }

        private static void ApplyReceiptAmountsToBillRows(List<BillEntry> rows, string targetLrNo, decimal rcvd, decimal tds, decimal ded, string mop, string mr, DateTime receiptDate)
        {
            if (rows == null || rows.Count == 0) return;

            var applicableRows = string.IsNullOrWhiteSpace(targetLrNo)
                ? rows
                : rows.Where(x => string.Equals((x?.LRNo ?? string.Empty).Trim(), targetLrNo.Trim(), StringComparison.OrdinalIgnoreCase)).ToList();

            if (applicableRows == null || applicableRows.Count == 0)
            {
                applicableRows = rows;
            }

            var totalBase = applicableRows.Sum(x => x.Total);
            if (totalBase <= 0m) totalBase = applicableRows.Count;

            decimal remR = rcvd, remT = tds, remD = ded;
            for (int i = 0; i < applicableRows.Count; i++)
            {
                var row = applicableRows[i];
                decimal partR, partT, partD;
                if (i == applicableRows.Count - 1)
                {
                    partR = remR;
                    partT = remT;
                    partD = remD;
                }
                else
                {
                    var ratio = applicableRows.Count == 1 ? 1m : (row.Total <= 0m ? (1m / applicableRows.Count) : (row.Total / totalBase));
                    partR = Math.Round(rcvd * ratio, 2, MidpointRounding.AwayFromZero);
                    partT = Math.Round(tds * ratio, 2, MidpointRounding.AwayFromZero);
                    partD = Math.Round(ded * ratio, 2, MidpointRounding.AwayFromZero);
                    remR -= partR;
                    remT -= partT;
                    remD -= partD;
                }

                row.RCVD += partR;
                row.TDS += partT;
                row.DED += partD;
                row.MOP = mop;
                row.MR = mr;
                row.Date = receiptDate;
            }
        }

        private void SyncLocalBillReceiptCbsEntries(string billNo, List<BillReceiptEntry> receipts)
        {
            if (BackendSettings.UseRemoteApi) return;

            AddCBSAccount("BFRS", refreshUi: false, trackUndo: false, showError: false);

            var existing = _cbsRepo.GetAll()
                .Where(x => string.Equals((x.AccountName ?? string.Empty).Trim(), "BFRS", StringComparison.OrdinalIgnoreCase))
                .Where(x =>
                {
                    var particulars = (x.Particulars ?? string.Empty).Trim();
                    return particulars.StartsWith($"Bill {billNo} - Receipt ", StringComparison.OrdinalIgnoreCase) ||
                           string.Equals(particulars, $"Bill {billNo} - Received", StringComparison.OrdinalIgnoreCase);
                })
                .ToList();

            foreach (var row in existing)
            {
                _cbsRepo.Delete(row);
            }

            foreach (var receipt in receipts.Where(x => x.RCVD != 0m))
            {
                var isCash = string.Equals((receipt.MOP ?? string.Empty).Trim(), "CASH", StringComparison.OrdinalIgnoreCase);
                _cbsRepo.Upsert(new CashBankStatementEntry
                {
                    Sr = _cbsRepo.GetMaxSr() + 1,
                    Date = receipt.ReceiptDate,
                    CBS = receipt.ReceiptDate.ToString("MMM-yy"),
                    AccountName = "BFRS",
                    Particulars = $"Bill {billNo} - Receipt {receipt.Id}",
                    Remarks = "Auto from Bill Receipt",
                    BankDr = isCash ? 0m : receipt.RCVD,
                    BankCr = 0m,
                    CashDr = isCash ? receipt.RCVD : 0m,
                    CashCr = 0m
                });
            }
        }

        private static decimal ParseDec(string text)
        {
            if (string.IsNullOrWhiteSpace(text)) return 0m;
            var t = text.Replace("Rs.", "").Replace(",", "").Trim();
            return decimal.TryParse(t, out var v) ? v : 0m;
        }

        private static string ExtractBillNoToken(string text)
        {
            var raw = (text ?? string.Empty).Trim();
            if (raw.Length == 0) return string.Empty;
            var idx = raw.IndexOf('|');
            if (idx > 0) raw = raw.Substring(0, idx).Trim();
            return raw;
        }

        private void BillUpdatePageUI()
        {
