        private bool UndoLREdit()
        {
            if (_lrUndoStack.Count == 0) return false;
            var action = _lrUndoStack.Pop();
            var entry = LRVM?.PagedEntries?.FirstOrDefault(x => x != null && x.Id == action.EntryId)
                        ?? LRVM?.Entries?.FirstOrDefault(x => x != null && x.Id == action.EntryId);
            if (entry == null) return false;

            _suppressLrHistory = true;
            try
            {
                ApplyLRSnapshot(entry, action.Before);
                new LRRepository().Upsert(entry);
                SyncLinkedBillsFromLREntry(entry);
                SyncChallanBillingForLr(entry);
                QueueDashboardRefresh();
            }
            finally
            {
                _suppressLrHistory = false;
            }

            RefreshDataGridItemsSafely(LRLedgerGrid);
            return true;
        }

        private void LedgerGrid_CellEditEnding(object sender, DataGridCellEditEndingEventArgs e)
        {
            if (e.EditAction != DataGridEditAction.Commit) return;
            var entry = e.Row.Item as ChallanEntry;
            if (entry == null || entry.Id <= 0) return;
            var bindingPath = GetColumnBindingPath(e.Column) ?? string.Empty;
            try
            {
                if (e.EditingElement is TextBox textBox)
                {
                    var binding = textBox.GetBindingExpression(TextBox.TextProperty);
                    binding?.UpdateSource();
                }
            }
            catch { }
            var beforeSnapshot = _challanEditBeforeSnapshot;
            var beforeEntryId = _challanEditEntryId;
            _challanEditBeforeSnapshot = null;
            _challanEditEntryId = -1;

            if (beforeSnapshot != null &&
                beforeEntryId == entry.Id &&
                AreChallanSnapshotsEqual(beforeSnapshot, entry))
            {
                return;
            }

            var canPersistInBackground = ChallanEditCanPersistInBackground(bindingPath) &&
                                         (!ChallanEditRequiresLinkedLrSync(bindingPath) ||
                                          string.Equals(bindingPath, "LRNumber", StringComparison.OrdinalIgnoreCase)) &&
                                         (!ChallanEditRequiresBillingSync(bindingPath) ||
                                          string.Equals(bindingPath, "LRNumber", StringComparison.OrdinalIgnoreCase)) &&
                                         !ChallanEditRequiresCbsSync(bindingPath);

            if (canPersistInBackground)
            {
                if (ChallanEditRequiresLocalMarginRefresh(bindingPath))
                {
                    RefreshChallanMarginFromCurrentValues(entry);
                }

                if (!_suppressChallanHistory &&
                    beforeSnapshot != null &&
                    beforeEntryId == entry.Id)
                {
                    var afterSnapshot = CloneChallanEntry(entry);
                    if (!AreChallanSnapshotsEqual(beforeSnapshot, afterSnapshot))
                    {
                        _challanUndoStack.Push(new ChallanEditAction
                        {
                            EntryId = entry.Id,
                            Before = beforeSnapshot,
                            After = afterSnapshot
                        });
                        _challanRedoStack.Clear();
                    }
                }

                var saveCopy = entry.CloneForPersistence();
                Task.Run(() =>
                {
                    try
                    {
                        new ChallanRepository { LedgerMode = _isChallanLedgerMode ? "Challan" : "Purchase" }.Upsert(saveCopy);
                        ChallanBillingSnapshot billingSnapshot = null;
                        if (string.Equals(bindingPath, "LRNumber", StringComparison.OrdinalIgnoreCase))
                        {
                            SyncLinkedLREntriesFromChallanBackground(saveCopy);
                            billingSnapshot = SyncSingleChallanBillingFromLRBackground(saveCopy);
                        }

                        Dispatcher.BeginInvoke(new Action(() =>
                        {
                            if (billingSnapshot != null)
                            {
                                entry.BillAmount = billingSnapshot.BillAmount;
                                entry.Margin = billingSnapshot.Margin;
                                RefreshDataGridItemsSafely(LedgerGrid);
                            }

                            RefreshTrackingAfterChallanChange();
                            QueueDashboardRefresh();
                        }));
                    }
                    catch (Exception saveEx)
                    {
                        LogException(nameof(LedgerGrid_CellEditEnding) + ".BackgroundSave", saveEx);
                        Dispatcher.BeginInvoke(new Action(() =>
                        {
                            if (beforeSnapshot != null && beforeEntryId == entry.Id)
                            {
                                ApplyChallanSnapshot(entry, beforeSnapshot);
                                RefreshDataGridItemsSafely(LedgerGrid);
                            }
                            MessageBox.Show("Unable to save challan entry: " + saveEx.Message, "Save Error", MessageBoxButton.OK, MessageBoxImage.Error);
                        }));
                    }
                });
                return;
            }

            RunAfterEditCommit(() =>
            {
                if (ChallanEditRequiresLocalMarginRefresh(bindingPath) &&
                    !ChallanEditRequiresBillingSync(bindingPath))
                {
                    RefreshChallanMarginFromCurrentValues(entry);
                }

                VM?.GetRepository().Upsert(entry);
                if (ChallanEditRequiresLinkedLrSync(bindingPath))
                {
                    SyncLinkedLREntriesFromChallan(entry);
                }
                if (ChallanEditRequiresBillingSync(bindingPath))
                {
                    SyncSingleChallanBillingFromLR(entry);
                }
                if (ChallanEditRequiresCbsSync(bindingPath))
                {
                    SyncLhsCBSFromChallan(entry.CloneForPersistence());
                    QueueCBSRefresh();
                }
                RefreshTrackingAfterChallanChange();
                QueueDashboardRefresh();

                if (!_suppressChallanHistory &&
                    beforeSnapshot != null &&
                    beforeEntryId == entry.Id)
                {
                    var after = CloneChallanEntry(entry);
                    if (!AreChallanSnapshotsEqual(beforeSnapshot, after))
                    {
                        _challanUndoStack.Push(new ChallanEditAction
                        {
                            EntryId = entry.Id,
                            Before = beforeSnapshot,
                            After = after
                        });
                        _challanRedoStack.Clear();
                    }
                }
            }, nameof(LedgerGrid_CellEditEnding));
        }
        private void LedgerGrid_Sorting(object sender, DataGridSortingEventArgs e) { e.Handled = true; var col = e.Column; string propName = (col as DataGridTextColumn)?.Binding is System.Windows.Data.Binding b ? b.Path?.Path : (col as DataGridTemplateColumn)?.SortMemberPath; if (string.IsNullOrEmpty(propName) || col.CanUserSort == false) return; bool sameColumn = VM?.GetSortColumn() == propName; bool ascending = !sameColumn || !(VM?.IsCurrentSortAscending ?? true); foreach (var c in LedgerGrid.Columns) { string h = (c.Header?.ToString() ?? "").Replace(" ^", "").Replace(" v", ""); c.Header = h; c.SortDirection = null; } col.SortDirection = ascending ? System.ComponentModel.ListSortDirection.Ascending : System.ComponentModel.ListSortDirection.Descending; col.Header = col.Header?.ToString() + (ascending ? " ^" : " v"); VM?.SetSort(propName, ascending); RefreshChallanPageAsync(); }
        private void LRLedgerGrid_SelectedCellsChanged(object sender, SelectedCellsChangedEventArgs e) { if (LRLedgerGrid.SelectedCells.Count < 2) { LRSelectedSumTextBlock.Visibility = Visibility.Collapsed; return; } decimal totalSum = 0; bool hasNumbers = false; var cache = new Dictionary<string, System.Reflection.PropertyInfo>(); foreach (var cellInfo in LRLedgerGrid.SelectedCells) { var item = cellInfo.Item; var column = cellInfo.Column as DataGridBoundColumn; if (column?.Binding is System.Windows.Data.Binding binding) { var path = binding.Path.Path; if (!cache.TryGetValue(path, out var prop)) { prop = item.GetType().GetProperty(path); cache[path] = prop; } if (prop != null) { var val = prop.GetValue(item); if (val is decimal || val is int || val is long || val is double) { totalSum += Convert.ToDecimal(val); hasNumbers = true; } } } } if (hasNumbers) { LRSelectedSumTextBlock.Text = $"Selected: Rs. {totalSum:N2}"; LRSelectedSumTextBlock.Visibility = Visibility.Visible; } else LRSelectedSumTextBlock.Visibility = Visibility.Collapsed; }
        private void LRLedgerGrid_CellEditEnding(object sender, DataGridCellEditEndingEventArgs e)
        {
