            var bindingPath = GetColumnBindingPath(e.Column) ?? string.Empty;

            try
            {
                if (e.EditingElement is TextBox textBox)
                {
                    var binding = textBox.GetBindingExpression(TextBox.TextProperty);
                    binding?.UpdateSource();
                }
            }
