        private void OpenChallanFormatPreview(ChallanEntry entry, bool challanMode)
        {
            if (entry == null) return;

            const double pageWidth = 559;
            const double pageHeight = 794;
            const double exportDpi = 180;

            var dialog = new Window
            {
                Title = $"{(challanMode ? "Challan" : "Purchase")} View - {entry.ChallanNumber}",
                Owner = this,
                Width = 760,
                Height = 900,
                MinWidth = 680,
                MinHeight = 760,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                Background = Brushes.White
            };

            var root = new Grid { Margin = new Thickness(12) };
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });

            var toolbar = new DockPanel { Margin = new Thickness(0, 0, 0, 10) };
            Grid.SetRow(toolbar, 0);

            var titleBlock = new TextBlock
            {
                Text = $"{(challanMode ? "Challan" : "Purchase")} Slip",
                FontSize = 18,
                FontWeight = FontWeights.SemiBold,
                Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#0F172A")),
                VerticalAlignment = VerticalAlignment.Center
            };
            DockPanel.SetDock(titleBlock, Dock.Left);
            toolbar.Children.Add(titleBlock);

            var buttonPanel = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                HorizontalAlignment = HorizontalAlignment.Right
            };
            DockPanel.SetDock(buttonPanel, Dock.Right);

            FrameworkElement BuildPreviewPage() => BuildChallanPrintVisual(entry, challanMode);

            var printPreviewButton = new Button
            {
                Content = "Print Preview",
                Margin = new Thickness(0, 0, 8, 0),
                Padding = new Thickness(14, 6, 14, 6),
                MinWidth = 100
            };
            printPreviewButton.Click += (_, __) =>
            {
                try
                {
                    var safeChallanNo = MakeSafeFileName(entry.ChallanNumber, "challan");
                    var tempPdf = System.IO.Path.Combine(System.IO.Path.GetTempPath(), $"Awagaman-{safeChallanNo}-{DateTime.Now:yyyyMMddHHmmss}.pdf");
                    var visual = BuildPreviewPage();
                    var bmp = RenderElementToBitmap(visual, pageWidth, pageHeight, exportDpi);
                    SaveBitmapAsPdf(bmp, tempPdf, exportDpi);
                    System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(tempPdf) { UseShellExecute = true });
                }
                catch (Exception ex)
                {
                    MessageBox.Show("Unable to open print preview: " + ex.Message, "Error", MessageBoxButton.OK, MessageBoxImage.Error);
                }
            };
            buttonPanel.Children.Add(printPreviewButton);

            var printButton = new Button
            {
                Content = "Print",
                Margin = new Thickness(0, 0, 8, 0),
                Padding = new Thickness(14, 6, 14, 6),
                MinWidth = 80
            };
            printButton.Click += (_, __) =>
            {
                try
                {
                    var printerName = ShowLegacyPrinterDialog(dialog);
                    if (string.IsNullOrWhiteSpace(printerName)) return;

                    var queue = new System.Printing.LocalPrintServer().GetPrintQueue(printerName);
                    var pd = new PrintDialog
                    {
                        PrintQueue = queue
                    };

                    var visual = BuildPreviewPage();
                    pd.PrintVisual(visual, $"{(challanMode ? "Challan" : "Purchase")} {entry.ChallanNumber}");
                    if (dialog.WindowState == WindowState.Minimized) dialog.WindowState = WindowState.Normal;
                    dialog.Activate();
                    Activate();
                }
                catch (Exception ex)
                {
                    MessageBox.Show("Unable to print: " + ex.Message, "Error", MessageBoxButton.OK, MessageBoxImage.Error);
                }
            };
            buttonPanel.Children.Add(printButton);

            var downloadButton = new Button
            {
                Content = "Download PDF",
                Margin = new Thickness(0, 0, 8, 0),
                Padding = new Thickness(14, 6, 14, 6),
                MinWidth = 110
            };
            downloadButton.Click += (_, __) =>
            {
                try
                {
                    var safeChallanNo = MakeSafeFileName(entry.ChallanNumber, "challan");
                    var sfd = new Microsoft.Win32.SaveFileDialog
                    {
                        Filter = "PDF Files|*.pdf",
                        FileName = $"{safeChallanNo}_{(challanMode ? "challan" : "purchase")}.pdf"
                    };
                    if (sfd.ShowDialog() == true)
                    {
                        var visual = BuildPreviewPage();
                        var bmp = RenderElementToBitmap(visual, pageWidth, pageHeight, exportDpi);
                        SaveBitmapAsPdf(bmp, sfd.FileName, exportDpi);
                    }
                }
                catch (Exception ex)
                {
                    MessageBox.Show("Unable to download PDF: " + ex.Message, "Error", MessageBoxButton.OK, MessageBoxImage.Error);
                }
            };
            buttonPanel.Children.Add(downloadButton);

            var closeButton = new Button
            {
                Content = "Close",
                Padding = new Thickness(14, 6, 14, 6),
                MinWidth = 80
            };
            closeButton.Click += (_, __) => dialog.Close();
            buttonPanel.Children.Add(closeButton);

            toolbar.Children.Add(buttonPanel);
            root.Children.Add(toolbar);

            var pageHost = new Border
            {
                Background = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#F8FAFC")),
                BorderBrush = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#E2E8F0")),
                BorderThickness = new Thickness(1),
                Padding = new Thickness(18)
            };
            Grid.SetRow(pageHost, 1);

            var scroll = new ScrollViewer
            {
                VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
                HorizontalScrollBarVisibility = ScrollBarVisibility.Auto
            };

            var fitView = new Viewbox
            {
                Stretch = Stretch.Uniform,
                StretchDirection = StretchDirection.DownOnly,
                Child = BuildPreviewPage()
            };

            scroll.Content = fitView;
            pageHost.Child = scroll;
            root.Children.Add(pageHost);

            dialog.Content = root;
            dialog.Show();
        }

        private FrameworkElement BuildChallanPrintVisual(ChallanEntry entry, bool challanMode)
        {
            const double pageWidth = 559;
            const double pageHeight = 794;

            var surface = new Border
            {
                Width = pageWidth,
                Height = pageHeight,
                Background = Brushes.White,
                BorderBrush = Brushes.Black,
                BorderThickness = new Thickness(1),
                Padding = new Thickness(22)
            };

            var root = new Grid();
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

            var titleGrid = new Grid { Margin = new Thickness(0, 0, 0, 10) };
            titleGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            titleGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

            var titleStack = new StackPanel();
            titleStack.Children.Add(new TextBlock
            {
                Text = challanMode ? "CHALLAN VIEW" : "PURCHASE VIEW",
                FontSize = 18,
                FontWeight = FontWeights.Bold,
                Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#111827"))
            });
            titleStack.Children.Add(new TextBlock
            {
                Text = $"Challan No.: {entry.ChallanNumber}",
                Margin = new Thickness(0, 4, 0, 0),
                FontSize = 12,
                FontWeight = FontWeights.SemiBold
            });
            Grid.SetColumn(titleStack, 0);
            titleGrid.Children.Add(titleStack);

            var dateBlock = new TextBlock
            {
                Text = $"Date: {entry.Date:dd-MMM-yyyy}",
                FontSize = 12,
                FontWeight = FontWeights.SemiBold,
                VerticalAlignment = VerticalAlignment.Top,
                HorizontalAlignment = HorizontalAlignment.Right
            };
            Grid.SetColumn(dateBlock, 1);
            titleGrid.Children.Add(dateBlock);
            root.Children.Add(titleGrid);

            Border BuildSection(string title, UIElement child, Thickness? margin = null)
            {
                var section = new Border
                {
                    BorderBrush = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#CBD5E1")),
                    BorderThickness = new Thickness(1),
                    Margin = margin ?? new Thickness(0, 0, 0, 10),
                    Padding = new Thickness(10, 8, 10, 10)
                };
                var panel = new StackPanel();
                panel.Children.Add(new TextBlock
                {
                    Text = title,
                    FontSize = 12,
                    FontWeight = FontWeights.Bold,
                    Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#1E3A8A")),
                    Margin = new Thickness(0, 0, 0, 8)
                });
                panel.Children.Add(child);
                section.Child = panel;
                return section;
            }

            Grid BuildTwoColumnDetails(params Tuple<string, string>[] items)
            {
                var grid = new Grid();
                grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                for (int i = 0; i < (items.Length + 1) / 2; i++)
                {
                    grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                }

                for (int i = 0; i < items.Length; i++)
                {
                    var row = i / 2;
                    var col = i % 2;
                    var stack = new StackPanel { Margin = new Thickness(0, 0, col == 0 ? 14 : 0, 8) };
                    stack.Children.Add(new TextBlock
                    {
                        Text = items[i].Item1,
                        FontSize = 10,
                        Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B"))
                    });
                    stack.Children.Add(new TextBlock
                    {
                        Text = string.IsNullOrWhiteSpace(items[i].Item2) ? "-" : items[i].Item2,
                        FontSize = 12,
                        FontWeight = FontWeights.SemiBold,
                        TextWrapping = TextWrapping.Wrap
                    });
                    Grid.SetRow(stack, row);
                    Grid.SetColumn(stack, col);
                    grid.Children.Add(stack);
                }

                return grid;
            }

            var tripSection = BuildSection(
                "Trip Details",
                BuildTwoColumnDetails(
                    Tuple.Create("LR Number", entry.LRNumber),
                    Tuple.Create("Broker / Agent", entry.BrokerName),
                    Tuple.Create("From", entry.From),
                    Tuple.Create("To", entry.To),
                    Tuple.Create("Vehicle No.", entry.VehicleNumber),
                    Tuple.Create("Vehicle Type", entry.VehicleType),
                    Tuple.Create("Driver Name", entry.DriverName),
                    Tuple.Create("Driver Mobile", entry.DriverMobile)
                ));
            Grid.SetRow(tripSection, 1);
            root.Children.Add(tripSection);

            var ownerSection = BuildSection(
                "Owner Details",
                BuildTwoColumnDetails(
                    Tuple.Create("Owner Name", entry.OwnerName),
                    Tuple.Create("PAN", entry.PAN),
                    Tuple.Create("Engine No.", entry.EngineNo),
                    Tuple.Create("Chassis No.", entry.ChassisNo),
                    Tuple.Create("Licence No.", entry.LicenceNo),
                    Tuple.Create("Policy No.", entry.PolicyNo)
                ));
            Grid.SetRow(ownerSection, 2);
            root.Children.Add(ownerSection);

            var settlementGrid = new Grid();
            settlementGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            settlementGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

            var settlementRows = new List<Tuple<string, decimal>>
            {
                Tuple.Create("Lorry Hire", entry.LorryHire)
            };

            if (challanMode)
            {
                settlementRows.Add(Tuple.Create("Other", entry.Other));
                settlementRows.Add(Tuple.Create("LHS", entry.LHS));
            }

            settlementRows.Add(Tuple.Create("Less TDS", entry.LessTDS));
            settlementRows.Add(Tuple.Create("Advance", entry.AdvanceAmount));
            settlementRows.Add(Tuple.Create("Detention", entry.Detention));
            settlementRows.Add(Tuple.Create("Hamali", entry.Hamali));
            settlementRows.Add(Tuple.Create("Deduction", entry.Deduction));
            settlementRows.Add(Tuple.Create("Balance Paid (NEFT)", entry.BalancePaidNEFT));
            settlementRows.Add(Tuple.Create("Balance Paid (Cash)", entry.BalancePaidCash));
            settlementRows.Add(Tuple.Create("Balance", challanMode ? entry.ChallanBalance : entry.Balance));
            settlementRows.Add(Tuple.Create("Due", challanMode ? entry.ChallanDue : entry.Due));
            settlementRows.Add(Tuple.Create("Bill Amount", entry.BillAmount));
            settlementRows.Add(Tuple.Create("Margin", challanMode ? entry.ChallanMargin : entry.Margin));

            for (int i = 0; i < settlementRows.Count; i++)
            {
                settlementGrid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var label = new TextBlock
                {
                    Text = settlementRows[i].Item1,
                    Margin = new Thickness(0, 0, 10, 5),
                    FontSize = 11,
                    FontWeight = (settlementRows[i].Item1 == "LHS" || settlementRows[i].Item1 == "Due") ? FontWeights.Bold : FontWeights.Normal
                };
                var value = new TextBlock
                {
                    Text = settlementRows[i].Item2.ToString("N2"),
                    Margin = new Thickness(0, 0, 0, 5),
                    FontSize = 11,
                    FontWeight = (settlementRows[i].Item1 == "LHS" || settlementRows[i].Item1 == "Due") ? FontWeights.Bold : FontWeights.SemiBold,
                    HorizontalAlignment = HorizontalAlignment.Right
                };
                Grid.SetRow(label, i);
                Grid.SetColumn(label, 0);
                Grid.SetRow(value, i);
                Grid.SetColumn(value, 1);
                settlementGrid.Children.Add(label);
                settlementGrid.Children.Add(value);
            }

            var settlementSection = BuildSection("Settlement", settlementGrid);
            Grid.SetRow(settlementSection, 3);
            root.Children.Add(settlementSection);

            var remarksBorder = BuildSection(
                "Remarks",
                new TextBlock
                {
                    Text = string.IsNullOrWhiteSpace(entry.Remarks) ? "-" : entry.Remarks,
                    FontSize = 11,
                    TextWrapping = TextWrapping.Wrap
                },
                new Thickness(0, 0, 0, 0));
            Grid.SetRow(remarksBorder, 4);
            root.Children.Add(remarksBorder);

            var footer = new TextBlock
            {
                Text = "Half A4 print format",
                FontSize = 10,
                Foreground = new SolidColorBrush((Color)ColorConverter.ConvertFromString("#64748B")),
                HorizontalAlignment = HorizontalAlignment.Right,
                Margin = new Thickness(0, 10, 0, 0)
            };
            Grid.SetRow(footer, 5);
            root.Children.Add(footer);

            surface.Child = root;
            return surface;
        }
        private void SyncLinkedBillsFromLREntry(LREntry entry)
        {
            if (entry == null || string.IsNullOrWhiteSpace(entry.LRNo) || string.IsNullOrWhiteSpace(entry.BillNo)) return;
            var bills = _billRepo.GetByBillNo(entry.BillNo);
            var exactEntryLrNo = (entry.LRNo ?? string.Empty).Trim();
            foreach (var bill in bills.Where(b =>
                         string.Equals((b.BillNo ?? string.Empty).Trim(), (entry.BillNo ?? string.Empty).Trim(), StringComparison.OrdinalIgnoreCase) ||
                         SplitLrNumbers(b.LRNo).Any(lr => string.Equals(lr, exactEntryLrNo, StringComparison.OrdinalIgnoreCase))))
            {
                var lrNos = SplitLrNumbers(bill.LRNo).ToList();
                if (lrNos.Count == 0 || !lrNos.Contains(exactEntryLrNo, StringComparer.OrdinalIgnoreCase)) continue;

                var matched = _lrRepo.GetByLRNumbers(lrNos);
                if (matched.Count == 0) continue;

                var newFreight = matched.Sum(x => x.TotalFreight);
                var newHml = matched.Sum(x => x.Hamali);
                var newDetention = matched.Sum(x => x.Detention);
                var newOthr = matched.Sum(x => x.Others);
                var newStCharge = matched.Sum(x => x.StCharge);
                var newRcvd = matched.Sum(x => x.NEFT + x.CASH);
                var newTds = matched.Sum(x => x.TDS);
                var newDed = matched.Sum(x => x.Ded);

                if (bill.Freight == newFreight &&
                    bill.HML == newHml &&
                    bill.Detention == newDetention &&
                    bill.OTHR == newOthr &&
                    bill.StCharge == newStCharge &&
                    bill.RCVD == newRcvd &&
                    bill.TDS == newTds &&
                    bill.DED == newDed)
                {
                    continue;
                }

                bill.Freight = newFreight;
                bill.HML = newHml;
                bill.Detention = newDetention;
                bill.OTHR = newOthr;
                bill.StCharge = newStCharge;
                bill.RCVD = newRcvd;
                bill.TDS = newTds;
                bill.DED = newDed;
                _billRepo.Upsert(bill);
            }
        }

        private void SyncAllChallanBillingFromLR(bool force = false)
        {
            if (_challanBillingSyncInProgress) return;
            if (!force && (DateTime.UtcNow - _lastChallanBillingSyncUtc).TotalMilliseconds < 800) return;
            try
            {
                _challanBillingSyncInProgress = true;
                var challanRepo = GetPurchaseChallanRepository();
                var challans = challanRepo.GetAll();
                var lrRows = _lrRepo.GetAll();
                var lrByNo = lrRows
                    .Where(x => !string.IsNullOrWhiteSpace(x.LRNo))
                    .GroupBy(x => (x.LRNo ?? string.Empty).Trim(), StringComparer.OrdinalIgnoreCase)
                    .ToDictionary(
                        g => g.Key,
                        g => g.Sum(x => x?.TotalBill ?? 0m),
                        StringComparer.OrdinalIgnoreCase);
                var lrByChNo = lrRows
                    .Where(x => !string.IsNullOrWhiteSpace(x.CHNo) && !string.IsNullOrWhiteSpace(x.LRNo))
                    .GroupBy(x => (x.CHNo ?? string.Empty).Trim(), StringComparer.OrdinalIgnoreCase)
                    .ToDictionary(g => g.Key, g => g.Select(x => (x.LRNo ?? string.Empty).Trim()).Distinct(StringComparer.OrdinalIgnoreCase).ToList(), StringComparer.OrdinalIgnoreCase);

                foreach (var ch in challans)
                {
                    if (ch.PreserveImportedBilling)
                    {
                        continue;
                    }

                    var lrSet = new HashSet<string>(SplitLrNumbers(ch.LRNumber), StringComparer.OrdinalIgnoreCase);
                    if (!string.IsNullOrWhiteSpace(ch.ChallanNumber) && lrByChNo.TryGetValue((ch.ChallanNumber ?? string.Empty).Trim(), out var listFromChNo))
                    {
                        foreach (var lrNo in listFromChNo) lrSet.Add(lrNo);
                    }

                    decimal billAmount = 0m;
                    foreach (var lrNo in lrSet)
                    {
                        if (lrByNo.TryGetValue(lrNo, out var total)) billAmount += total;
                    }
                    var margin = billAmount != 0m ? (billAmount - (ch.LHS + ch.Detention + ch.Hamali)) : 0m;
                    if (ch.BillAmount == billAmount && ch.Margin == margin)
                    {
                        continue;
                    }

                    ch.BillAmount = billAmount;
                    ch.Margin = margin;
                    challanRepo.Upsert(ch);

                    var vmEntry = VM?.PagedEntries?.FirstOrDefault(x =>
                        x.Id == ch.Id ||
                        (x.SourcePurchaseId.HasValue && x.SourcePurchaseId.Value == ch.Id) ||
                        string.Equals((x.ChallanNumber ?? string.Empty).Trim(), (ch.ChallanNumber ?? string.Empty).Trim(), StringComparison.OrdinalIgnoreCase));
                    if (vmEntry != null)
                    {
                        vmEntry.BillAmount = billAmount;
                        vmEntry.Margin = margin;
                    }
                }
                _lastChallanBillingSyncUtc = DateTime.UtcNow;
                RefreshDataGridItemsSafely(LedgerGrid);
                RefreshFilteredSummary();
                RefreshDashboard();
            }
            catch { }
            finally
            {
                _challanBillingSyncInProgress = false;
            }
        }

        private void SyncLinkedLREntriesFromChallanBackground(ChallanEntry challan)
        {
            if (challan == null) return;

            var challanNo = (challan.ChallanNumber ?? string.Empty).Trim();
            var lrTokens = SplitLrNumbers(challan.LRNumber).ToList();
            if (string.IsNullOrWhiteSpace(challanNo) && lrTokens.Count == 0) return;

            try
            {
                var set = new HashSet<string>(lrTokens, StringComparer.OrdinalIgnoreCase);
                var linkedRows = _lrRepo.GetByLRNumbers(set);
                foreach (var lr in _lrRepo.GetByChallanNumbers(new[] { challanNo }))
                {
                    if (lr != null && linkedRows.All(x => x.Id != lr.Id))
                    {
                        linkedRows.Add(lr);
                    }
                }

                foreach (var lr in linkedRows)
                {
                    if (lr == null) continue;
                    lr.From = challan.From;
                    lr.To = challan.To;
                    lr.VehicleNo = challan.VehicleNumber;
                    lr.VehicleType = challan.VehicleType;
                    lr.Broker = challan.BrokerName;
                    _lrRepo.Upsert(lr);
                }
            }
            catch { }
        }

        private ChallanBillingSnapshot SyncSingleChallanBillingFromLRBackground(ChallanEntry challan)
        {
            if (challan == null || challan.PreserveImportedBilling) return null;

            try
            {
                var challanRepo = GetPurchaseChallanRepository();
                var sourceId = challan.SourcePurchaseId ?? (challan.Id > 0 && !_isChallanLedgerMode ? (int?)challan.Id : null);
                var purchaseChallan = sourceId.HasValue
                    ? challanRepo.FindById(sourceId.Value)
                    : null;
                if (purchaseChallan == null)
                {
                    purchaseChallan = challanRepo.FindByChallanNumber(challan.ChallanNumber);
                }
                if (purchaseChallan == null)
                {
                    purchaseChallan = challan;
                }

                var lrRows = new List<LREntry>();
                if (!string.IsNullOrWhiteSpace(purchaseChallan.LRNumber))
                {
                    lrRows.AddRange(_lrRepo.GetByLRNumbers(SplitLrNumbers(purchaseChallan.LRNumber)));
                }
                if (!string.IsNullOrWhiteSpace(purchaseChallan.ChallanNumber))
                {
                    foreach (var lr in _lrRepo.GetByChallanNumbers(new[] { purchaseChallan.ChallanNumber }))
                    {
                        if (!lrRows.Any(x => x.Id == lr.Id))
                        {
                            lrRows.Add(lr);
                        }
                    }
                }

                var lrByNo = lrRows
                    .Where(x => !string.IsNullOrWhiteSpace(x.LRNo))
                    .GroupBy(x => (x.LRNo ?? string.Empty).Trim(), StringComparer.OrdinalIgnoreCase)
                    .ToDictionary(
                        g => g.Key,
                        g => g.Sum(x => x?.TotalBill ?? 0m),
                        StringComparer.OrdinalIgnoreCase);

                var lrSet = new HashSet<string>(SplitLrNumbers(purchaseChallan.LRNumber), StringComparer.OrdinalIgnoreCase);
                if (!string.IsNullOrWhiteSpace(purchaseChallan.ChallanNumber))
                {
                    foreach (var lr in lrRows)
                    {
                        if (string.Equals((lr.CHNo ?? string.Empty).Trim(), purchaseChallan.ChallanNumber.Trim(), StringComparison.OrdinalIgnoreCase) &&
                            !string.IsNullOrWhiteSpace(lr.LRNo))
                        {
                            lrSet.Add(lr.LRNo.Trim());
                        }
                    }
                }

                decimal billAmount = 0m;
                foreach (var lrNo in lrSet)
                {
                    if (lrByNo.TryGetValue(lrNo, out var total)) billAmount += total;
                }

                var margin = billAmount != 0m ? (billAmount - (purchaseChallan.LHS + purchaseChallan.Detention + purchaseChallan.Hamali)) : 0m;
                if (purchaseChallan.BillAmount != billAmount || purchaseChallan.Margin != margin)
                {
                    purchaseChallan.BillAmount = billAmount;
                    purchaseChallan.Margin = margin;
                    challanRepo.Upsert(purchaseChallan);
                }

                return new ChallanBillingSnapshot
                {
                    BillAmount = billAmount,
                    Margin = margin
                };
            }
            catch
            {
                return null;
            }
        }

        private void SyncSingleChallanBillingFromLR(ChallanEntry challan)
        {
            if (challan == null) return;
            if (challan.PreserveImportedBilling) return;
            using (EnterBusyCursor())
            {

            try
            {
                var challanRepo = GetPurchaseChallanRepository();
                var sourceId = challan.SourcePurchaseId ?? (challan.Id > 0 && !_isChallanLedgerMode ? (int?)challan.Id : null);
                var purchaseChallan = sourceId.HasValue
                    ? challanRepo.FindById(sourceId.Value)
                    : null;
                if (purchaseChallan == null)
                {
                    purchaseChallan = challanRepo.FindByChallanNumber(challan.ChallanNumber);
                }
                if (purchaseChallan == null)
                {
                    purchaseChallan = challan;
                }
                var lrRows = new List<LREntry>();
                if (!string.IsNullOrWhiteSpace(purchaseChallan.LRNumber))
                {
                    lrRows.AddRange(_lrRepo.GetByLRNumbers(SplitLrNumbers(purchaseChallan.LRNumber)));
                }
                if (!string.IsNullOrWhiteSpace(purchaseChallan.ChallanNumber))
                {
                    foreach (var lr in _lrRepo.GetByChallanNumbers(new[] { purchaseChallan.ChallanNumber }))
                    {
                        if (!lrRows.Any(x => x.Id == lr.Id))
                        {
                            lrRows.Add(lr);
                        }
                    }
                }

                var lrByNo = lrRows
                    .Where(x => !string.IsNullOrWhiteSpace(x.LRNo))
                    .GroupBy(x => (x.LRNo ?? string.Empty).Trim(), StringComparer.OrdinalIgnoreCase)
                    .ToDictionary(
                        g => g.Key,
                        g => g.Sum(x => x?.TotalBill ?? 0m),
                        StringComparer.OrdinalIgnoreCase);

                var lrSet = new HashSet<string>(SplitLrNumbers(purchaseChallan.LRNumber), StringComparer.OrdinalIgnoreCase);
                if (!string.IsNullOrWhiteSpace(purchaseChallan.ChallanNumber))
                {
                    foreach (var lr in lrRows)
                    {
                        if (string.Equals((lr.CHNo ?? string.Empty).Trim(), purchaseChallan.ChallanNumber.Trim(), StringComparison.OrdinalIgnoreCase) &&
                            !string.IsNullOrWhiteSpace(lr.LRNo))
                        {
                            lrSet.Add(lr.LRNo.Trim());
                        }
                    }
                }

                decimal billAmount = 0m;
                foreach (var lrNo in lrSet)
                {
                    if (lrByNo.TryGetValue(lrNo, out var total)) billAmount += total;
                }

                var margin = billAmount != 0m ? (billAmount - (purchaseChallan.LHS + purchaseChallan.Detention + purchaseChallan.Hamali)) : 0m;
                if (purchaseChallan.BillAmount == billAmount && purchaseChallan.Margin == margin)
                {
                    return;
                }

                purchaseChallan.BillAmount = billAmount;
                purchaseChallan.Margin = margin;
                challanRepo.Upsert(purchaseChallan);

                var vmEntry = VM?.PagedEntries?.FirstOrDefault(x =>
                    x.Id == challan.Id ||
                    x.Id == purchaseChallan.Id ||
                    (x.SourcePurchaseId.HasValue && x.SourcePurchaseId.Value == purchaseChallan.Id) ||
                    string.Equals((x.ChallanNumber ?? string.Empty).Trim(), (purchaseChallan.ChallanNumber ?? string.Empty).Trim(), StringComparison.OrdinalIgnoreCase));
                if (vmEntry != null)
                {
                    vmEntry.BillAmount = billAmount;
                    vmEntry.Margin = margin;
                }
            }
            catch { }
            }
        }

        private void SyncChallanBillingForLrs(IEnumerable<LREntry> lrEntries)
        {
            var lrList = (lrEntries ?? Enumerable.Empty<LREntry>())
                .Where(x => x != null)
                .ToList();
            if (lrList.Count == 0) return;

            try
            {
                var challanRepo = GetPurchaseChallanRepository();
                var challanNos = lrList
                    .Select(x => (x.CHNo ?? string.Empty).Trim())
                    .Where(x => !string.IsNullOrWhiteSpace(x))
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .ToList();

                var challans = challanRepo.GetByChallanNumbers(challanNos)
                    .Where(x => x != null)
                    .GroupBy(x => x.Id > 0 ? ("ID:" + x.Id) : ("NO:" + (x.ChallanNumber ?? string.Empty).Trim()), StringComparer.OrdinalIgnoreCase)
                    .Select(g => g.First())
                    .ToList();

                foreach (var challan in challans)
                {
                    SyncSingleChallanBillingFromLR(challan);
                }
            }
            catch (Exception ex)
            {
                LogException(nameof(SyncChallanBillingForLrs), ex);
            }
        }

        private void SyncChallanBillingForBillEntry(BillEntry billEntry)
        {
            if (billEntry == null) return;
            var lrNos = SplitLrNumbers(billEntry.LRNo).ToList();
            if (lrNos.Count == 0 && !string.IsNullOrWhiteSpace(billEntry.BillNo))
            {
                lrNos = _billRepo.GetByBillNo(billEntry.BillNo)
                    .SelectMany(x => SplitLrNumbers(x.LRNo))
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .ToList();
            }
            if (lrNos.Count == 0) return;
            SyncChallanBillingForLrs(_lrRepo.GetByLRNumbers(lrNos));
        }

        private void SyncChallanBillingForLr(LREntry lrEntry)
        {
            if (lrEntry == null) return;
            using (EnterBusyCursor())
            {

            try
            {
                var challanRepo = GetPurchaseChallanRepository();
                ChallanEntry challan = null;
                var chNo = (lrEntry.CHNo ?? string.Empty).Trim();
                if (!string.IsNullOrWhiteSpace(chNo))
                {
                    challan = challanRepo.FindByChallanNumber(chNo);
                }

                if (challan == null && !string.IsNullOrWhiteSpace(lrEntry.LRNo))
                {
                    var lrNo = lrEntry.LRNo.Trim();
                    challan = challanRepo.GetAll()
                        .FirstOrDefault(x => SplitLrNumbers(x.LRNumber).Any(n => string.Equals(n, lrNo, StringComparison.OrdinalIgnoreCase)));
                }

                if (challan != null)
                {
                    SyncSingleChallanBillingFromLR(challan);
                }
            }
            catch (Exception ex)
            {
                LogException(nameof(SyncChallanBillingForLr), ex);
            }
            }
        }

        private static IEnumerable<string> SplitLrNumbers(string raw)
        {
            return (raw ?? string.Empty)
                .Split(new[] { ',', ';', ' ', '\n', '\r', '\t' }, StringSplitOptions.RemoveEmptyEntries)
                .Select(x => x.Trim())
                .Where(x => !string.IsNullOrWhiteSpace(x))
                .Distinct(StringComparer.OrdinalIgnoreCase);
        }
        private void LRLedgerGrid_Sorting(object sender, DataGridSortingEventArgs e) { e.Handled = true; var col = e.Column; string propName = (col as DataGridTextColumn)?.Binding is System.Windows.Data.Binding b ? b.Path?.Path : (col as DataGridTemplateColumn)?.SortMemberPath; if (string.IsNullOrEmpty(propName) || col.CanUserSort == false) return; bool sameColumn = LRVM?.GetSortColumn() == propName; bool ascending = !sameColumn || !(LRVM?.IsCurrentSortAscending ?? true); foreach (var c in LRLedgerGrid.Columns) { string h = (c.Header?.ToString() ?? "").Replace(" ^", "").Replace(" v", ""); c.Header = h; c.SortDirection = null; } col.SortDirection = ascending ? System.ComponentModel.ListSortDirection.Ascending : System.ComponentModel.ListSortDirection.Descending; col.Header = col.Header?.ToString() + (ascending ? " ^" : " v"); LRVM?.SetSort(propName, ascending); SaveLRColumnSettings(); }
        private static string NormalizeLrKey(string value)
        {
            return new string((value ?? string.Empty).Where(c => !char.IsWhiteSpace(c)).ToArray()).Trim();
        }

        private HashSet<string> GetBilledLrNumbers()
        {
            var billed = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var bill in _billRepo.GetAll())
            {
                var raw = (bill.LRNo ?? string.Empty).Trim();
                if (string.IsNullOrWhiteSpace(raw)) continue;
                foreach (var token in SplitLrNumbers(raw))
                {
                    var key = NormalizeLrKey(token);
                    if (key.Length > 0) billed.Add(key);
                }
            }
            return billed;
        }

        private static bool IsLrBilled(string lrNo, HashSet<string> billedSet)
        {
            var key = NormalizeLrKey(lrNo);
            return key.Length > 0 && billedSet != null && billedSet.Contains(key);
        }

        private void LRLedgerGrid_PreviewMouseLeftButtonDown(object sender, MouseButtonEventArgs e)
        {
            if (IsInColumnHeaderResizeGripper(e.OriginalSource as DependencyObject)) return;
            var source = e.OriginalSource as DependencyObject;
            while (source != null && !(source is DataGridColumnHeader)) source = System.Windows.Media.VisualTreeHelper.GetParent(source);
            var header = source as DataGridColumnHeader;
            if (header?.Column == null || LRLedgerGrid == null) return;

            e.Handled = true;
            bool appendMode = (Keyboard.Modifiers & ModifierKeys.Control) == ModifierKeys.Control;
            _lrHeaderDragSelecting = true;
            _lrDragStartDisplayIndex = header.Column.DisplayIndex;
            _lrDragAppendMode = appendMode;

            SelectLRColumnsByDisplayRange(_lrDragStartDisplayIndex, _lrDragStartDisplayIndex, appendMode);
        }

        private void LRLedgerGrid_PreviewMouseMove(object sender, MouseEventArgs e)
        {
            if (!_lrHeaderDragSelecting || LRLedgerGrid == null || e.LeftButton != MouseButtonState.Pressed) return;

            var source = e.OriginalSource as DependencyObject;
            while (source != null && !(source is DataGridColumnHeader)) source = System.Windows.Media.VisualTreeHelper.GetParent(source);
            var header = source as DataGridColumnHeader;
            if (header?.Column == null || _lrDragStartDisplayIndex < 0) return;

            SelectLRColumnsByDisplayRange(_lrDragStartDisplayIndex, header.Column.DisplayIndex, _lrDragAppendMode);
            e.Handled = true;
        }

        private void LRLedgerGrid_PreviewMouseLeftButtonUp(object sender, MouseButtonEventArgs e)
        {
            _lrHeaderDragSelecting = false;
            _lrDragStartDisplayIndex = -1;
            _lrDragAppendMode = false;
        }

        private static bool IsInColumnHeaderResizeGripper(DependencyObject source)
        {
            var walker = source;
            while (walker != null)
            {
                if (walker is Thumb) return true;
                var fe = walker as FrameworkElement;
                var name = fe?.Name ?? string.Empty;
                if (name.IndexOf("Gripper", StringComparison.OrdinalIgnoreCase) >= 0) return true;
                walker = System.Windows.Media.VisualTreeHelper.GetParent(walker);
            }
            return false;
        }

        private void SelectLRColumnsByDisplayRange(int startDisplayIndex, int endDisplayIndex, bool appendMode)
        {
            if (LRLedgerGrid == null) return;
            int lo = Math.Min(startDisplayIndex, endDisplayIndex);
            int hi = Math.Max(startDisplayIndex, endDisplayIndex);

            if (!appendMode) LRLedgerGrid.UnselectAllCells();

            var cols = LRLedgerGrid.Columns
                .Where(c => c.DisplayIndex >= lo && c.DisplayIndex <= hi)
                .OrderBy(c => c.DisplayIndex)
                .ToList();

            foreach (var item in LRLedgerGrid.Items)
            {
                if (item == CollectionView.NewItemPlaceholder) continue;
                foreach (var col in cols)
                {
                    var info = new DataGridCellInfo(item, col);
                    SelectDataGridCellSafely(LRLedgerGrid, info);
                }
            }
        }

        private void LRLedgerGrid_PreviewMouseRightButtonUp(object sender, MouseButtonEventArgs e)
        {
            var source = e.OriginalSource as DependencyObject;
            DependencyObject walker = source;
            while (walker != null &&
                   !(walker is DataGridColumnHeader) &&
                   !(walker is DataGridCell) &&
                   !(walker is DataGridRowHeader) &&
                   !(walker is DataGridRow))
            {
                walker = System.Windows.Media.VisualTreeHelper.GetParent(walker);
            }
            var header = walker as DataGridColumnHeader;
            var cell = walker as DataGridCell;
            var rowHeader = walker as DataGridRowHeader;
            var row = walker as DataGridRow;
            if (header?.Column == null && cell == null && rowHeader == null && row == null) return;
            var headerName = header?.Column != null
                ? NormalizeChallanHeaderName((header.Column.Header ?? string.Empty).ToString())
                : string.Empty;

            e.Handled = true;
            var menu = new ContextMenu();
            if (header?.Column != null)
            {
                var copyCol = new MenuItem { Header = "Copy Column" };
                var colRef = header.Column;
                copyCol.Click += (_, __) => CopyColumnFromGrid(LRLedgerGrid, colRef);
                menu.Items.Add(copyCol);
                menu.Items.Add(new Separator());
                AddFreezeMenuItems(menu, LRLedgerGrid, header, SaveLRColumnSettings);
                menu.Items.Add(new Separator());
            }
            if (rowHeader != null || row != null)
            {
                if (row != null && row.Item != null && row.Item != CollectionView.NewItemPlaceholder)
                {
                    LRLedgerGrid.SelectedItems.Clear();
                    LRLedgerGrid.SelectedItems.Add(row.Item);
                }
                var copyRows = new MenuItem { Header = "Copy Row(s)" };
                copyRows.Click += (_, __) => CopySelectedRowsFromGrid(LRLedgerGrid);
                menu.Items.Add(copyRows);
                var selectedLr = (row?.Item as LREntry) ?? (LRLedgerGrid.SelectedItem as LREntry);
                if (selectedLr != null)
                {
                    var viewLr = new MenuItem { Header = "View LR Format" };
                    viewLr.Click += (_, __) => OpenLRFormatPreview(selectedLr);
                    menu.Items.Add(viewLr);
                }
                menu.IsOpen = true;
                return;
            }
            if (cell != null)
            {
                if (cell.DataContext != null) LRLedgerGrid.CurrentCell = new DataGridCellInfo(cell.DataContext, cell.Column);
                var copyCell = new MenuItem { Header = "Copy Cell" };
                copyCell.Click += (_, __) => CopyCurrentCellFromGrid(LRLedgerGrid);
                menu.Items.Add(copyCell);
                var lrEntryForView = cell.DataContext as LREntry;
                if (lrEntryForView != null)
                {
                    var viewLr = new MenuItem { Header = "View LR Format" };
                    viewLr.Click += (_, __) => OpenLRFormatPreview(lrEntryForView);
                    menu.Items.Add(viewLr);
                }

                var cellHeader = NormalizeChallanHeaderName((cell.Column?.Header ?? string.Empty).ToString());
                if (string.Equals(cellHeader, "LR No.", StringComparison.OrdinalIgnoreCase))
                {
                    var lrEntry = cell.DataContext as LREntry;
                    if (lrEntry != null)
                    {
                        var addComment = new MenuItem { Header = "View / Add Comment" };
                        addComment.Click += (_, __) => OpenLRCommentPopup(lrEntry);
                        menu.Items.Add(addComment);
                    }
                }
                menu.IsOpen = true;
                return;
            }
            if (header?.Column == null) return;

            var sortPath = (header.Column as DataGridTextColumn)?.Binding is System.Windows.Data.Binding sb
                ? sb.Path?.Path
                : (header.Column as DataGridTemplateColumn)?.SortMemberPath;
            if (string.IsNullOrWhiteSpace(sortPath)) return;

            GetLRSortLabels(sortPath, out var ascLabel, out var descLabel);
            var sortAsc = new MenuItem { Header = ascLabel };
            sortAsc.Click += (_, __) => ApplyLRSortClean(sortPath, true);
            menu.Items.Add(sortAsc);

            var sortDesc = new MenuItem { Header = descLabel };
            sortDesc.Click += (_, __) => ApplyLRSortClean(sortPath, false);
            menu.Items.Add(sortDesc);

            var clearSort = new MenuItem { Header = "Clear Sort" };
            clearSort.Click += (_, __) => ClearLRSort();
            menu.Items.Add(clearSort);

            if (!LRFilterableHeaders.Contains(headerName))
            {
                header.ContextMenu = menu;
                menu.IsOpen = true;
                return;
            }

            menu.Items.Add(new Separator());

            var values = GetLRHeaderFilterValues(headerName).ToList();
            var current = _lrHeaderFilters.TryGetValue(headerName, out var curSet)
                ? new HashSet<string>(curSet, StringComparer.OrdinalIgnoreCase)
                : new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            var selectAll = new MenuItem { Header = "Select All" };
            selectAll.Click += (_, __) =>
            {
                _lrHeaderFilters.Remove(headerName);
                ApplyLRHeaderFilter();
            };
            menu.Items.Add(selectAll);

            var clear = new MenuItem { Header = "Clear Filter" };
            clear.Click += (_, __) =>
            {
                _lrHeaderFilters.Remove(headerName);
                ApplyLRHeaderFilter();
            };
            menu.Items.Add(clear);
            menu.Items.Add(new Separator());

            var searchBox = new TextBox
            {
                Width = 180,
                Height = 24,
                Margin = new Thickness(4, 2, 4, 4),
                ToolTip = "Search values..."
            };
            var searchHost = new MenuItem
            {
                StaysOpenOnClick = true,
                Focusable = false,
                Header = searchBox
            };
            menu.Items.Add(searchHost);
            menu.Items.Add(new Separator());

            var valueItems = new List<(string Value, MenuItem Item)>();
            foreach (var v in values)
            {
                var item = new MenuItem
                {
                    Header = v,
                    IsCheckable = true,
                    StaysOpenOnClick = true,
                    IsChecked = current.Contains(v)
                };
                item.Click += (_, __) =>
                {
                    if (item.IsChecked) current.Add(v);
                    else current.Remove(v);

                    if (current.Count == 0 || current.Count == values.Count) _lrHeaderFilters.Remove(headerName);
                    else _lrHeaderFilters[headerName] = new HashSet<string>(current, StringComparer.OrdinalIgnoreCase);

                    ApplyLRHeaderFilter();
                };
                menu.Items.Add(item);
                valueItems.Add((v, item));
            }

            searchBox.TextChanged += (_, __) =>
            {
                var text = (searchBox.Text ?? string.Empty).Trim();
                foreach (var pair in valueItems)
                {
                    pair.Item.Visibility = string.IsNullOrWhiteSpace(text) || pair.Value.IndexOf(text, StringComparison.OrdinalIgnoreCase) >= 0
                        ? Visibility.Visible
                        : Visibility.Collapsed;
                }
            };
            menu.Opened += (_, __) => searchBox.Focus();

            header.ContextMenu = menu;
            menu.IsOpen = true;
        }

        private void ApplyLRSort(string propName, bool ascending)
        {
            if (LRLedgerGrid == null || LRVM == null || string.IsNullOrWhiteSpace(propName)) return;

            foreach (var c in LRLedgerGrid.Columns)
            {
                c.Header = NormalizeHeaderForSort(c.Header?.ToString() ?? string.Empty);
                c.SortDirection = null;
            }

            var target = LRLedgerGrid.Columns.FirstOrDefault(c =>
            {
                var p = (c as DataGridTextColumn)?.Binding is System.Windows.Data.Binding b ? b.Path?.Path : (c as DataGridTemplateColumn)?.SortMemberPath;
                return string.Equals(p, propName, StringComparison.OrdinalIgnoreCase);
            });

            if (target != null)
            {
                target.SortDirection = ascending ? ListSortDirection.Ascending : ListSortDirection.Descending;
                var clean = NormalizeChallanHeaderName(target.Header?.ToString() ?? string.Empty);
                target.Header = clean + (ascending ? " ^" : " v");
            }

            LRVM.SetSort(propName, ascending);
            SaveLRColumnSettings();
        }

        private static void GetLRSortLabels(string propName, out string ascLabel, out string descLabel)
        {
            var key = (propName ?? string.Empty).Trim().ToLowerInvariant();

            if (key == "date" || key == "billdate")
            {
                ascLabel = "Sort Oldest to Newest";
                descLabel = "Sort Newest to Oldest";
                return;
            }

            if (key == "lrno" || key == "sr" || key == "pkg" || key == "sizel" || key == "sizew" || key == "sizeh" ||
                key == "actualweight" || key == "chargedweight" || key == "totalfreight" || key == "hamali" ||
                key == "detention" || key == "others" || key == "stcharge" || key == "totalbill" ||
                key == "neft" || key == "cash" || key == "tds" || key == "ded" || key == "bal" ||
                key == "comm")
            {
                ascLabel = "Sort Smallest to Largest";
                descLabel = "Sort Largest to Smallest";
                return;
            }

            ascLabel = "Sort A to Z";
            descLabel = "Sort Z to A";
        }

        private void ApplyLRSortClean(string propName, bool ascending)
        {
            if (LRLedgerGrid == null || LRVM == null || string.IsNullOrWhiteSpace(propName)) return;

            foreach (var c in LRLedgerGrid.Columns)
            {
                c.Header = NormalizeHeaderForSort(c.Header?.ToString() ?? string.Empty);
                c.SortDirection = null;
            }

            var target = LRLedgerGrid.Columns.FirstOrDefault(c =>
            {
                var p = (c as DataGridTextColumn)?.Binding is Binding b ? b.Path?.Path : (c as DataGridTemplateColumn)?.SortMemberPath;
                return string.Equals(p, propName, StringComparison.OrdinalIgnoreCase);
            });

            if (target != null)
            {
                target.SortDirection = ascending ? ListSortDirection.Ascending : ListSortDirection.Descending;
                target.Header = NormalizeHeaderForSort(target.Header?.ToString() ?? string.Empty) + (ascending ? " ^" : " v");
            }

            LRVM.SetSort(propName, ascending);
            SaveLRColumnSettings();
        }

        private static string NormalizeHeaderForSort(string header)
        {
            var h = (header ?? string.Empty).Trim();
            return h.Replace(" \u25B2", string.Empty)
                    .Replace(" \u25BC", string.Empty)
                    .Replace(" ^", string.Empty)
                    .Replace(" v", string.Empty)
                    .Trim();
        }

        private void ClearLRSort()
        {
            if (LRLedgerGrid == null || LRVM == null) return;

            foreach (var c in LRLedgerGrid.Columns)
            {
                c.Header = NormalizeChallanHeaderName(c.Header?.ToString() ?? string.Empty);
                c.SortDirection = null;
            }

            LRVM.SetSort(string.Empty, true);
            SaveLRColumnSettings();
        }

        private static readonly HashSet<string> LRFilterableHeaders = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
        {
            "LR No.", "Date", "Consignor Name", "Consignee Name", "From", "To", "Vehicle No.", "Type",
            "L", "W", "H", "Actual Weight", "Charged Weight", "No. of Pkg", "Pkg Type", "DESCRIPTION", "Invoice", "Value", "CH No.", "Total Freight", "Hamali", "Detention",
            "Others", "St. Charge", "Total Bill", "Bill No.", "Bill Date", "Bill Party", "Broker", "Frt Type", "To Pay/To Be Billed", "comm", "Paid"
        };

        private IEnumerable<string> GetLRHeaderFilterValues(string headerName)
        {
            var rows = (LRVM?.PagedEntries ?? new System.Collections.ObjectModel.ObservableCollection<LREntry>()).Where(x => x != null);
            return rows.Select(x => GetLRHeaderCellValue(x, headerName))
                .Where(x => !string.IsNullOrWhiteSpace(x))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(x => x);
        }

        private string GetLRHeaderCellValue(LREntry entry, string headerName)
        {
            if (entry == null) return string.Empty;
            switch (headerName)
            {
                case "LR No.": return (entry.LRNo ?? string.Empty).Trim();
                case "Date": return entry.Date.ToString("dd-MMM-yyyy");
                case "Consignor Name": return (entry.ConsignorName ?? string.Empty).Trim();
                case "Consignee Name": return (entry.ConsigneeName ?? string.Empty).Trim();
                case "From": return (entry.From ?? string.Empty).Trim();
                case "To": return (entry.To ?? string.Empty).Trim();
                case "Vehicle No.": return (entry.VehicleNo ?? string.Empty).Trim();
                case "Type": return (entry.VehicleType ?? string.Empty).Trim();
                case "L": return entry.SizeL.ToString("0.####################");
                case "W": return entry.SizeW.ToString("0.####################");
                case "H": return entry.SizeH.ToString("0.####################");
                case "Actual Weight": return entry.ActualWeight.ToString("0.####################");
                case "Charged Weight": return entry.ChargedWeight.ToString("0.####################");
                case "No. of Pkg": return entry.PKG.ToString();
                case "Pkg Type": return (entry.PkgType ?? string.Empty).Trim();
                case "DESCRIPTION": return (entry.Description ?? string.Empty).Trim();
                case "Invoice": return (entry.Invoice ?? string.Empty).Trim();
                case "Value": return (entry.Value ?? string.Empty).Trim();
                case "CH No.": return (entry.CHNo ?? string.Empty).Trim();
                case "Total Freight": return entry.TotalFreight.ToString("N2");
                case "Hamali": return entry.Hamali.ToString("N2");
                case "Detention": return entry.Detention.ToString("N2");
                case "Others": return entry.Others.ToString("N2");
                case "St. Charge": return entry.StCharge.ToString("N2");
                case "Total Bill": return entry.TotalBill.ToString("N2");
                case "Bill No.": return (entry.BillNo ?? string.Empty).Trim();
                case "Bill Date": return entry.BillDate.HasValue ? entry.BillDate.Value.ToString("dd-MMM-yyyy") : string.Empty;
                case "Bill Party": return (entry.BillParty ?? string.Empty).Trim();
                case "Broker": return (entry.Broker ?? string.Empty).Trim();
                case "Frt Type": return (entry.FrtType ?? string.Empty).Trim();
                case "To Pay/To Be Billed": return (entry.PayType ?? string.Empty).Trim();
                case "comm": return entry.Comm.ToString("N2");
                case "Paid": return (entry.Paid ?? string.Empty).Trim();
                default: return string.Empty;
            }
        }

        private void ApplyLRHeaderFilter()
        {
            if (LRLedgerGrid == null) return;

            var cv = CollectionViewSource.GetDefaultView(LRLedgerGrid.ItemsSource);
            if (cv == null) return;

            if (_lrHeaderFilters.Count > 0)
            {
                cv.Filter = obj =>
                {
                    var entry = obj as LREntry;
                    if (entry == null) return false;

                    foreach (var kv in _lrHeaderFilters)
                    {
                        if (kv.Value == null || kv.Value.Count == 0) continue;
                        var value = GetLRHeaderCellValue(entry, kv.Key);
                        if (!kv.Value.Contains(value)) return false;
                    }
                    return true;
                };
            }
            else cv.Filter = null;

            RefreshCollectionViewSafely(cv);
            ApplyLRHeaderFilterIndicators();
            UpdateLRVisibleSummaryFromView(cv);
        }

        private void ApplyLRHeaderFilterIndicators()
        {
            if (LRLedgerGrid == null) return;
            if (_lrFilteredHeaderStyle == null)
            {
                var baseStyle = FindResource("DataGridHeaderStyle") as Style;
                _lrFilteredHeaderStyle = new Style(typeof(DataGridColumnHeader), baseStyle);
                _lrFilteredHeaderStyle.Setters.Add(new Setter(Control.BackgroundProperty, new System.Windows.Media.SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString("#E65100"))));
                _lrFilteredHeaderStyle.Setters.Add(new Setter(Control.ForegroundProperty, System.Windows.Media.Brushes.White));
            }

            foreach (var col in LRLedgerGrid.Columns)
            {
                var headerName = NormalizeChallanHeaderName((col.Header ?? string.Empty).ToString()).Trim();
                var hasFilter = _lrHeaderFilters.TryGetValue(headerName, out var selectedSet) && selectedSet != null && selectedSet.Count > 0;
                col.HeaderStyle = hasFilter ? _lrFilteredHeaderStyle : null;
            }
        }

        private void UpdateLRVisibleSummaryFromView(ICollectionView cv)
        {
            if (LRVM == null || cv == null) return;
            LRRefreshFilteredSummary();
        }

