        private void OpenChallanForm_Click(object sender, RoutedEventArgs e) { OpenChallanForm(); }
        private void OpenChallanForm()
        {
            var challanRepository = GetActiveChallanRepository();
            var form = new ChallanFormWindow(VM.Entries, challanRepository);
            form.Owner = this;
            form.Closed += (_, __) =>
            {
                if (!form.WasSaved) return;

                try
                {
                    var entry = form.Result;
                    if (entry == null) return;

                    entry.Sr = VM.GetNextSr();
                    entry.RecalculateBalance();
                    var saveEntry = entry.CloneForPersistence();
                    challanRepository.LedgerMode = _isChallanLedgerMode ? "Challan" : "Purchase";
                    var uiDispatcher = Dispatcher;
                    var useRemoteApi = BackendSettings.UseRemoteApi;

                    if (useRemoteApi)
                    {
                        VM.AcceptSavedEntry(entry);
                        UpdatePageUI();
                        QueueDashboardRefresh();
                    }

                    Task.Run(() =>
                    {
                        try
                        {
                            challanRepository.Upsert(saveEntry);
                        }
                        catch (Exception saveEx)
                        {
                            LogException("OpenChallanForm Save", saveEx);
                            uiDispatcher.BeginInvoke(new Action(() =>
                            {
                                if (useRemoteApi)
                                {
                                    VM.RemoveOptimisticEntry(entry);
                                    UpdatePageUI();
                                    QueueDashboardRefresh();
                                }
                                MessageBox.Show("Unable to save challan entry: " + saveEx.Message, "Save Error", MessageBoxButton.OK, MessageBoxImage.Error);
                            }));
                            return;
                        }

                        uiDispatcher.BeginInvoke(new Action(() =>
                        {
                            try
                            {
                                entry.Id = saveEntry.Id;
                                if (!useRemoteApi)
                                {
                                    VM.AcceptSavedEntry(entry);
                                    UpdatePageUI();
                                    QueueDashboardRefresh();
                                }
                                MessageBox.Show($"Challan created: {entry.ChallanNumber}", "Success", MessageBoxButton.OK, MessageBoxImage.Information);
                            }
                            catch (Exception refreshEx)
                            {
                                LogException("OpenChallanForm LocalRefresh", refreshEx);
                            }
                        }));

                        if (!string.IsNullOrWhiteSpace(saveEntry.LRNumber))
                        {
                            try { SyncSingleChallanBillingFromLR(saveEntry); }
                            catch (Exception syncEx) { LogException("OpenChallanForm BillingSync", syncEx); }
                        }

                        SyncLhsCBSFromChallan(saveEntry);
                        QueueCBSRefresh();
                        QueueDashboardRefresh();

                        uiDispatcher.BeginInvoke(new Action(RefreshTrackingAfterChallanChange));
                    });
                }
                catch (Exception ex)
                {
                    MessageBox.Show("Unable to save challan entry: " + ex.Message, "Save Error", MessageBoxButton.OK, MessageBoxImage.Error);
                }
            };
            form.Show();
        }
        private void ResetAllData_Click(object sender, RoutedEventArgs e)
        {
            if (!EnsureAdminAccess("Reset data")) return;
            InvalidateBillDueCaches();
            if (LRLedgerView != null && LRLedgerView.Visibility == Visibility.Visible)
            {
                ResetLRDataOnly();
                return;
            }

            if (BillLedgerView != null && BillLedgerView.Visibility == Visibility.Visible)
            {
                ResetBillDataOnly();
                return;
            }

            var first = MessageBox.Show(
                "This will permanently delete all data from Challan, LR, Tracking, Bill, CBS, Vehicle, Party and comments.\n\nDo you want to continue?",
                "Reset All Data",
                MessageBoxButton.YesNo,
                MessageBoxImage.Warning);
            if (first != MessageBoxResult.Yes) return;

            var second = MessageBox.Show(
                "Final confirmation:\n\nThis action cannot be undone.\nDelete all ledger data now?",
                "Confirm Delete",
                MessageBoxButton.YesNo,
                MessageBoxImage.Stop);
            if (second != MessageBoxResult.Yes) return;

            try
            {
                if (BackendSettings.UseRemoteApi)
                {
                    RemoteApiClient.PostNoContent("api/admin/reset-all");
                }
                else
                {
                    foreach (var entry in _billRepo.GetAll()) _billRepo.Delete(entry);
                    foreach (var entry in _lrRepo.GetAll()) _lrRepo.Delete(entry);
                    foreach (var entry in _challanRepo.GetAll()) _challanRepo.Delete(entry);
                    foreach (var entry in _cbsRepo.GetAll()) _cbsRepo.Delete(entry);
                    foreach (var entry in _partyRepo.GetAll()) _partyRepo.Delete(entry);
                    foreach (var entry in _vehicleRepo.GetAll()) _vehicleRepo.Delete(entry);
                    foreach (var entry in _trackingRepo.GetAll()) _trackingRepo.Delete(entry);
                    foreach (var entry in _billReceiptRepo.GetAll()) _billReceiptRepo.Delete(entry);
                }

                VM?.RefreshAfterDelete();
                LRVM?.RefreshAfterDelete();
                BillVM?.RefreshAfterDelete();
                TrackingVM = new TrackingViewModel(loadOnStartup: false);
                if (TrackingLedgerView != null) TrackingLedgerView.DataContext = TrackingVM;
                if (TrackingLedgerGrid != null) TrackingLedgerGrid.ItemsSource = TrackingVM.Entries;

                RefreshFilteredSummary();
                LRRefreshFilteredSummary();
                BillUpdatePageUI();
                RefreshDashboard();
                RefreshCBSAccounts();
                RefreshCBSGrid();

                MessageBox.Show("All ledger data has been deleted.", "Reset Completed", MessageBoxButton.OK, MessageBoxImage.Information);
            }
            catch (Exception ex)
            {
                MessageBox.Show("Reset failed: " + ex.Message, "Error", MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }

        private void ResetLRDataOnly()
        {
            if (!EnsureAdminAccess("Reset LR ledger")) return;
            var first = MessageBox.Show(
                "This will permanently delete LR ledger data only.\n\nChallan, Purchase, Bill, Tracking, CBS, Vehicle and Party data will remain unchanged.\n\nDo you want to continue?",
                "Reset LR Ledger",
                MessageBoxButton.YesNo,
                MessageBoxImage.Warning);
            if (first != MessageBoxResult.Yes) return;

            var second = MessageBox.Show(
                "Final confirmation:\n\nDelete all LR ledger rows now?",
                "Confirm LR Delete",
                MessageBoxButton.YesNo,
                MessageBoxImage.Stop);
            if (second != MessageBoxResult.Yes) return;

            try
            {
                if (BackendSettings.UseRemoteApi)
                {
                    RemoteApiClient.PostNoContent("api/lr/reset-all");
                }
                else
                {
                    foreach (var entry in _lrRepo.GetAll()) _lrRepo.Delete(entry);
                }

                LRVM?.RefreshAfterDelete();
                LRUpdatePageUI();
                RefreshDashboard();

                MessageBox.Show("LR ledger data has been deleted.", "LR Reset Completed", MessageBoxButton.OK, MessageBoxImage.Information);
            }
            catch (Exception ex)
            {
                MessageBox.Show("LR reset failed: " + ex.Message, "Error", MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }

        private void ResetBillDataOnly()
        {
            if (!EnsureAdminAccess("Reset bill ledger")) return;
            InvalidateBillDueCaches();
            var first = MessageBox.Show(
                "This will permanently delete Bill ledger data only.\n\nBill receipts and bill comments will also be deleted.\n\nChallan, Purchase, LR, Tracking, CBS, Vehicle and Party data will remain unchanged.\n\nDo you want to continue?",
                "Reset Bill Ledger",
                MessageBoxButton.YesNo,
                MessageBoxImage.Warning);
            if (first != MessageBoxResult.Yes) return;

            var second = MessageBox.Show(
                "Final confirmation:\n\nDelete all Bill ledger rows now?",
                "Confirm Bill Delete",
                MessageBoxButton.YesNo,
                MessageBoxImage.Stop);
            if (second != MessageBoxResult.Yes) return;

            try
            {
                if (BackendSettings.UseRemoteApi)
                {
                    RemoteApiClient.PostNoContent("api/bills/reset-all");
                }
                else
                {
                    foreach (var entry in _billReceiptRepo.GetAll()) _billReceiptRepo.Delete(entry);
                    foreach (var entry in _billRepo.GetAll()) _billRepo.Delete(entry);
                    new CommentRepository().DeleteAllBillComments();
                }

                BillVM?.RefreshAfterDelete();
                BillUpdatePageUI();
                RefreshDashboard();

                MessageBox.Show("Bill ledger data has been deleted.", "Bill Reset Completed", MessageBoxButton.OK, MessageBoxImage.Information);
            }
            catch (Exception ex)
            {
                MessageBox.Show("Bill reset failed: " + ex.Message, "Error", MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }
