        private void EnforceLRLockedColumnsReadOnly()
        {
            if (LRLedgerGrid == null) return;
            foreach (var col in LRLedgerGrid.Columns)
            {
                var h = NormalizeHeaderForSort((col.Header ?? string.Empty).ToString());
                if (string.Equals(h, "From", StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(h, "To", StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(h, "Vehicle No.", StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(h, "Type", StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(h, "CH No.", StringComparison.OrdinalIgnoreCase))
                {
                    col.IsReadOnly = true;
                }
            }
        }
        private void EnsureLRColumnVisible(string headerName, double minWidth)
        {
            if (LRLedgerGrid == null || string.IsNullOrWhiteSpace(headerName)) return;
            foreach (var col in LRLedgerGrid.Columns)
            {
                var h = (col.Header?.ToString() ?? "").Replace(" ^", "").Replace(" v", "").Trim();
                if (!string.Equals(h, headerName, StringComparison.OrdinalIgnoreCase)) continue;
                col.Visibility = Visibility.Visible;
                if (col.Width.DisplayValue < minWidth) col.Width = new DataGridLength(minWidth);
                break;
            }
        }
        private void ShowPurchaseLedger(Button activeTab, string pageTitle)
        {
            using (EnterBusyCursor())
            {
            _isChallanLedgerMode = ReferenceEquals(activeTab, TabChallan);
            HideUtilityViews();
            DashboardView.Visibility = Visibility.Collapsed;
            LRLedgerView.Visibility = Visibility.Collapsed;
            DeliveryChallanView.Visibility = Visibility.Visible;
            TrackingLedgerView.Visibility = Visibility.Collapsed;
            PartyLedgerView.Visibility = Visibility.Collapsed;
            BillLedgerView.Visibility = Visibility.Collapsed;
            VehicleLedgerView.Visibility = Visibility.Collapsed;
            CBSLedgerView.Visibility = Visibility.Collapsed;
            TabDeliveryChallans.Style = ReferenceEquals(activeTab, TabDeliveryChallans)
                ? (Style)FindResource("ActiveTabButtonStyle")
                : (Style)FindResource("TabButtonStyle");
            TabChallan.Style = ReferenceEquals(activeTab, TabChallan)
                ? (Style)FindResource("ActiveTabButtonStyle")
                : (Style)FindResource("TabButtonStyle");
            TabDashboard.Style = (Style)FindResource("TabButtonStyle");
            TabLRLedger.Style = (Style)FindResource("TabButtonStyle");
            TabTrackingLedger.Style = (Style)FindResource("TabButtonStyle");
            TabPartyLedger.Style = (Style)FindResource("TabButtonStyle");
            TabBillLedger.Style = (Style)FindResource("TabButtonStyle");
            TabVehicleLedger.Style = (Style)FindResource("TabButtonStyle");
            TabCBSLedger.Style = (Style)FindResource("TabButtonStyle");
            if (PageTitle != null) PageTitle.Text = pageTitle;
            ApplyPurchaseChallanMode();
            VM?.ResetToLatestChallanView();

            if (LedgerGrid != null)
            {
                var cv = CollectionViewSource.GetDefaultView(LedgerGrid.ItemsSource);
                cv?.SortDescriptions.Clear();
                LedgerGrid.FrozenColumnCount = Math.Max(0, Math.Min(VM?.FrozenColumnCount ?? 0, LedgerGrid.Columns.Count));
            }

            if (BackendSettings.UseRemoteApi)
            {
                if (!VM.HasLoadedPage && RecordCountText != null)
                    RecordCountText.Text = "Loading challans...";

                BeginBusyCursor();
                VM.EnsurePageLoadedAsync(
                    () =>
                    {
                        UpdatePageUI(applyGridFilter: _onlyDueFilterEnabled || _challanHeaderFilters.Count > 0);
                        EndBusyCursor();
                    },
                    ex =>
                    {
                        AppLogger.LogException(nameof(OpenDeliveryChallans_Click), ex);
                        if (RecordCountText != null) RecordCountText.Text = "Unable to load challans";
                        EndBusyCursor();
                    });
                return;
            }

            VM.EnsurePageLoaded();
            UpdatePageUI(applyGridFilter: _onlyDueFilterEnabled || _challanHeaderFilters.Count > 0);
            }
        }

        private void ApplyPurchaseChallanMode()
        {
            _challanRepo.LedgerMode = _isChallanLedgerMode ? "Challan" : "Purchase";

            if (CreatePurchaseButton != null)
            {
                CreatePurchaseButton.Visibility = _isChallanLedgerMode ? Visibility.Collapsed : Visibility.Visible;
            }

            if (ChallanDeleteButton != null)
            {
                ChallanDeleteButton.Visibility = IsOperatorRestricted() || _isChallanLedgerMode ? Visibility.Collapsed : Visibility.Visible;
            }

            if (VM != null)
            {
                VM.LedgerMode = _isChallanLedgerMode ? "Challan" : "Purchase";
                VM.UseLhsDerivedValues = _isChallanLedgerMode;
                VM.ShowOther = _isChallanLedgerMode;
                VM.ShowLHS = _isChallanLedgerMode;
            }

            if (LedgerGrid != null)
            {
                LedgerGrid.FrozenColumnCount = Math.Max(0, Math.Min(VM?.FrozenColumnCount ?? 0, LedgerGrid.Columns.Count));
            }

            if (ChallanBalanceColumn != null)
            {
                ChallanBalanceColumn.Binding = new Binding(_isChallanLedgerMode ? "ChallanBalance" : "Balance")
                {
                    StringFormat = "N2"
                };
            }

            if (ChallanDueColumn != null)
            {
                ChallanDueColumn.Binding = new Binding(_isChallanLedgerMode ? "ChallanDue" : "Due")
                {
                    StringFormat = "N2"
                };
            }

            if (ChallanMarginColumn != null)
            {
                ChallanMarginColumn.Binding = new Binding(_isChallanLedgerMode ? "ChallanMargin" : "Margin");
            }

            UpdateColumnVisibility();
            RefreshChallanSummaryText();
            if (LedgerGrid != null)
                LedgerGrid.Items.Refresh();
        }
