        private void EditSelected_Click(object sender, RoutedEventArgs e)
        {
            var item = LedgerGrid.SelectedItem as ChallanEntry;
            if (item == null) return;

            var challanRepository = GetActiveChallanRepository();
            var form = new ChallanFormWindow(item, VM.Entries, challanRepository);
            form.Owner = this;
            form.Closed += (_, __) =>
            {
                if (!form.WasSaved) return;

                try
                {
                    var updated = form.Result;
                    if (updated == null) return;

                    updated.HasComments = item.HasComments;
                    updated.CommentPreview = item.CommentPreview;
                    updated.RecalculateBalance();
                    challanRepository.LedgerMode = _isChallanLedgerMode ? "Challan" : "Purchase";
                    var beforeSnapshot = CloneChallanEntry(item);
                    ApplyChallanSnapshot(item, updated);
                    RefreshDataGridItemsSafely(LedgerGrid);
                    QueueDashboardRefresh();

                    var saveCopy = item.CloneForPersistence();
                    var uiDispatcher = Dispatcher;
                    Task.Run(() =>
                    {
                        try
                        {
                            challanRepository.Upsert(saveCopy);

                            SyncLinkedLREntriesFromChallanBackground(saveCopy);
                            var billingSnapshot = SyncSingleChallanBillingFromLRBackground(saveCopy);
                            SyncLhsCBSFromChallan(saveCopy);

                            uiDispatcher.BeginInvoke(new Action(() =>
                            {
                                if (billingSnapshot != null)
                                {
                                    item.BillAmount = billingSnapshot.BillAmount;
                                    item.Margin = billingSnapshot.Margin;
                                }

                                RefreshTrackingAfterChallanChange();
                                QueueCBSRefresh();
                                QueueDashboardRefresh();
                                RefreshDataGridItemsSafely(LedgerGrid);
                            }));
                        }
                        catch (Exception saveEx)
                        {
                            LogException(nameof(EditSelected_Click) + ".BackgroundSave", saveEx);
                            uiDispatcher.BeginInvoke(new Action(() =>
                            {
                                ApplyChallanSnapshot(item, beforeSnapshot);
                                RefreshDataGridItemsSafely(LedgerGrid);
                                MessageBox.Show("Unable to update challan entry: " + saveEx.Message, "Save Error", MessageBoxButton.OK, MessageBoxImage.Error);
                            }));
                        }
                    });
                }
                catch (Exception ex)
                {
                    MessageBox.Show("Unable to update challan entry: " + ex.Message, "Save Error", MessageBoxButton.OK, MessageBoxImage.Error);
                }
            };
            form.Show();
        }
        private void MakeBuilty_Click(object sender, RoutedEventArgs e)
        {
            var item = LedgerGrid.SelectedItem as ChallanEntry;
            if (item == null)
            {
                MessageBox.Show("Select a Challan entry first.", "No Selection", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }
            if (!string.IsNullOrWhiteSpace(item.LRNumber))
            {
                var result = MessageBox.Show($"Challan '{item.ChallanNumber}' already has LR No. '{item.LRNumber}'.\nCreate another LR?", "LR Exists", MessageBoxButton.YesNo, MessageBoxImage.Question);
                if (result != MessageBoxResult.Yes) return;
            }

            OpenLRFormFromChallan(item);
        }
        private async void DeleteSelected_Click(object sender, RoutedEventArgs e)
        {
            if (!EnsureAdminAccess("Delete challan entries")) return;
            if (_isChallanLedgerMode)
            {
                MessageBox.Show("Delete challans from Purchase Ledger only.", "Use Purchase Ledger", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            if (LedgerGrid == null) return;
            var selected = LedgerGrid.SelectedItems.Cast<ChallanEntry>().ToList();
            if (selected.Count == 0)
            {
                MessageBox.Show("Select Challan entries to delete.", "No Selection", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            if (MessageBox.Show($"Delete {selected.Count} challan entr{(selected.Count == 1 ? "y" : "ies")}?", "Confirm", MessageBoxButton.YesNo, MessageBoxImage.Question) != MessageBoxResult.Yes)
            {
                return;
            }

            var challanRepository = GetActiveChallanRepository();
            foreach (var entry in selected)
            {
                VM?.RemoveOptimisticEntry(entry);
            }
            UpdatePageUI(applyGridFilter: _onlyDueFilterEnabled || _challanHeaderFilters.Count > 0);

            BeginBusyCursor();
            try
            {
                await Task.Run(() =>
                {
                    foreach (var entry in selected)
                    {
                        try
                        {
                            challanRepository.Delete(entry);
                            DeleteTrackingRowsForChallan(entry);
                        }
                        catch { }
                    }
                });

                TrackingVM?.LoadData();
                RefreshTrackingReminderFromCurrentEntries();
                RefreshFilteredSummary();
                QueueDashboardRefresh();
            }
            catch (Exception ex)
            {
                VM?.RefreshAfterDelete();
                UpdatePageUI(applyGridFilter: _onlyDueFilterEnabled || _challanHeaderFilters.Count > 0);
                MessageBox.Show("Challan delete failed: " + ex.Message, "Error", MessageBoxButton.OK, MessageBoxImage.Error);
            }
            finally
            {
                EndBusyCursor();
            }
        }

        private void DeleteTrackingRowsForChallan(ChallanEntry entry)
        {
            var challanNo = (entry?.ChallanNumber ?? string.Empty).Trim();
            if (challanNo.Length == 0)
            {
                return;
            }

            _trackingRepo.DeleteByChallanNo(challanNo);
        }
